INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (15867,3,1,'၁။ ပထမမွန်သရ။',NULL)
,(15867,3,1,'၂။ သုံးဆယ့်လေးလုံးမြောက်မွန်ဗျည်း။',NULL)
,(15868,3,4,'အသည်။ စကားမပီမသဖြစ်သည်။',NULL)
,(15869,3,9,'(ကြိရှေ့ဆက်) ကြိယာရှေ့­ ‘အ’ ဆက်ခြင်းအားဖြင့် ကြိယာပုဒ်မှ နာမ်ပုဒ်ဖြစ်လာစေသည်။ ဥပမာ— (၁) ‘ထိုၚ်သး’ = (ချီးမွမ်းသည်) ‘အထိုင်သး’','‘အထိုင်အသး’ = (ချီးမွမ်းခြင်း၊ အချီးအမွမ်း။) (၂) ‘စဳရေၚ်’ = (စီရင်သည်) ‘အစဳရေၚ်’ || ‘အစဳအရေၚ်’ = (စီရင်ခြင်း၊ အစီအရင်။) (၃) ‘စံၚ်တူ’ = (စိုးရိမ်ပူပန်သည်) ‘အစံၚ်တူ’/‘အစံၚ်အတူ’ = (စိုးရိမ်ပူပန်ခြင်း၊ သောက။)')
,(15870,3,9,'(နရှေ့ဆက်) (ကြိရှေ့ဆက်) အထူးသဖြင့် ယောကျာ်းတို့၏ အမည်နာမရှေ့တွင် ‘အ’ ဆက်ခြင်းအားဖြင့် အသုံးပြုနိုင်သည်။ မြန်မာဘာသာတွင် ‘မောင်—’','‘င—’ တို့ကဲ့သို့ဖြစ်သည်။ ဥပမာ— (၁) ‘ကၠဵု’ = (ခွေး) ‘အကၠဵု’ = (မောင်ခွေး၊ ငခွေး။) (၂) ‘ကုန်’ = (ကုန်းသည်) ‘အကုန်’ = (မောင်ကုန်း၊ ငကုန်း။) (၃) ‘ကွ’ = (ပုသည်) ‘အကွ’ = (မောင်ပု၊ ငပု။)')
,(15871,3,12,'(န) ကျေးဇူးမသိတတ်သောသူ။ ကျေးဇူးကန်းသူ။','“(ဍေံ) ဒှ်မၞိဟ်အကတညူ ဂြိုဟ်ကဵုမိတ်စှ်ပြကာတုဲ ဒေဝတဴဟွံမၚ်မွဲ။” (အကြီုရာဇာဓိရာဇ်) =“သူသည် ကျေးဇူးကန်းသူဖြစ်၍ ခင်ပွန်းကြီးဆယ်ပါးကိုပြစ်မှား၍ နတ်မစောင့်။” || “ဍေံဟွံတီဂုန်ညး ဍေံမဒှ်အကတညုဂုန်ရောၚ်သွံ။” (ဇ—၄၄၅။ အစွောံ။) = “သူသည်ကား ကျေးဇူးမသိတတ်၊ ကျေးဇူးကန်းသူတည်း။” || ‘ကတညူ’/‘ကတညူဂုန်’ လည်းရှု။')
,(15872,3,10,'(န) အသွင်သဏ္ဍာန်။ အမူအရာ။ ပုံဟန်။ အခြင်းအရာ။ (ပါဠိ—အာကာရ)','“ညံၚ်အကာရဒမၠမပၠံၚ်စဂှ်ပတုဲ—။” (ဇ—၄၄၆။ အစွောံ။) = “ခိုးသူတို့လုယက်သောပုံဟန်ကဲ့သို့ပြု၍—။” || “ပြဘာတ်ဂှ် ပုၚ်မွဲကလောံဇၞော်ဂိုၚ်ကေတ်တုဲ ဒဒှ်မမိက်ကဵုကၠဵုစဂှ် ထ္ၜးအကာရဂှ် ကဵုသၟိၚ်တီရ။” (ဇ—၅၂၈။ အစွောံ။) = “ထိုပရိဗိုဇ်သည် ထမင်းတုံးကြီးကိုယူ၍ ခွေးကိုစားစေလိုသော အမူအရာကိုပြ၍ မင်းအားသိစေ၏။” || “ညံၚ်ရဴအကာရမသုၚ်ဍာ်ကီုပတုဲ (သၟိၚ်ဒြာဲ) တန်ဒၟံၚ်ရ။” (ဇ—၅ဝ၁။ အစွောံ။) = “သမင်မင်းသည် ရေသောက်ဟန်ကဲ့သို့ပြု၍ နေ၏။” || “ပွမပတုပ်စအာကာရတၠပညာ။” (ဇ—၄၂၈။ အစွောံ။) = “ပညာရှိဟန်အမူအရာကို တုပ ခြင်း။” || “(ၜိုန်ဟွံမိပ်စိုတ်ကီုလေဝ်) ညံၚ်အာကာရမအိုဟ်တၟိုဟ်စိုတ် ဒၟံၚ်တဴရ။” (ဇ—၂၁၈။ အစွောံ။) = “စိတ်မကောင်းဖြစ်သော်လည်း ဝမ်းမြောက်သောဟန်အမူအရာကဲ့သို့ နေ၏။” || ‘အက္ကရ’/‘အက္ကာရ’ ဟုလည်း အနည်းအားဖြင့်တွေ့ရသည်။ || “(သၟိၚ်ကုသ) ထ္ၜးတၚ်တဲကဵုပြဘာဝတဳ အက္ကရမထၞက်ကီုမပ—။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသည် ပဘာဝတီအား မိမိတံတောင်ကိုပြ၍ တံတောင်နှင့်တွက်သော အမူအရာကဲ့သို့ပြု၏။”')
,(15873,3,10,'(န) အမူအရာဖောက်ပြန်ခြင်း။ မူမမှန်ခြင်း။','“အနာထပိဏ္ဍကသေဋ္ဌဳ ညာတ်အကာရဝိကာရလဗၚ်သၟုၚ်တံဂှ်တုဲ ဗ္စာရဏာတီကေတ် ဒဒှ်ဍေံတံစုတ်လဝ်ဂဥုဲဂျိ ပ္ဍဲသုရာဂှ်ရ။” (ဇ—၅၃။ အစွောံ။) = “အနာထပိဏ်သူဋ္ဌေးသည် သေသောက်ကြူးတို့၏အမူအရာမမှန်ဖောက်ပြန်နေသည်ကိုမြင်၍ အရက်ထဲတွင် ၄င်းတို့အဆိပ်ဆေးခတ်ထားကြောင်းကိုပိုင်းခြားဆင်ခြင်ပြီးသိ၏။”')
,(15874,3,10,'(န) အခါမဟုတ်။ အချိန်မတော်။ ညအခါ။ အကာလ။',NULL)
,(15875,3,10,'(န) အာကာသ။ ကောင်းကင်။',NULL)
,(15876,3,1,'ကောင်းကင်­ တည်မှီသောနတ်။ အာကာသစိုးနတ်။','“အကာသဇဵုဂျ၊ ပၠဘုမ္မဇဵုကၠာ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “အာကာသစိုးနတ်ကို၄င်း ဘုမ္မစိုးနတ်ကို၄င်း။”')
,(15877,3,11,'(န) မကောင်းမှု။ အကုသိုလ်။',NULL)
,(15878,3,11,'(န) အကုသိုလ်ကံ။ ပြုထားသောမကောင်းမှုကံ။','“အကုသဵုကံမ္ဒးထၞိက်စုတ်လဝ်မိဂှ် ကဵုဖဵုတုဲ မၚ်ဗၠာဲမိတ္တဝိန္ဒကဂှ် ဂျိုၚ်ဂျိုၚ်မဒးဒုၚ်နရက်ရ။” = “မိခင်အားကန်ကျောက်ထားသော အကုသိုလ်ကံအကျိုးပေး၍ မိတ္တဝိန္ဒကလုလင်သည် အရှင်လတ်လတ် ငရဲခံရ၏။”')
,(15879,3,11,'(န) မကောင်းသောစိတ်။ အကုသိုလ်စိတ်။ လောဘဒေါသမောဟစသည့် အကုသိုလ်တရားများ ကြီးစိုးသောစိတ်။',NULL)
,(15880,3,11,'(န) မိုးကောင်းကင်။ (ပါဠိ—အာကာသ)','‘တ္ၚဲတၟးအကးသ္ဇုၚ်။’ = ‘မိုးလင်း၍ကောင်းကင်ကြည်လင်သည်။’')
,(15881,3,1,'၁။ အကောက်အခွန်။','အကံက်ဖျာ = ဈေးကောက်။')
,(15881,3,1,'၂။ အကွပ်။','အကံက်မြ =ဓါးအကွပ်။')
,(15882,3,1,'အကောက်အခွန်။',NULL)
,(15883,3,1,'၁။ အရေပြားပေါ်ပေါက်သော အနာအဖု။ အင်ပြင်ရောဂါ။','ခဍတ်အကၚ် = အနာပေါက်။ || အကၚ်ဂျိ = အဆိပ်ကြောင့်ဖြစ်သော အနာအဖု။ || အကၚ်တူပၟတ် = မီးလောင်ဖု။ မီးလောင်နာ။ || အကၚ်မြန် = ကျောက်ရောဂါအနာအဖု။')
,(15883,3,1,'၂။ အရှိန်။ အခိုး။','အကၚ်ဂဥုဲ =ဆေးအရှိန်။ || အကၚ်ဂဥုဲတိုန် = ဆေးရှိန်တက်သည်။')
,(15884,3,1,'အလေ့အထ။ လုပ်ရိုးလုပ်စဉ်။ ပြုနေကျအမှု။ ကျင့်သား။','“အကေၚ်ဟွံမွဲမ္ဂး ကၠောန်ကလောန်ဇြိုၚ်ၚ်ဟွံမာန်ရ။” = “ကျင့်သားမရှိလျှင် လေးလံသောအလုပ်ကို မလုပ်နိုင်ပါ။” || “တ္ၚဲယးတုဲ ကၠဂှ် အကေၚ်ဍေံဂွံစဒၟံၚ်ရိုဟ်ဟ်တ္ၚဲဂှ် ကၠုၚ်ကဵုကၠိက်ဂမၠိုၚ်ရ။” (ဇ—၄၉၂။ အစွောံ။) =“မိုးလင်းလတ်သော် ထိုကျားသည် နေ့တိုင်းစားနေကျအလေ့အတိုင်း ဝက်များဆီသို့လာ၏။” || “သၟိၚ်ဗှ်ဗၞုဟ်ဒါန်ကုသဵုဇကု အကေၚ်မပ္တုဲ (ပ္ဍဲဍုၚ်မၞိဟ်ဂှ်တုဲ လဟိၚ်စိုတ်ဟွံမွဲ ပ္ဍဲဍုၚ်သွဝ်ရ။)” (ဇ—၄၉၄။ အစွောံ။) = “သာဓိနမင်းသည် လူ့ပြည်­ မိမိအလှူပေးနေကျ ကုသိုလ်ကောင်းမှုကိုအောက်မေ့၍ နတ်ပြည်­ပျော်ပိုက်ခြင်းမရှိ။” || “ဇၟာပ်ဗတံဟေၚ် အကေၚ်ပိုဲမဂွံရေၚ်ကာန်ဒၟံၚ်မွဲစွံ—။” (ဇ—၅ဝ၄။ အစွောံ။) = “ညတိုင်းပင် ငါတို့လင်မယားသည် အတူပေါင်းဖက်နေကျ အလေ့အထရှိ၏။”')
,(15885,3,1,'ငကုန်း။ ကုန်းသောသူ။',NULL)
,(15886,3,1,'၁။ ငှက်ခါး။ (ပါဠိ—စာသ)',NULL)
,(15886,3,1,'၂။ ဒလိမ့်တုံး။',NULL)
,(15887,3,1,'၁။ အကွပ်။ ဘေးနားအကွပ်။','အကောပ်န = တောင်းအကွပ်။')
,(15887,3,1,'၂။ အစိုးရခြင်း။စီရင်ပိုင်ခြင်း။','“ဒဒှ်ဒးလောပ်၊ အကောပ်ဒဒိုက်။” (လိက်မာဃဒေဝါန်) = “ဒုက္ခ၏အလိုသို့ရောက်ရ၏။”')
,(15888,3,1,'လှည်းဖိနပ်သံခွါ။ လှည်းဘီးအကွပ်။ ဘီးပတ်။ ဘီးခွေ။ (ပါဠိ—နေမိ)',NULL)
,(15889,3,1,'သေမင်းလက်တွင်းသို့ရောက်ခြင်း။','“ပိုဲညးၜါဂှ် ဒှ်အာအကောပ်ဂစိုတ်ရဂးတုဲ ကလောပိုဲဂမၠိုၚ်ဂှ် (ဂွိၚ်စံၚ်တူအိုတ်ရ။)” (ဇ—၅၃၄။ အစွောံ။) =“ငါတို့နှစ်ဦး သေမင်းလက်တွင်းသို့ ရောက်ခဲ့ပြီဟုဆိုကာ ငါတို့၏အဆွေအမျိုးတို့သည် စိုးရိမ်ပူပန်ကုန်၏။” || “(ယဝ်ရဂၞကျာ်မဒ္ဒဳသဒှ်အန္တရာဲဂစိုတ်) ဇာလဳကဵုကဏှာဇိုန် သီုတၠညးဝေသန္တဝ် သ္ဒးလုပ်အကောပ်သၟိၚ်ဂစိုတ်ရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အကယ်၍မဒ္ဒီမိဖုရားသာ အသက်အန္တရာယ်ဖြစ်ခဲ့သော် ဇာလီနှင့်ကဏှာဇိန်ရော ဝေဿန္တရာမင်းပါ သေမင်းလက်တွင်းသို့ ဝင်ရကုန်လတ္တံ့။” || “ကၠာဟွံဂွံလုပ်အကောပ်တဲသၟိၚ်ဂစိုတ်ဏီဂှ် ကုသိုလ်မဒှ်ဇွောံမ ပ္ဍဲသံသာဝွံ မှတ်ဆန်ၜန်ဂလိုၚ်လဝ်ညိ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “သေမင်းလက်တွင်းသို့ မသက်ဆင်းရသေးမီသံသရာ­ရိက္ခာဖြစ်သော ကုသိုလ်ကောင်းမှုကို မဖြစ်မနေ စီမံပွားများထားပါလေ။”')
,(15890,3,1,'လက်ခုပ်အတွင်း။ အုပ်ချုပ်မှုအောက်။ လက်အောက်ခံ။','“အိုတ်ဇန်ဇၟာပ်ညး၊ဇၟာပ်ရးဒေသ။ ကဵုဍေံဒးလုပ်၊ အကောပ်တဲမ။ ကဵုနၚ်အခေါန်၊ ကောန်ဂၠုတလ။” (လိက်သၚ်ဂဒါ။သဳလဝန္တထေရ်။) = “တိုင်းနိုင်ငံတိုင်းမှလူများကို သားတော်မောင်လက်အောက်ရောက်စေ၍ အခွန်တော်ဆက်စေရပါမည်။” || “ဟာကောန်ဒဒေံယာဲ၊ နာဲမဒးလောပ်အာအကောပ်တဲသတြုကွေံရသွံကောန်။” (သၠပတ်သုရသာ) = “အိုအမယ့်ချစ်သားထွေး၊ ရန်သူ့လက်ခုပ်အတွင်းသို့ အမှန်တကယ် သင်ဝင်ရောက်သွားရလေပြီတကား။”')
,(15891,3,1,'ရာဇဝတ်အပြစ်ပေးခြင်း။','“တ္ၚဲသၟိၚ်သ္ပအကောပ်ရာဇာဝတ် တိုၚ်ပိုဲမဒးကီု။” = “မင်းက ရာဇဝတ်အပြစ်ပေးသောနေ့­ ငါတို့ခံရဖို့သာရှိ၏။”')
,(15892,3,1,'၁။ ကွပ်ကဲခြင်း။','၂။ ကွပ်မျက်ခြင်း။')
,(15893,3,1,'၁။ အမူအရာ။ အကဲ။ အခြင်းအရာ။ အခြေအနေ။ အသွင်။','“ရံၚ်အကာဲဍေံတုဲ ဟီုအရေဝ်ညိ။” = “သူ့အကဲကိုကြည့်ပြီး စကားပြောပါ။” || “ရာဟုရုပ်နာဲ၊ အကာဲသ္ဇုၚ်ဂွု။ ဍန်ဒးစက္ခု၊ ဇကုသမြပ်။ ရာဟုဂနပ်၊ ဇြဟာန်စပ်ဒး။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ဖြူစင်သောအသွင်ရှိသော သခင့်ရုပ်လွှာတည်းဟူသောရာဟုသည် မျက်စိအာရုံကို ဆွဲဆောင်သည်ရှိသော်ကိုယ်ခန္ဓာအလုံးတုန်လှုပ်သွားရကာ ချစ်နှစ်သက်ခြင်းဟူသောရာဟုသည် စိတ်­ကပ်ငြိစွဲလမ်းသွားရ၏။” || “နူညာတ်ဒးနာဲ၊ ရုပ်အကာဲသွဝ်။ ကောန်ခနှောဝ်ကျ၊ ရုပ္ပအသဝ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) = “ကိနနရီရှုံးရသော အံ့ဖွယ်ရူပါရှိသော လှနတ်ရုပ်အသွင်ရှိသောသခင့်ကိုမြင်ရသည်မှစ၍—။”')
,(15893,3,1,'၂။ အထွတ်အခေါင်။ ကျက်သရေဆောင်။ (?)','“ယွံသၟိၚ်ဓဝ်ဗၠာဲ၊ အကာဲနန်ကၠတ်။” (လိက်ပဒုမဝတဳ) = “အို—နန်းတော်၏အထွတ်အခေါင် တရားမင်းပျို။” || “မနွံစရာဲ၊ ဗြဴအကာဲနန်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဂုဏ်သရေရှိသော နန်းကျက်သရေဆောင်မိန်းမ။” || “သၟိၚ်ဓဝ်အကာဲ၊ နာဲညးဒိုဟ်ပန်။ ဂုန်ရုပ်အမြိုတ်၊ စိုတ်ပ္တန်ဟွံတန်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “အရပ်လေးမျက်နှာ၏သခင် အထွတ်အခေါင်မင်းတရားသည်မယ့်ရုပ်လွှာကြောင့် စိတ်ကိုတည်ငြိမ်အောင်မထားနိုင်။”')
,(15894,3,1,'အမူအရာ။ အခြေအနေ။','“အကာဲအရာပရေၚ်ဍုၚ်ကွာန်။” = “နိုင်ငံရေးအခြေအနေ။”')
,(15895,3,1,'ကုတ်ကရူးငှက်။ (ငှက်ဆိုး) (ပါဠိ—ကရေဋု)',NULL)
,(15896,3,1,'လေအောင်သောသူ။ လေပေးများသောသူ။ လေထွားသူ။',NULL)
,(15897,3,13,'(န) အကျိုး။ အကျိုးစီးပွား။','“သၟိၚ်ဗြာဇ္ဇမဟီုဝွံ ညာတ်အာဒဵုအကျောတၞောဝ်ဒတောဝ်ပိုဲဂတဏီသွံ။” (အကြီုရာဇာဓိရာဇ်) = “အမတ်မင်းဗြာဇ္ဇ၏စကားသည် ငါတို့၏အနာဂတ်ဆွေမျိုးစဉ်ဆက်အကျိုးကိုပင် မြင်ပါပေသည်တကား။” || “ဂလာန်အမာတ်ဒိန်ပ္တီဝွံ ဒှ်ဂလာန်ယုတ္တိစၟတ်ကွေံ။ ဆအကျောတၠညးဟွံသေၚ်၊ ဒှ်ဒဵုအကျောတၞောဝ်ရာဇာဝၚ် ဖေက်စေန်ဆက်အာအနာဂတ် ဂွံခိုဟ်အာဂတကီုရောၚ်။” (အကြီုရာဇာဓိရာဇ်)')
,(15898,3,3,'ကြီးသော။','ဇရဳအကြ = စဉ့်အိုးကြီး။')
,(15899,3,6,'အကြား။ စပ်ကြား။','အကြာညးၜါ = နှစ်ဦးကြား။ || အကြာဂြိုပ်ဂၞိၚ် = တောကြိုတောင်ကြား။ || “ဒြာဲနန္ဒိယဂှ် လုပ်အာအကြာဒြာဲဂမၠိုၚ်ရ။” (ဇ—၃၈၅။ အစွောံ။) = “နန္ဒိယသမင်သည် သမင်များအကြားသို့ ဝင်သွား၏။”')
,(15900,3,1,'အတိုင်းအတာ။ အစပ်အဟပ်။','အကြိုက်ညးကဵုညး = သူ့အတိုင်းအတာနှင့်သူ။ || ဒးအကြိုက် = အစပ်အဟပ်မိသည်။ အစပ်အဟပ်တည့်သည်။')
,(15901,3,5,'တိုက်တိုက်ဆိုင်ဆိုင်။ တိုက်ဆိုင်စွာ။','“သၟိၚ်တိတ်ဝေၚ်ဂြိုပ် အကြိုက်သၟိက်ကဵုဒှ် အာဆဵုလၟမွဲ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မင်းသည် တောကစားထွက်၏။ တိုက်ဆိုင်စွာ တစ်ယောက်သောမုဆိုးနှင့် ဆုံမိ၏။” || ‘ကြိုက်သၟိက်ကဵုဒှ်’ || ‘ထေက်—ထိုက်သၟိက်ကဵုဒှ်’ || ‘အလိုက်သၟိက်ကဵုဒှ်’ တို့နှင့်အတူတူ။')
,(15902,3,1,'အကြပ်။ တပ်ကြပ်။',NULL)
,(15903,3,1,'၁။ အကြောင်း။ နိဒါန်း။','အကြီုရာဇာဓိရာဇ် = ရာဇာဓိရာဇ်အကြောင်း။ || အကြီုယဲ= ရောဂါအကြောင်း။ || “ယွံတဳလမနွံပိုန်၊ ပိုဲဍိက်ဟီုအကြီုဒေဝဒတ်တိၚိတ်ကၠေံဂှ်ရောၚ်အဴ” ခမဳဂမၠိုၚ်ဂး။ (ဇ—၄ဝ၄။ အစွောံ။) = “အရှင်ဘုရား၊ တပည့်တော်တို့သည် ဒေဝဒတ်အား မြေမျိုသွားသည့်အကြောင်းကို ပြောဆိုကြပါကုန်၏။” || “အမာတ်တံသဳကၠဳဒၟံၚ်သၟိၚ်တုဲ ဟီုဒၟံၚ်အကြီုသဘဴဓဝ်ကုသဵုရ။” (ဇ—၄ဝ၆။ အစွောံ။) = “အမတ်တို့သည် မင်းအားခစားနေလျက် ကုသိုလ်တရားနှင့် ယှဉ်သောအကြောင်းကို ပြောဆိုလျက်နေ၏။”')
,(15903,3,1,'၂။ ကြုံးဝါးခြင်း။ ဥဒါန်း။','‘ကရီု’နှင့်အတူတူ။ || “အသီဂှ်ချိုတ်အာတုဲ ဂစေံစစိပ်ဂှ် ဟိုတ်ဂွံဇၞးသတြုတုဲ — အကြီုမွဲဂှ် ကြီုတဴရ။” (ဇ—၁၆၈။ အစွောံ။) = “ထိုသိမ်းငှက်သေသွားပြီးနောက် ဗီလုံးငှက်သည် ရန်သူကိုအောင်နိုင် ခြင်းကြောင့် တစ်ခုသောဥဒါန်းကို ကျူးရင့်လေ၏။”')
,(15904,3,1,'အကြောင်းအရာ။ အခြင်းအရာ။ အချက်အလက်။',NULL)
,(15905,3,1,'သတင်းစာခေါင်းကြီးပိုင်း။ အယ်ဒီတာ့အာဘော်။',NULL)
,(15906,3,1,'ကြိုးကြာငှက်။',NULL)
,(15907,3,1,'ဘက်ပဲ့သောသူ။',NULL)
,(15908,3,1,'ငှက်ကုလား။ ငှက်မိန်။ (?) (ပါဠိ—ကုက္ကုဋ္ဌက)','“မြာ်ထဝ်၊ ကၟာၚ်အိုၚ်၊ ၚံက်ၚာ်၊ ခ္ဍာ်သၟိၚ် ရာံ၊ ဗဂီု၊ အကၠီု၊ အကၠဟ်—။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။)')
,(15909,3,1,'တင်ကျီးငှက်။','“ဗောဓိသတ်က္တဵုဒှ်ဂစေံအကၠဟ်မွဲ ပ္ဍဲဂြိုပ်ဟေမဝန်။” (ဇ—၂ဝ၄။ အစွောံ။) = “ဘုရားလောင်းသည် ဟိမဝန္တာအရပ်ဝယ် တင်ကျီးမျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(15910,3,1,'ငကွ။ ပုကွသောသူ။',NULL)
,(15911,3,6,'အတွက်။ အဘို့။ အလို့ငှာ။ အကျိုးငှာ။','“ကေတ်နၚ်အကွက်အဲညိ။” = “ကျွန်တော့အတွက် ယူလာပါ။” || အကွက်စ = စားဘို့။ စားရန်အတွက်။')
,(15912,3,1,'၁။ အခါ။ အချိန်အခါ။','အခါဂှ် = ထိုအချိန်။ ထိုအခါ။ || အခါဏအ် = ဤအချိန်။ဤအခါ။ || အခါလဵု = ဘယ်အခါ။ ဘယ်သောအခါ။ || အခါလၟုဟ် = ယခုအခါ။ || “(ၚုဟ်ဂၠဴဂှ်) ကာလစိုပ်အခါသြောံတိတ်တုဲ ကာလဂှ်ပိုဲကဵုရ။” (ဇ—၁၉၉။ အစွောံ) = “စပါးထွက်သောအခါရောက်လျှင် ထိုအခါ နွားဘိုးကို ငါတို့ပေးပါမည်။”')
,(15912,3,1,'၂။ တစ်နှစ်ကာလ။','“(ယွံတေမဳဂၠုမိဟိုဲ) ၊နူမွဲအခါပေၚ်ကၠုၚ် (၄) အခါ ကဵုယာဲပၠန်သွံလေဝ်ကောန်။” (ဇ—တေမဳ။ အစွောံ။) = “အိုချစ်သားမောင်တေမိ၊ တစ်နှစ်အရွယ်မှသည် လေးနှစ်အရွယ်ပြည့်ခဲ့ပြန်လေပြီ။” || “အယုက်ဒှ်တုန်၊ စှ်သုန်အခါ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “အသက် (၁၅) နှစ်သို့ရောက်၏။”')
,(15913,3,11,'(န) အလွန်များပြားသော အရေအတွက်တစ်ခု၏အမည်။ ခေါဘဏဳ။ သုညရေ (၄၂) လုံးရှိသောသင်္ချာ။ (ပါဠိ—အက္ခောဘိဏဳ)','“သၟိၚ်ကၠံမွဲက္ဍိုၚ်ဗ္တာၚ် သီုဗဵုလဗးၜါစှ်ောပန်အခေါဗနဳ။” (ဇ—၅၃၂။ အစွောံ။) = “တစ်ရာ့တစ်ပါးသောမင်းများနှင့်တကွ စစ်သည်ဗိုလ်ပါနှစ်ဆယ့်လေးခေါဘဏီ။” || ‘ခေါဘနဳ’ နှင့်အတူတူ။')
,(15914,3,1,'၁။ ဓလေ့။ ထုံးစံ။ အလေ့အထ။ လုပ်ရိုးလုပ်စဉ်။ လုပ်ဟန်ကိုင်ဟန်။','“အခိုက်ပြဝေဏဳဗောဓိသတ်ကျာ် ပ္တံပါရမဳဂှ် နွံပ္ဍဲဒဒိုက်ကၠာ ကြဴရောၚ်ဂွံတွံဓဝ်။” (အကြီုရာဇာဓိရာဇ်) =“ဘုရားလောင်းတို့ ပါရမီဖြည့်ခြင်း အစဉ်အလာဓလေ့သည် အလျင်ဒုက္ခခံပြီးမှ နောင်တရားဟောရ၏။” || “သၟိၚ်အာယမန္ဒယာ ကျိုၚ်ကေတ်အခိုက်ဒကိုပ်ပၞာန်။” (အကြီုရာဇာဓိရာဇ်) =“သမိန်အာယမန္ဒယာသည် စစ်တပ်မှူးဟန် ဝတ်စားဆင်ယင်၍—။”')
,(15914,3,1,'၂။ (ဂီတ) တီးကွက်တီးဟန်။ သံစဉ်။','“ဖံဗာတ်တွိၚ်တွိုက်၊ အခိုက်သဗ္ဗ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “တူရိယာပေါင်းစုံတို့သည် အလုံးစုံသောတီးကွက်သံစဉ်ရှိကုန်၏။” || “ဗရုကွိၚ်ကွိုက်၊ အခိုက်စှ်ၜါ။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ။) = “တစ်ဆယ့်နှစ်မျိုးသော တီးကွက်တီးဟန်နှင့်တကွသော တူရိယာသံများ။” || “မလေပ်တွိၚ်တွိုက်၊ လေပ်အခိုက်ဒွက်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “တူရိယာတီးမှုတ်ခြင်းကိုတတ်၍ တေးသီချင်းသံစဉ်ကိုတတ်၏။”')
,(15915,3,1,'ဓလေ့ထုံးစံ။ နည်းလမ်း။ ဟန်ပန်။','“အခိုက်ကၞာမန် စပ်ကဵုမ္ၚဵုစဝ်ကပေါဝ်။” =“ကၚ်ပွန်းတပ်မင်္ဂလာဆိုင်ရာ မွန်တို့၏ဓလေ့ထုံးစံ။” || “(သရာဲမန်ဗညာဓရာံ ကေုာံသရာဲကြုက်ကာမ္မနိတံ ဍိုက်ချေံပြိုၚ်ပ္ကာန်) လှ်ေကွာဲအာကဵုအိုတ်အခိုက်ကဏာကၠာတုဲ (စၞေဟ်ကေတ်ကယျဇမၞးရၚ်သ္ကံ။)” (အကြီုရာဇာဓိရာဇ်) = “မွန်သူရဲသမိန်ဗရမ်းနှင့် တရုတ်သူရဲကာမနိတို့သည် မြင်းစီးယှဉ်ပြိုင်၍ ကနည်းကဟန်ကုန်စုံသည့်တိုင်အောင် ကပြကြပြီးနောက် အရှုံးအနိုင်စီချင်းထိုးကြ၏။”')
,(15916,3,1,'အလိုက်အထိုက်။','ဟွံတီအခိုက်အလိုက်ညး = အလိုက်မသိ၊ အလိုက်ကမ်းဆိုးမသိ။')
,(15917,3,9,'—မှန်း။ —ကြောင်း။','“အခၚ်ဍေံနွံအဏအ် အဲဟွံတီ။” = “သူဒီမှာရှိမှန်း ငါမသိပါ။” || “အစာသိုန်သဒိုဟ်ဂှ် ဟွံတီအခၚ်မၞိက်တဴ လတူတာအကာသ။” (ဇ—မဟောဟ်သဓ။အစွောံ။) = “သေနကအမတ်သည် မိုက်မဲပညာနည်း၍ အာကာသထန်းပင်ထက်­ ပတ္တမြားရှိကြောင်းကို မသိလေ။” || “အခၚ်ဒှ်ဝိသာခါ၊ လိုက်ဗာတအ်ဟွံတီမွဲ။” (လိက်ဂၞကျာ်ဝိသာခါ) =“ဝိသာခဖြစ်မှန်း လူတို့မသိကြကုန်။” || “ၜိုန်ကွာ်အာကြာစဴ၊ အခၚ်ဗဴညးဟွံတီ။” (လိက်ဂၞကျာ်ဝိသာခါ) = “မြေးမများအကြား လျှောက်သွားသည်ရှိသော် အဘွားဖြစ်မှန်း သူတကာတို့မသိကြကုန်။” || ‘အခြၚ်’ (စည်း) လည်းရှု။')
,(15918,3,9,'တစ်ခေါင်း။ တစ်ခင်။','တောဝ်မွဲအခၚ် = ချည်ခင်တစ်ခင်။ ချည်ခေါင်းတစ်ခေါင်း။')
,(15919,3,1,'အချိန်။ အခါ။ ကာလ။','အခိၚ်တ္ၚဲ = နေ့အချိန်။ || အခိၚ်ဗ္တံ = ညအချိန်။ || အခိၚ်စိုပ်၊စိုပ်အခိၚ် = အချိန်ရောက်သည်။ အချိန်ကျသည်။ အချိန်တန်သည်။ || အခိၚ်လောန်၊ အခိၚ်ၜက်= အချိန်လွန်သည်။ || အခိၚ်အိုတ်၊ အိုတ်အခိၚ် = အချိန်ကုန်သည်။ || “တြုံတြုံဗြဴဗြဴ၊ ပူဇဴပၞာၚ်ထဝ်။ လံဖိုတ်ခၠန်သွိၚ်၊ အခိၚ်တ္ၚဲသဝ်။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။)')
,(15920,3,1,'တပ်။ အစုအဖွဲ့။','အခေၚ်ပၞာန်၊ အခေၚ်ဗဵုပၞာန် = စစ်ကြောင်း။ စစ်သည်ဗိုလ်ပါ။ || “(သၟိၚ်) သီုအခေၚ်ဗဵု ဇက်တိတ်ဥဒျာန်။” (ဇ—၅၁၉။ အစွောံ။) = “မင်းသည် စစ်သည်ဗိုလ်ပါများနှင့်တကွ ဥယျာဉ်တော်သို့ ထွက်၏။” || “သၟိၚ်တံဂှ်မိၚ်တုဲ စဳရေၚ်အခေၚ်ဗဵုပၞာန်မဇၞော်တုဲ သီုထပှ်က္ဍိုၚ်ဗ္တာၚ်ဂှ် ဇက်ကၠုၚ်မွဲဒမြိပ်။” (ဇ—၅၃၁။ အစွောံ။) = “ထိုခုနစ်ပြည်ထောင်မင်းတို့သည်ကြားကုန်၍ စစ်တပ်အလုံးအရင်းစီရင်၍ တစ်ပြိုင်နက်တည်း ချီတက်လာကြကုန်၏။”')
,(15920,3,9,'စစ်ကြောင်းအရေအတွက်တွင် သုံးသောစကားလုံး။','“ပၞာန်ပန်အခေၚ်၊ ကဵုစဳရေၚ်ပၠန်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “စစ်ကြောင်းလေးကြောင်းကို စီရင်စေပြန်၏။”')
,(15921,3,1,'စစ်ကြောင်း။','“သၟိၚ်ကဵုစဳရေၚ်၊ အခေၚ်ပၞာန်ပန်။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ) = “မင်းသည် (ဆင်တပ်၊ မြင်းတပ်၊ ရထားတပ်၊ ခြေသည်တပ်ဟူသော) စစ်ကြောင်းလေးခုတို့ကို စီရင်ပြင်ဆင်စေ၏။”')
,(15922,3,1,'၁။ အခွင့်။ ပြုလုပ်ခွင့်။ ခွင့်ပြုချက်။','“အပါဟွံကဵုအခေါၚ်မ္ဂး အဲအာပေဲါဟွံဂွံရောၚ်၊”= “အဖေအခွင့်မပြုလျှင် ကျွန်မပွဲမသွားရပါ။” || အာတ်အခေါၚ် = ခွင့်တောင်းသည်။ || ကဵုအခေါၚ်၊ သၠးအခေါၚ် = ခွင့်ပေးသည်၊ ခွင့်ပြုသည်။')
,(15922,3,1,'၂။ အခွင့်အလမ်း။ အခွင့်အခါ။','“ဟွံပလွဳပရာမ္ဂး အခေါၚ်သ္ဂောံဇၞော်မောဝ် ဟွံမွဲရ။” = “မကြိုးစားလျှင် ကြီးပွားရန်အခွင့်အလမ်းမရှိပါ။”')
,(15922,3,1,'၃။ အခွင့်အရေး။','“မၞိဟ်တြုံတြုံကီု မၞိဟ်ဗြဴဗြဴကီု ဒှ်မၞိဟ်တုပ်တုပ် ဒးနွံအခေါၚ်တုပ်သၟဟ်ရ။”= “ယောကျာ်းများသည်၄င်း မိန်းမများသည်၄င်း လူချင်းအတူတူ တူညီသောအခွင့်အရေးရှိရမည်။”')
,(15923,3,1,'အခွင့်အလမ်း။','“ကၠောန်ကလောန်ဏအ်မ္ဂး အခေါၚ်ဂၠံၚ်သ္ဂောံဇၞော်မောဝ်တိုန် နွံဒၟံၚ်ရ။” = “ဤအလုပ်ကိုလုပ်လျှင် ကြီးပွားတိုးတက်ရန် အခွင့်အလမ်းရှိသည်။”')
,(15924,3,1,'လူ့အခွင့်အရေး။','‘ပလီုပလာ်တဴအခေါၚ်အရာမၞိဟ်။’ = ‘လူ့အခွင့်အရေးချိုးဖောက်သည်။’ || ‘ယိုက်ဒိုက်တဴအခေါၚ်အရာမၞိဟ်။’ = ‘လူ့အခွင့်အရေးကို လေးစားသည်။’')
,(15925,3,1,'အခွင့်အရေး။','“မၞိဟ်ဗြဴဗြဴဗွဲမဂၠိုၚ် ဟွံဂွံတဴအခေါၚ်အရာ ဗွဲမတုပ်သၟဟ်ကဵုမၞိဟ်တြုံတြုံရ။” = “များစွာသောအမျိုးသမီးတို့သည် ယောကျာ်းတို့နှင့်တူညီသော အခွင့်အရေးမရရှိကြပါ။”')
,(15926,3,1,'အခွင့်အာဏာ။','“ပ္ဍဲကၟိန်ဍုၚ်ဗၟာလၟုဟ်ဝွံဂှ် ဂကူကောန်ဍုၚ်အရၚ်ဂမၠိုၚ် အခေါၚ်အဝဵုဟွံမွဲရ။” = “ယခုမြန်မာနိုင်ငံတွင် တိုင်းရင်းသားလူမျိုးများ အခွင့်အာဏာမရှိကြပါ။”')
,(15927,3,1,'ခိုင်ခံ့ခြင်း။ မြဲမြံခြင်း။','‘ပအခိုၚ်’ လည်းရှု။')
,(15928,3,5,'အတင်းအကြပ်။ အတင်းအဓမ္မ။ နိုင်ထက်စီးနင်း။ အမိန့်အာဏာဖြင့်။','“အခိုၚ်အနိၚ် သီုဇြဟတ်ဗိုလ်လဗး ဇက်ပၞာန်တိုန်အာ။” (အကြီုရာဇာဓိရာဇ်) = “အတင်းအဓမ္မဗိုလ်ပါအင်အားနှင့်တကွ စစ်ချီတက်သွား၏။” || ‘အနိၚ်အခိုၚ်’ နှင့်အတူတူ။')
,(15929,3,4,'အနိုင်အထက်ပြုသည်။ အတင်းအကြပ်ပြုသည်။','“(သၟိၚ်မန်ဝွံ) သၟိက်ပအခိုၚ်အနိၚ် တသိုၚ်ပၠံၚ်တိရးပိုဲ ပဒြပ်ဇကု” သၟိၚ်ဗမာဂး။ (အကြီုရာဇာဓိရာဇ်) = “မွန်မင်းသည်အနိုင်အထက်ပြုလိုသဖြင့် ငါတို့နိုင်ငံမြေကိုလုယက်၍ မိမိဥစ္စာပြု၏” ဟုဗမာမင်းဆို၏။')
,(15930,3,1,'အခန်းကဏ္ဍ။',NULL)
,(15931,3,1,'အခွန်။','အခေါန်ကၚ်ၚာၚ် = ကင်းဂိတ်ကြေးအခွန်။ || အခေါန်တိ = မြေခွန်။ || “သၟိၚ်ဂှ် လောဘဇၞော်တုဲ ကေတ်အခေါန် ရာန်သကိုတ်ညးလောန်။” (ဇ—၄၇၈။ အစွောံ။) =“ထိုမင်းသည် လောဘကြီး၍ လူတို့ကိုနှိပ်စက်၍ အခွန်ကောက်၏။”')
,(15932,3,1,'ကင်းခွန်။ အခွန်အတုတ်။ (ပါဠိ—သုၚ်္က)','“ကွာန်မၞုံယၟုကာသိ အခေါန်ၚာၚ်မတိတ်ဒၟံၚ်သြန်မွဲကိုတ်ဝွံ—။” (ဇာတ်ဝတ္ထုတၠပါရမဳဂမၠိုၚ်။ ပါလိတ။) = “ငွေတစ်သိန်းအခွန်ထွက်သော ကာသိမည်သောရွာ။”')
,(15933,3,1,'အကောက်အခွန်။ အခွန်အတုတ်။','“အခေါန်ဖလှာလ္ပကံက်ညိ။မၞးတံဗလးကဵုအဲညိ။” (ဇ—၄၅၄။ အစွောံ။) = “အခွန်အကောက်ကို သင်တို့မကောက်ပါနှင့်။ ငါ့ကိုကင်းလွတ်ခွင့်ပေးပါ။” || “ဟိုတ်သၟိၚ်ဂှ်မဒှ်အဓမ္မ ကေတ်အခေါန်ဖလှာ ဟွံတီဗၞတ်ဗ္ၜတ်တုဲ—။” (ဇ—၅၂ဝ။ အစွောံ။) = “အတိုင်းအရှည်ပမာဏမသိဘဲ အခွန်အတုတ်ကိုယူသော အဓမ္မမင်းဖြစ်၍—။” || “ကာလဂှ် ဗဂေါဒးဒုၚ်အခေါန်ဖလှာကဵုဍုၚ်ဗကာံ။” (အကြီုရာဇာဓိရာဇ်) = “ထိုကာလတွင် ဗဂိုးသည် ပုဂံပြည်အား အခွန်ပေးဆောင်ရ၏။”')
,(15934,3,1,'အကောက်အခွန်။ အခွန်အတုတ်။',NULL)
,(15935,3,1,'အကောက်အခွန်။ အခွန်အတုတ်။','“အမာတ်ဒကိုပ်ပၞာန်သၟိၚ်ပဥ္စာလဂှ် ပွအဓမ္မဂှ်ပတုဲ ကုမှာဇန်အိုဿီု နအခေါန်အဒါန် မရာန်သကိုတ်တဴတုဲ ညးရးတံညးဂမၠိုၚ်ဂှ် — ဒဴလုပ်အာဂြိုပ်—။” (ဇ—၅၂ဝ။ အစွောံ။) = “ထိုပဥ္စာလမင်း၏မှူးမတ်အစရှိသော—သူတို့သည် တရားမစောင့်ကုန်သည်လျှင်ဖြစ်ကုန်၏။ အခွန်အတုတ်ဖြင့် နှိပ်စက်အပ်ကုန်သော တိုင်းပြည်­နေသောသူတို့သည် (တောသို့ဝင်၍ပြေးကုန်၏။)” (ညောင်ကန်) || “ညးကွာန်တံဂမၠိုၚ်ဂှ် ကၠုၚ်ဆက်ကွာဲအခေါန်အဒါန် ဒၞာဲဂှ်ဖအိုတ်ရ။” (ဇ—၄၆၇။ အစွောံ။) = “ရွာသားအပေါင်းတို့သည် အားလုံးထိုနေရာသို့လာ၍ အခွန်တော်ဆက်ကြကုန်၏။”')
,(15936,3,11,'(န) အက္ခရာ။ စာလုံး။ (ပါဠိ—အက္ခရ)','“ၚ်ဇာတ်ဝေသန္တဝ်ဂှ်၊ၚ်မၞုံဗၞတ်စှ်ပိခဏ်၊ မၞုံဗၞတ်လ္ၚီဂါထာ၊ မၞုံဗၞတ်ပန်လ္ၚီပိုတ်၊ မၞုံဗၞတ်ပိလက်ကဵုၜါလ္ၚီအခဝ်၊ — စိုန်ကျာ်တွံစွံလဝ် ပ္ဍဲကာလဂှ်ရောၚ်မိဂ္ဂး။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အက္ခရာပေါင်းသုံးသောင်းနှစ်ထောင်။” || “ပ္တုဲကၠေံဇြပ်ဂှ်ရ။ တုဲချူလဝ်အက္ခဝ်ရ။ ဇြပ်သုဓမ္မာဂးယၟု။” (ဇ—၃၁။ အစွောံ။) =“ထိုဇရပ်ကိုပြီးစေ၏။ ပြီးသော် အက္ခရာရေးထား၏။ သုဓမ္မာဇရပ်ဟု အမည်တွင်၏။” || “ဒု၊သ၊ န၊ သော၊ ဗရုပန်အခဝ်အဲမိၚ်တုဲ အဲသတိက်ဟွံလှိၚ်ရအ္စာ” သၟိၚ်ဂး။ (ဇ—၃၁၄။ အစွောံ။) = “ဆရာ၊ ဒု၊ သ၊ န၊ သောတည်းဟူသော အက္ခရာလေးခုဖြင့် ဟစ်ကြွေးသံကိုကြား၍ ငါအိပ်မပျော်” ဟုမင်းဆို၏။ || “မွဲဂါထာပန်ပိုတ် မွဲပိုတ်ဒစာံအခဝ်ဂှ်။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) =“တစ်ဂါထာလေးပိုဒ် တစ်ပိုဒ်လေးအက္ခရာ။”')
,(15937,3,1,'ခါချဉ်။',NULL)
,(15938,3,13,'(န) ချုပ်နှောင်ခြင်း။ အချုပ်။','ဒးအချုက် = အချုပ်အနှောင်ခံရသည်။ အချုပ်ကျသည်။ အကျဉ်းကျသည်။')
,(15939,3,1,'အကြိုအကြား။ ချောင်။',NULL)
,(15940,3,1,'ချောင်ကြိုချောင်ကြား။',NULL)
,(15941,3,1,'၁။ အခြင်းအရာ။ အကြောင်း။ အကြောင်းအရာ။','“ကၠတ်ထဝ်နန်ထဝ်၊ အသဝ်က္ၜန်က္ၜောဲ။ အခြၚ်ဍုၚ်ဂှ်၊ ဒယှ်ဂၠိုၚ်နဲ။” (လိက်မေဃသန်) = “ရွှေနန်းဆောင်နန်းတော်တို့သည်အံ့ဖွယ်တို့နှင့်ပြည့်စုံ၏။ ထိုမြို့၏အကြောင်းသည် များစွာကျော်စော၏။” || “ဇယဗေဒ၊ ဟီုပၠမွဲတဲ။မွဲသတ္တပ္ပ၊ ဗေဒဟီုသ္ကဲ။ ဣတိဟာသ၊ ဝွံဗေဒမွဲ။ နက္ခယုပြဲ၊ ပန်သ္ကဲဗေဒၚ်။ သာ်ဝွံအခြၚ်၊ ဗေဒၚ်ပန် ရ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဇယဗေဒ၊ သတ္တပ္ပဗေဒ၊ ဣတိဟာသဗေဒ၊ နက္ခယုဗေဒဟူသော ဗေဒင်လေးပုံဖြစ်၏။ ဤကား ဗေဒင်လေးပုံ၏အကြောင်းတည်း။”')
,(15941,3,1,'၂။ အရေးပါသောအဖြစ်အပျက်။ အခါကြီး။','“ဗရုအသံ၊ ဂမြံသဒ္ဒ။ က္တဵုဒှ်အခြၚ်၊ သဘၚ်ဇၞော်ရ။ လုံဍုၚ်တမ္ညဝ်၊ လလောၚ်အဝ်ဇ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “တူရိယာသံတို့ ခြိမ့်ခြိမ့်သဲဆူညံလျက် အခါကြီးပွဲကြီးဆင်နွှဲ၏။ မြို့လုံးအနှံ့ ပဲ့တၚ်ထပ်မျှ မြည်ဟည်းနေ၏။”')
,(15941,3,1,'၃။ အမျိုးအစား။','“လ္ၚီအခြၚ်။” = “အမျိုးပေါင်းတစ်ထောင်။” || “ဗ္ဒဟ်သဘၚ်က္ဍၚ်၊ အခြၚ်နာနာ။ ပေဲါဒဵုပေဲါဍာ်၊ ဂၠိုၚ်သာ်ပြကာ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ပွဲသဘင်ပေါင်းမျိုးစုံကျင်းပ၏၊ကြည်းပွဲရေပွဲစုံလၚ်၏။”')
,(15941,3,1,'၄။ ဂုဏ်သရေ။ အဆင်းအသရေ။ (?)','“အဵုရုပ်အခြၚ်၊ ဟးက္ၜၚ်ထဝ်ယာဲ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ရုပ်အဆင်းအသရေနှင့်ပြည့်စုံသော အို—အမယ့်ချစ်သား။”')
,(15942,3,9,'—မှန်း။ —ကြောင်း။','“အခြၚ်မဒှ်ဨကရာတ် မာၚ်ဗၠာဲဂှ်ဟွံတီ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ဘုရင်ဖြစ်ကြောင်း ထိုလုလင်မသိ။” || ‘အခၚ်’ ဟုလည်းရေးသည်။')
,(15943,3,1,'(ဂီတ) တီးကွက်တီးဟန်။ ကကွက်ကဟန်။','“ညံၚ်တွိၚ်အရာ၊ နစ္စာဂဳတ။ နွံတဴအ ခြာၚ်၊ ရမ်သာၚ်တွိၚ်ရ။” (လိက်ဝိဓုရ) = “အက၊ အဆို၊ အတီးအမှုတ်ကဲ့သို့ တီးကွက်တီးဟန်ဂီတသံရှိ၏။”')
,(15944,3,1,'၁။ ရောင်ခြည်။','“(ကျာ်တြဲ) တၞောဝ်ဒတောဝ်သာကျဝၚ် မၞုံကဵုအခၠၚ်လျးတြဴ။” (ဇ—ဝိဓုရ။ အစွောံ။) = “သာကီဝင်မင်းမျိုးနွယ်ဖြစ်သော ရောင်ခြည်တော်ခြောက်သွယ်ရှိသော မြတ်စွာဘုရား။”')
,(15944,3,1,'၂။ (အလင်းရောင်၏) ထွင်းဖောက်ခြင်း။ (?)','“သဗ္ဗဒိသာသု။ ပ္ဍဲဒိုသ်ဂမၠိုၚ်အိုတ်သီု။သတ္တဗ္ဘန္တရာ။ ၚ်ထပှ်အဗ္ဘန္တိုရ်ဂမၠိုၚ်။ နိဗ္ဗေဓေန။ ဗွဲအခၠၚ်။ အခၠၚ်ဍေံၜါဒိုသ် ဗွဲဒ္ဂူကေတ်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)')
,(15945,3,10,'(န) ဘက်လိုက်ခြင်း။ အဂတိတရား။ မလားအပ်သည်ကိုလားခြင်း။','ဓဝ်အဂတိပန်= (၁၊ ဆန္ဒာဂတိ = ချစ်သဖြင့်ဘက်လိုက်ခြင်း။ ၂၊ ဒေါသာဂတိ = မုန်းသဖြင့်ဘက်လိုက်ခြင်း။၃၊ ဘယာဂတိ = ကြောက်သဖြင့်ဘက်လိုက်ခြင်း။ ၄၊ မောဟာဂတိ = မသိသဖြင့်ဘက်လိုက် ခြင်းတည်းဟူသော အဂတိတရားလေးပါး။) || “စဳရေၚ်သတ္တံဂမၠိုၚ်ဂှ် (မရာတ်) ဂွံဗၠးအဂတိပန်ညိဟာ။” (ဇ—၃၇၈။ အစွောံ။) = “လူအပေါင်းတို့ကို စီရင်သည်မှာ အရှင်မင်းကြီးသည် အဂတိတရားလေးပါးမှ လွတ်ပါ၏လော။”')
,(15946,3,10,'(န) မလားအပ်သည်ကိုလားခြင်း။','‘အဂတိ’ နှင့်အတူတူ။')
,(15947,3,1,'ရိုးရာပုံပြင်။ (folktale)','အဂီုတမၠာ = ရှေးရိုးရာပုံပြင်။ || “သဘဴသၟိၚ် — နူၜါယာံမစိုပ်ပိယာံဂှ် အဂီုမၚ်ဇေန်မၚ်လာဲ ဂပ်ဂဝ်ပၚ်မှိၚ်ရ။” (ဓမ္မသာတ်။ MDT VII) = “မင်းတို့မည်သည်ဒုတိယယံမှ တတိယယံရောက်သည်အထိ ရိုးရာပုံပြင်၊ တဘောင်နိမိတ်စကားနှင့် သမိုင်းစာတို့ကိုနာကြားသင့်၏။”')
,(15948,3,5,'ထိုမှာ။ ထိုနေရာမှာ။','“လ္ပမံၚ်အဂှ်။” = “ထိုနေရာမှာ မနေပါနှင့်။”')
,(15949,3,1,'ကံ့ကော်ပင်။','ပ္ကဴအဂၞု = ကံ့ကော်ပန်း။')
,(15950,3,12,'(န) အရှေ့တောင်ထောင့်။','ဒိုဟ်အဂၞဲ = အရှေ့တောင်ထောင့်အရပ်။')
,(15951,3,5,'အတင်း။ အတင်းအကျပ်။','‘အနိၚ်’ နှင့်အတူတူ။ || “ၜိုန်ညးဂြိုဟ်အိုတ်၊ ဂစိုတ်အဂၞိၚ်။ ဟွံချိုတ်ဂျိုၚ်တဴ၊ ဂွံစဴပသၟိၚ်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “သူတစ်ပါးတို့ အတင်းအကျပ်သတ်ရန် ကြံစည်ပြစ်မှားသော်လည်း မသေဘဲ မင်းအဖြစ်ကိုရ၏။”')
,(15952,3,1,'ကျိုင်းကောင်။',NULL)
,(15953,3,1,'ပုစဉ်းထိုးငှက်။',NULL)
,(15954,3,11,'(န) ၁။ အကျော်။ အကျော်နံ့သာ။ (ပါဠိ—အဂလု)','အဂၠဴဒမျိုၚ် = အကျော်နက်။ || “ကဵုကေတ်နၚ်စလန်အဂၠဴပ္ကဴမြမောဝ်တုဲ—။” (ဇ—၄၇၉။ အစွောံ။) || “မြမောဝ်ပန်သာ် မပ္တံစလန်၊ အဂၠဴ၊ ဂဒဵု၊ ဘုံမသိုန်။” (ဇ—၄၉၇။ အစွောံ။) = “စန္ဒကူး၊ အကျော်၊ ကတိုး၊ ဖုံးမသိန်အစရှိသော နံ့သာမျိုးလေးပါး။”')
,(15954,3,11,'(န) ၂။ ရှားစောင်းလက်ပတ်ပင်။','“လဆောဝ်တုန်ဂှ်၊ ဒှ်ဂစေံပၠန်။ ဂစေံအဂၠောန်၊ ကောန်သာရိကာ။ လဆောဝ်ဒှ်အကၠီု၊ ဗဂီုဂံက်ဂါ။” (လိက်တရဳသံသာ)')
,(15956,3,1,'အချိန်။ အချိန်အတောအတွင်း။','အဃောဂှ် = ထိုအချိန်တွင်။ || “အဃောဏအ်မူကၠုၚ်ကေတ်ရော။” = “ဤအချိန်မှာ ဘာလာယူသလဲ။”')
,(15956,3,7,'ပြုလုပ်နေစဉ်ကိုပြသောစကား။ —စဉ်။ —တုန်း။','“အဃောကွာ်ကၠုၚ် ဆဵုဒးဇြုံရ။” = “လျှောက်လာစဉ် မြွေကိုတွေ့မိသည်။” || “အဃောဗြဲဂူ ညးဒုၚ်ဍာ်ရ။” = “မိုးရွာတုန်း သူရေခံသည်။” || ‘ဒးအဃော’ (ကြိ) လည်းရှု။')
,(15957,3,3,'မကြီးလွန်း မငယ်လွန်း။ ကောင်းတုန်း။ အနေတော်။','“ဆုဏအ် ဟွံဂၠိၚ်ဟွံဂၠေံ အဃောခိုဟ်ရ။” = “ဤသစ်သည် မရှည်မတို အနေတော်ဖြစ်သည်။”')
,(15958,3,1,'အရွယ်၏ကောင်းခြင်းနှင့် ပြည့်စုံတုန်းအချိန်။',NULL)
,(15959,3,10,'(န) အသံပြင်းပြင်း မထွက်သောအက္ခရာ။ သံညင်းအက္ခရာ။ အဃောသ။',NULL)
,(15960,3,1,'(စည်း) (သဗဓ) ‘အဃော’ ရှု။',NULL)
,(15961,3,12,'(န) အင်္ဂါ။','တ္ၚဲအၚာ = အင်္ဂါနေ့။ || ဂြိုဟ်အၚာ = အင်္ဂါဂြိုဟ်။')
,(15962,3,1,'စားကြွင်း။ စားကျန်။','‘ၚး’ (န) ရှု။')
,(15963,3,1,'လက်ပွားခြေပွားရှိသူ။ ငလက်ပွား။ ငခြေပွား။',NULL)
,(15964,3,6,'အတွက်။','“ပုၚ်အၚာန်အဲဂှ် ဗှ်ေလ္ပစထောံညိ။” = “ငါ့အတွက်ထမင်းကို နင်မစားလိုက်ပါနှင့်။”')
,(15965,3,1,'ချင်ခြင်း။ လိုချင်တောင့်တမှု။ အာသာ။','“အၚပ်အဲနွံမွဲသာ်ရ။” =“ငါ့မှာချင်ခြင်းတစ်ခုရှိသည်။” || “ယွံတၠညး၊ အၚပ်အဲသၟိက်ကလၚ်ဓဝ်သၟိၚ်မြာ်ထဝ်ညိအဴ” ဂၞကျာ်ဂး။ (ဇ—၁၅၉။ အစွောံ။) = “မင်းမြတ်၊ ရွှေဥဒေါင်းမင်း၏ တရားကိုနာလိုသော အကျွန်ုပ်ချင်ခြင်းဖြစ်၏” ဟုမိဖုယားဆို၏။ || “အဇ္ၚပ်ဂၞကျာ်၊ သာ်ဝွံဒှ်ကၠာ။” (လိက်ရတနပဇ္ဇောတ) = “မိဖုရား၏ချင်ခြင်းသည် ဤသို့ဖြစ်၏။”')
,(15965,3,4,'ချင်ခြင်းဖြစ်သည်။ အာသာဖြစ်သည်။','“အဲစလဝ်သွစာၚ်ဖဲဒၟံၚ်တုဲ သွစာၚ်ဂှ် အဲဟွံအၚပ်ရ။” = “ကြက်သားဟင်းကို ငါစားထားသည်မှာ ဝနေပြီ ဖြစ်သဖြင့် ကြက်သားဟင်းကို ငါချင်ခြင်းမဖြစ်တော့ပါ။”')
,(15966,3,1,'စိတ်အလို။ စိတ်ဆန္ဒ။ လိုအင်။ လိုချင်တောင့်တမှု။','“သွက်ဂွံအာဂှ် အၚပ်စိုတ်အဲဟွံမွဲရ။” = “သွားရန်ငါ့မှာဆန္ဒမရှိတော့ပါ။”')
,(15967,3,4,'ချင်ခြင်းပြေသည်။ ချင်ခြင်းငြိမ်းသည်။ အာသာပြေသည်။','“သတ်ကြုက်ဂှ် ဇိုန်ကဵုဂၞကျာ်ဂွံစတုဲ အၚပ်ဂှ်ဟဲအာရ။” (ဇ—၂၈၁။ အစွောံ) = “ထိုမိဖုယားသည် ထိုသရက်သီးကိုစား၍ ချင်ခြင်းကိုငြိမ်းစေ၏။” (ညောင်ကန်)')
,(15968,3,1,'အံသွား။',NULL)
,(15969,3,1,'အမူအရာ။ ဟန်။ အသွင်။','“အၚဝ်မကြအ်ဂှ်ပတဴတုဲ လ္ၚာ်တိုန်လတူအကာသတုဲ ‘ဗတာဲ (ပ္ဍဲစက်ဂိတု) ဂှ် ကေတ်ကဵုအဲညိ’ ရဴဝွံဟီုတုဲ—။” (ဇ—၄၅၄။ အစွောံ။) = “ရူးဟန်ကဲ့သို့ပြု၍ မိုးကောင်းကင်သို့ မော်ကြည့်လျက် ‘လမင်းမှယုန်ကို ယူပေးပါ’ ဟုဆို၏။” || “(ဂၞကျာ်ဇၞော်) ပအၚဝ်ယဲတုဲ လုပ်တိက်ဒၟံၚ် ပ္ဍဲဒေန်ကျာ်သြဳဂှ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “မိဖုရားကြီးသည် ဖျားနာဟန်ဆောင်၍ ကျက်သရေရှိသောညောင်စောင်း­ အိပ်နေ၏။” || “(ဣသိစၞာဲဂှ်) — ပအေၚာဝ်မယဲတုဲ သတိက်ဒၟံၚ်ရ။” (ဇ—၅ဝ၅။ အစွောံ။) = “ထိုရသေ့စဉ်းလဲသည် ဖျားနာဟန်ပြု၍ အိပ်နေ၏။” || “ညံၚ်အၚဝ်မကြအ်သ္ဒိုဟ် မသတိက်ဒၟံၚ်ဂှ် သိက်ဂွံဒှ်သာ်ဂှ်ရော။” (ဇ—၄၇၇။ အစွောံ။) = “ရူးမိုက်သောအသွင်ကဲ့သို့ အိပ်နေသည်မှာ အဘယ်ကြောင့်ပါနည်း။”‘သော်လစံက်အေၚာဝ်သၞေၚ်ထိုၚ်ဗၠာဲ။’ (ဇ—၁၆၇။ အစွောံ။) = ‘ပိတုန်းပျို၏အတောင်ကဲ့သို့သောမည်းညိုသည့်ဆံပင်။’ || “(ဗၠာဲသၟိၚ်ဂှ်) အၚဝ်ညးကွာ်တြဴဂှ်ပတုဲ ကွာ်လုပ်အာ။” (ဇ—၁၉၄။ အစွောံ။) = “ထိုမင်းချင်းယောကျာ်းသည် ခရီးသွားသူဟန်ဆောင်၍ လျှောက်ဝင်သွား၏။” || “မပတၠရမျှာၚ် ညံၚ်ကြဝိတ်ထဝ် အၚဝ်ရမျှာၚ်ဗြီု—။” (ဇ—၂၈၄။ အစွောံ။) = “ရွှေကရဝိတ်ကဲ့သို့သောအသံ ဗြဟ္မာမင်း၏အသံကဲ့သို့သော အသံရှင်ဖြစ်၏။” || “ကျိုၚ်ညံၚ်ညးသွဝ်၊ အၚဝ်ဒေဝ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “နတ်ဒေဝါအသွင် တန်ဆာဆင်၏။”')
,(15970,3,12,'(န) ဆရာ။',NULL)
,(15971,3,1,'ကဝိ။ စာဆိုတော်။ စာရေးဆရာ။',NULL)
,(15972,3,1,'ပန်းချီဆရာ။',NULL)
,(15973,3,1,'၁။ ပေစာကူးရေးသူ (ခေတ်ဟောင်းသုံး) ။',NULL)
,(15973,3,1,'၂။ စာရေးဆရာ။ (ယနေ့ခေတ်သုံး)',NULL)
,(15974,3,1,'ရှေ့နေ။',NULL)
,(15975,3,1,'ဂိုဏ်းအုပ်။ ဂိုဏ်းဆရာ။',NULL)
,(15976,3,1,'ဆင်ဦးစီး။',NULL)
,(15977,3,1,'ကျောင်းထိုင်ဆရာတော်။ ဆရာတော်ဘုရားကြီး။',NULL)
,(15978,3,1,'ဒိသာပါမောက္ခဆရာကြီး။','“ဗောဓိသတ်ပိုဲ ဒှ်ဗမၞးအ္စာပါတိမောက္ခ။” (ဇ—၁၁၉။ အစွောံ။)')
,(15979,3,1,'ဓါတ်ဆရာ။ (ဆေးမပေးဘဲ ဓာတ်စာကျွေး၍ ရောဂါကုသသောဆရာ။)',NULL)
,(15980,3,1,'မျက်လှည့်ဆရာ။',NULL)
,(15981,3,1,'တရားဆရာ။',NULL)
,(15982,3,1,'ပန်းရန်ဆရာ။',NULL)
,(15983,3,1,'အနှိပ်သည်။','‘အ္စာကဝတ်’ ဟုလည်း အချို့ရေးသည်။')
,(15984,3,1,'ဗိသုကာဆရာ။ ဆောက်လုပ်ရေးအင်ဂျင်နီယာ။',NULL)
,(15985,3,1,'ဗေဒင်ဆရာ။',NULL)
,(15986,3,1,'ကွက်စိပ်ဆရာ။','“ဥပဇျာဲကီု၊ သီုအ္စာဗဝှ်။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ဥပဇ္ဈာယ်ဆရာသည်၄င်း ကွက်စိပ်ဆရာသည်၄င်း။”')
,(15987,3,1,'ကျောင်းဆရာ။',NULL)
,(15988,3,1,'အလမ္ပာယ်ဆရာ။',NULL)
,(15989,3,1,'လက်သမားဆရာ။',NULL)
,(15990,3,1,'သမားတော်။ ဆရာဝန်။',NULL)
,(15991,3,1,'အဋ္ဌကထာဆရာ။',NULL)
,(15992,3,1,'ဥပ္ပဇ္ဈာယ်ဆရာ။',NULL)
,(15993,3,10,'(န) ကောင်းသောအကျင့်။','‘အနာစာရ’ (န) လည်းရှု။')
,(15994,3,11,'(န) ကောင်းသောကျင့်ဝတ်။','“ပဟိုတ်ကဵုခမဳမွဲမဍိုက်ပေၚ်တဴကဵုအစာရဝတ်ရ အမ္ဗဇာတ်ကျာ်တြဲတွံ။” (ဇ—၁၂၄။ အစွောံ) = “ကောင်းသောကျင့်ဝတ်နှင့်ပြည့်စုံသော ရဟန်းတစ်ပါးကို အကြောင်းပြု၍ အမ္ဗဇာတ်ကို မြတ်စွာဘုရားဟောတော်မူ၏။”')
,(15995,3,1,'ရာထူးကြီးပုဂ္ဂိုလ်။ အကြီးအကဲ။',NULL)
,(15996,3,1,'၁။ ပြည့်စုံခြင်း။ ပြီးမြောက်ခြင်း။','၂။ လျဉ်းပါးခြင်း။ အနက်မပြတ်သားခြင်း။ အနက်ထွေပြားခြင်း။')
,(15997,3,1,'အစီအရင်။ အစီအစဉ်။ အစီအမံ။','“ဒကိုပ်ပၞာန်ဂှ် စဳရေၚ်လဝ်ဗဵုပၞာန်ပန်ကၞိပ်တုဲ အစဳရေၚ်ပၞာန်အိုတ်သီုဂှ် လ္ၚောဝ်ပ္တီသၟိၚ်ရ။” = “စစ်သူကြီးသည် စစ်အင်္ဂါလေးပါးကိုစီရင်ထားပြီး စစ်အစီအရင်အားလုံးကို ဘုရင်အား ရှိခိုးလျှောက်တင်၏။” || “ဒှ်ရသာ်ဂှ် ပိုဲအာဒုၚ်အစဳအရေၚ်သၟိၚ်ဝၚ်ပန်ရ” ဒေဝတဴဗြဴၜါဂး။ (ဇ—၃၈၂။ အစွောံ။) = “ထိုသို့တပြီးကား နတ်မင်းကြီးလေးယောက်၏ အစီအရင်အဆုံးဖြတ်ကို ငါတို့ခံယူကုန်အံ့” ဟုနတ်သမီးနှစ်ယောက်တို့ဆို၏။ || “အတိုၚ်ကသပ်ဂၞန် အစဳရေၚ်သီုဖအိုတ်ဂှ် ဟီုကဵုကောန်ဗြဴသၟိၚ် သီုဖအိုတ်ရ။” (ဇ—၁၂၆။အစွောံ။) = “အလုံးစုံသော အကြံအစည်အစီအမံတို့ကို မင်းသမီးအားပြောပြ၏။”')
,(15998,3,1,'အပြစ်တင်သောစကား။ စောဒနာ။','“အစောညးပြဲ၊ ဂှ်မွဲသာ်သွံ။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “မြတ်သောသူတို့၏ စောဒနာအပြစ်တင်ခြင်းသည်လည်းတစ်ပါး။” || “ကဵုဗၠးဒုတ်ဒေါ၊ အစောဍုၚ်ကွာန်။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “မြို့ရွာ၏ကဲ့ရဲ့ခြင်း၊ အပြစ်တင်ခြင်းမှလွတ်ပါစေ။”')
,(15999,3,1,'အစောက်။ အနက်။ အမြင့်။ (ပါဠိ—ဥဗ္ဗေဓ)','“ပါၚ်တနှိၚ်ဂှ် ဒစာံဟတ်၊ အစံက် (၁၂) ဟတ်သာံဒံၚ်။” (သၠပတ်ဝၚ်ဓါတ်သော်လ္ဂုၚ်) = “ခေါင်းလောင်း၏အဝသည် ရှစ်တောင်ရှိ၍ အစောက်သည် (၁၂) တောင်ရှိ၏။”')
,(16000,3,1,'အကောင်းအဆိုး အရောအနှော။ အကျိုးအပြစ် အရောအနှော။','“အကြာအစံက်အပြာဲဂလာန်ညး ဒၞာဲဂလာန်မၞုံကဵုဂုန် မဒှ်ရတ်ဂှ် ရုဲစှ်လပှ်ဒေပ်လဝ်ကဵုဗိုန်ညိ။” (ဇ—၆၇။ အစွောံ။) = “သူတစ်ပါးစကား၏ အကောင်းအဆိုးအရောအနှောမှ အကျိုးရှိရာရှိကြောင်း ကောင်းနိုးရာရာ ရတနာနှင့်တူသောစကားတို့ကို ရွေးချယ်ကောက်စု သိမ်းဆည်းထားပါလေ။”')
,(16001,3,1,'၁။ စဉ်းစားဆင်ခြင်ခြင်း။',NULL)
,(16001,3,1,'၂။ တိုင်ပင်ခြင်း။ ဆွေးနွေးခြင်း။ စည်းဝေးခြင်း။','ဇြပ်အစၚ်အခြၚ် = စုဝေးတိုင်ပင်ရာဇရပ်။ || “ပ္ဍဲဍုၚ်ဗာရာဏသဳ ပ္ဍဲရုၚ်အစၚ်အခြၚ်ဂှ်ကေုာံမှာဇန်ဂမၠိုၚ် ကၠုၚ်ကောံမွဲဟာန်တုဲ ဂလာန်မဒှ်မ္ၚဵုဂှ် ကတဵုဗဒှ်အိုတ်ရ။” (ဇ—၄၅၃။ အစွောံ။) = “ဗာရာဏသီပြည်ဝယ် မင်းတို့၏ စုဝေးတိုင်ပင်ရာဇရပ်­ စည်းဝေးသော များစွာသောလူအပေါင်း­ မင်္ဂလာပြဿနာသည်ဖြစ်၏။” (ညောင်ကန်) || “ဗှ်ေဟွံဒုၚ်အစၚ်အခြၚ်ကဵုအဲ။” (သၠပတ်ရာဇာဓိရာဇ်) = “ငါ့ကို နင်အတိုင်ပင်မခံ။”')
,(16002,3,1,'မျောက်မောင်းမ။ မျောက်လေဗွေ။',NULL)
,(16003,3,1,'စိုးရိမ်ပူပန်ခြင်း။ သောက။','“ချိုတ်အာသီုဓဝ်အစံၚ်အတူဂှ် စှ်ေဒးနရက်ပၠန်ရ။” (ဇ—၃၁ဝ။ အစွောံ။) = “ပူပန်ခြင်းနှင့်တကွသေသော် ငရဲကျပြန်လိမ့်မည်။” || “အစံၚ်အတူဗွဲမလောန် က္တဵုဒှ်ပ္ဍဲစိုတ်ရ။” (အာန်ဇုနာန်) = “လွန်စွာသောစိုးရိမ်ပူပန်ခြင်း စိတ်­ဖြစ်ပေါ်၏။”')
,(16004,3,1,'ဆရာသမား။','“ကလအ်စအစံၚ်အ္စာ” = “ဆရာသမားများကိုကန်တော့သည်။”')
,(16005,3,1,'၁။ အချဉ်သနပ်။',NULL)
,(16005,3,1,'၂။ ဗူးသီးကြော်၊ ငပေါင်းကြော်။','“တ္ၚဲဏအ် သ္ၚိပိုဲခၞာစအစာတ်လဵုရ။” = “ဒီနေ့ ငါတို့အိမ်မှာ ဗူးသီးကြော် ကြော်စားတယ်။”')
,(16006,3,1,'တစ်ပိဿာ၏လေးပုံတစ်ပုံ။ အစိတ်သား။','“ဍာ်တှ်သမာအစိတ်။” (ဇ—၅၃၅။ အစွောံ။) = “နို့ရည်အစိတ်သား။”')
,(16007,3,10,'(န) မကြံစည်အပ် မကြံစည်နိုင်သောအရာ။ အစိန္တေယျ။',NULL)
,(16008,3,1,'အစဉ်အလာ။','“ပ္ဍဲကဵုအခေါၚ်ဖလာတံဂှ်လေဝ် အစေန်ဟွံမွဲဂှ် လ္ပဗဒှ်ညိ။ အစေန်နွံရောၚ်လ္ပပကဵုလီုညိ။” (သၠပတ်သုရသာ) = “အခွန်အတုတ်တို့­လည်း အစဉ်အလာမရှိသည်ကိုမဖြစ်စေလေနှင့်။ အစဉ်အလာရှိသည်ကိုလည်း မပျက်စေလေနှင့်။” || “အမာတ်ဒကိုပ်ပၞာန်တံဂှ်ထောံကၠေံအစေန်ပဝေဏဳတုဲ သတ်တံဟွံဂွံလၟုဟ်စိုတ်။” (ရာဇာဝၚ်အၚ်ဝ—ဟံသာဝတဳ) (အစေန်= ပဝေဏဳ) = “အမတ်စစ်သူကြီးတို့ အစဉ်အလာကိုစွန့်သဖြင့် လူအပေါင်းတို့သည် စိတ်အေးငြိမ်းခြင်းကို မရကြကုန်။”')
,(16009,3,1,'အစဉ်အဆက်။ မျိုးနွယ်အစဉ်အဆက်။','“ဣဝွံ ဒှ်ပဝေဏဳအစာတမၠာဂမၠိုၚ်အစေန်အဆက် မပ္တံမဟာထေရ်ကဿပရ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ဤသည်မှာ မဟာကဿပမထေရ် အစရှိသောရှေးဆရာအစဉ်အဆက်တို့၏ ပဝေဏီတည်း။” || “လၟေၚ်အစေန်အဆက်ဨကရာတ်တမၠာတမၠာ။” (သၚ်္ခါရလိုက်) = “ရှေးအဆက်အဆက်သော မင်းဧကရာဇ်အစဉ်အဆက်။” || “အစေန်အဆက်၊ စဴစေက်ဆက်က္ၜဝ်။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “အစဉ်အဆက် မြေးမြစ်များဆက်လာ၏။”')
,(16010,3,1,'အစွမ်း။ စွမ်းပကား။ အစွမ်းသတ္တိ။','“သၟိၚ်ဂွံညာတ်ရ၊ တြုံတၠအစောန်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “မင်းသည် လူစွမ်းကောင်းကို မြင်ရလေပြီ။”')
,(16011,3,1,'မနာလိုဝန်တိုခြင်း။ ငြူစူခြင်း။','“(သၟိၚ်အလံၚ်ဒေဝဒတ်ဂှ်) မိၚ်ညးထိုၚ်သးစိၚ်ဇကုတုဲ က္တဵုဗဒှ်အစောန်စိုတ် ပ္ဍဲစိၚ်ပၠန်—။” (ဇ—၁၂၂။ အစွောံ။) = “ဒေဝဒတ်လောင်းမင်းသည်မိမိ၏ဆင်တော်အား သူတကာတို့ ချီးမွမ်းကြသည်ကိုကြား၍ ဆင်­ဝန်တိုခြင်းဖြစ်၏။”')
,(16012,3,1,'အစွမ်းအား။','“ဗွဲအစောန်ဒြဟတ်အဲဝွံဂှ် အဲခၠေဝ်ရော်ဂုန်တြရ” ဒေဝတဴဂး။ (ဇ—၃ဝ၇။ အစွောံ။) = “ငါ၏အစွမ်းအာနုဘော်ဖြင့် သင်၏ကျေးဇူးကို ငါဆပ်အံ့။”')
,(16013,3,1,'အစက်အပြောက်ဖြစ်နေခြင်း။ အစွန်းအကွက်ဖြစ်နေခြင်း။ ပေရေနေခြင်း။',NULL)
,(16014,3,1,'၁။ အဆက်အစပ်။ ထိစပ်ခြင်း။','“ရးဂန္ဓာရကဵုရးကာသိကဂှ် ဒှ်မွဲအစပ်ရောၚ်။” (ဇ—၄ဝ၆။ အစွောံ။) = “ဂန္ဓာရတိုင်းနှင့် ကာသိကတိုင်းတို့သည် တစ်စပ်တည်းထိစပ်နေ၏။”')
,(16014,3,1,'၂။အကျွမ်းဝင်သူ။ ရင်းနှီးသူ။','“ပ္ဍဲကွာန်ဒမာတ်လ္ၚီသ္ၚိဂှ် ဇၞော်ဒမာတ်မွဲဂှ် ဒှ်ဒၟံၚ်အစပ်သၟိၚ် ဍေံသ္ဂေဟ်သွဟ်သန်။” (ဇ—၃၈၇။ အစွောံ။) = “အိမ်ခြေတစ်ထောင်ရှိသော ပန်းပဲရွာ­ ပန်းပဲဆရာကြီးသည် မင်းနှင့်အကျွမ်းဝင်ရင်းနှီးသူဖြစ်၍ အလွန်ကြွယ်ဝချမ်းသာ၏။” || “အဲဟွံမွဲကဵုကလောရ။ဟွံမွဲကဵုအစပ်ရ။” (ဇ—၄၂၃။ အစွောံ။) = “ငါ့မှာ ဆွေမျိုးမရှိ။ သိကျွမ်းရင်းနှီးသူမရှိ။”')
,(16015,3,1,'ရင်းနှီးသောမိတ်ဆွေ။',NULL)
,(16016,3,1,'အစွမ်း။ စွမ်းအား။','“ဗောဓိသတ်ဒှ်သၟာတ္ၚ မၞုံကဵုအစောံမပန်ကံ စိုပ်ဒဵုဍုၚ်သွဝ်တာဝတိၚ်ရ။” = “ဘုရားလောင်းသည် လေးသမားဖြစ်၍ တာဝင်္တံသာနတ်ပြည်သို့တိုင်အောင် ပစ်နိုင်စွမ်းရှိ၏။” || “မိမၜါမိၚ်ဂလာန်ကောန်တုဲ အစောံမသ္ဍိုက်တဴ ကောန်တြုံမွဲတၟံတုဲဖျုန်ဂြိုဟ်ညံၚ်မသပါ်အာ ထပှ်လွးကီု။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “သား၏စကားကိုကြား၍ မိဘတို့သည် တစ်ဦးတည်းသောသားကို ချစ်သောအစွမ်းအားဖြင့် နှလုံးခုနစ်စိတ်ကွဲအံ့သကဲ့သို့ဖြစ်၏။”')
,(16017,3,1,'အင်အား။ ခွန်အား။ စွမ်းအား။','“ဗောဓိသတ်ပိုဲဒှ်ကောန်ကၞုဲအာစိုပ်ဒဒှ်ဗၠာဲတုဲ တၟာကောန်ချေံဗၠာဲ မဍိုက်ပေၚ်တဴကဵုအစောံဒြဟတ်လောန်။” (ဇ—၅၇။ အစွောံ) = “ဘုရားလောင်းသည် မျောက်အမျိုး­ဖြစ်၍ အရွယ်ရောက်လတ်သော မြင်းပျိုပမာဏရှိ၍အားအစွမ်းနှင့်ပြည့်စုံ၏။”')
,(16018,3,1,'ခွန်အား။ သန်စွမ်းခြင်း။ သန်မာခြင်း။','“ကဝွံမွဲ သၟဟ်ရထအစောံအပါ ပ္ဍဲကၞဳပ္ဍဲဍာ်သန်။” (ဇ—၃၈။ အစွောံ။) = “ဤငါးကြီးသည် ကြည်း­၄င်း ရေ­၄င်း ခွန်အားနှင့်ပြည့်စုံ၍သန်စွမ်း၏။” || “ဣဝွံမဒှ်ချေံရတ်မၞုံကဵုဂၟံၚ် မၞုံကဵုဒြဟတ်အစောံအပါ မၞုံကဵုလအာမပြဟ်ဂှ် နွံတဴရ။” (ဇ—စန္ဒကုမာ။ အစွောံ။) = “ဤသည်မှာ ရဲစွမ်းသတ္တိနှင့်တကွ ခွန်အားအစွမ်းနှင့်ပြည့်စုံသော အမြန်နှင့်ပြည့်စုံသော ရတနာမြင်းပေတည်း။” || “မၞုံကဵုဒြဟတ်အစောံအပါ။” (ရာဇာထ္ၜုတ်) || ‘စောံပါ’ (ကြိ) လည်းရှု။')
,(16019,3,1,'အစု။ ဝေစု။ အဖို့။','“(ညးဗၞိက်လီုၜါတၠတံဂှ်) သြော်သဗာန်တရဴအလုံဍုၚ်ပရအ်ပ္တုပ်ပၜါစွံတုဲ အစွံသြော်သဗာန်တရဴ မဒးဇကုဟေၚ် ဂ္ၚေၚ်သွံဗၞိက်ရ။” (ဇ—၃။ အစွောံ။) = “ရွဲကုန်သည်နှစ်ဦးတို့သည် တစ်မြို့လုံးရှိ ခရီးလမ်းကြီးလမ်းငယ်တို့ကို အညီအမျှ နှစ်စုခွဲဝေ၍ မိမိရအပ်သော ခရီးအစုဖြင့်သာလျှင် လှည့်လည်၍ ကုန်ရောင်းကြ၏။” || “အစွံသွက်ဇကုမဂွံကီု အစွံသွက်အဲကီု ကေတ်နၚ်တုဲစဴကၠုၚ်ရ” အ္စာဂးကဵုကွးဂမၠိုၚ်ရ။ (ဇ—၇၁။ အစွောံ။) =“သင်တို့ရအပ်သောဝေစုကို၄င်း ငါ့အဖို့ဝေစုကို၄င်း ယူဆောင်၍ ပြန်လာကြကုန်လော့။” || ‘စွံ’ (န) လည်းရှု။')
,(16020,3,1,'ခွဲဝေခြင်း။ ဝေစု။ (ဇ—၅၆။ အစွောံ။)',NULL)
,(16288,3,1,'ဝေါမြို့။','ကျာ်ဇၞော်အစွောံ = ဝေါဆရာတော်။')
,(16021,3,1,'အဆ။ အတိုင်းအဆ။',NULL)
,(16022,3,1,'ရန်သူပေါရာအရပ်။ အန္တရာယ်များသောအရပ်။','“ဒေါဝ်ဂြိုပ်အဆဴ၊ အပၠဴဝိတ္ထဳ။ အာတဴဒ္ၚဳဒ္ၚဳ၊ ဒေါဝ်ဝေရဳသၞ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “အန္တရာယ်များသောတောလယ် ကျယ် ပြောသောလမ်းခရီးဖြင့် ရန်သူများအကြား သတိဖြင့်ဖြည်းဖြည်းသွား၏။” || “လုပ်ဂြိုပ်အဆဴ၊ညာတ်ဗြဴဂျိကၠာ။ ရုပ်သာ်ဂေါဝ်လောန်၊ ညံၚ်ကောန်ဒေဝါ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “အန္တရာယ်ပေါသော တောသို့ဝင်သည်ရှိသော် နတ်သမီးတမျှ ရုပ်အဆင်းလှပသော နတ်ဆိုးမိန်းမတို့ကိုမြင်၏။” || “ဟွံပါလနၚ်၊ ဒေါဝ်ဂၚ်အဆဴ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “အန္တရာယ်ပေါသော သမုဒ္ဒရာလယ်­ ထိခိုက်မှုမရှိ။ (ဘေးမသီရန်မခ။)” || “တေံဟွံညာတ်သြၚ်၊ ဂၚ်ဇၞော်အဆဴ။” (လိက်ဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ကမ်းမမြင်သော ဘေးရန်ပေါသောသမုဒ္ဒရာ­။”')
,(16023,3,1,'လေ၏မျက်နှာစာ။ လေ၏အဝှေ့။','“ညံၚ်ရဴဍာ်လမၠာၚ်၊ ဂၠးထာၚ်ဒကှ်သွာ။ ဒွံဒးအဆဴကျာ၊ ပေက်အာဘသ္မ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ကြာရွက်ပေါ်­ ငြိတင်နေသောနှင်းပေါက်သည် လေမျက်နှာစာကို ထိမိသည်ရှိသော် ပြာမှုန်ပမာကွဲကာ ကြွေလွင့်သွားရသကဲ့သို့။” || “ကောန်ဍောတ်ဂှ်အဴ၊ ဒးအဆဴကျာ။ ပ္ဍဲဂၚ်ဂှ်ကွေံ၊ ဒတုံစှ်ေအာ။ ဂစေံဗြဴပ္ညဳ၊ ယာံတဴဖဳဒွါ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “ငှက်သားငယ်သည် လေအဝှေ့ကိုထိ၍ မြစ်ထဲသို့ကျသွားရာ မိခင်ငှက်မခမျာ ပူဆွေးငိုကြွေးရှာ၏။” || “ညံၚ်ဗီုပၞာၚ်သ္ဍဴ၊ ဒးအဆဴကျာ။ ခၞပၞာၚ်အိုတ်၊ မဒးပၠိုတ်အာ။” (လိက်ပယးအနိစ္စ) = “လေအဝှေ့ကိုထိသော ဆီမီးကဲ့သို့ မီးလျှံကုန်၍ ငြိမ်းသွားရ၏။”')
,(16024,3,1,'၁။ အဆက်။ ဆက်စပ်နေသောနေရာ။ ဆက်ရာ။',NULL)
,(16024,3,1,'၂။ မျိုးရိုးစဉ်ဆက်။','“တၠညးရာဇာဓိရာဇ်ဂှ် ဒှ်အဆက်တၞောဝ်သၟိၚ်ဝါရေဝ်ရောဝ်ရ။” = “ရာဇာဓိရာဇ်မင်းသည် ဝါရီရူမင်း၏မျိုးရိုးစဉ်ဆက်ဖြစ်သည်။” || “(သၟိၚ်ဂှ်) ဒှ်စဴဗောဓိသတ် မရနုက်ကဵုထပှ်အဆက်ရ။” (ဇ—၄၉၄။အစွောံ။) = “ထိုမင်းသည် ဘုရားအလောင်း၏ ခုနစ်ဆက်မြောက်သောမြေးဖြစ်၏။”')
,(16024,3,1,'၃။ အစဉ်အဆက်။ အစဉ်အလာ။','“သၟိၚ်ၜိုပ်ထဝ်မွဲဂှ် လၟေၚ်ဂ္ၚေၚ်ဇကုအဆက်ဂှ် ဟွံဂ္ၚေၚ်တုဲ ဂကောံဂဍာ်ဗြဴမွဲ မဒဒှ်ေယှ်အာတုဲ—။” (ဇ—၁၆ဝ။ အစွောံ။) = “ရွှေဟင်္သာမင်းသည် မိမိ၏အစဉ်အလာကျက်စားရာ­ မကျက်စားဘဲ တစ်ခုသောကျီးမနှင့်တကွ အကျွမ်းဝင်သွား၏။”')
,(16025,3,1,'ဦးခေါင်းခွံအဆက်။',NULL)
,(16026,3,1,'အဆက်အစပ်။',NULL)
,(16027,3,3,'အစဉ်အဆက်ဖြစ်သော။ အဆင့်ဆင့်သော။','“ယွံတၠညး၊ကြုက်အဘန်တဵုမ္ဂးဂှ် ဒှ်ပြဘိုက်ဒေဝတဴတံ ပ္ဍဲဂြိုပ်ဟေမဝန်တေံရောၚ်အဴ။ ပ္ဍဲဂိုဟ်တၟံထဝ် ဒေဝတဴတံမၚ်လဝ်ဂှ် ဂလာန်အဆက်ဆက် ညးဟီုကၠုၚ်ဂှ် မိၚ်ရအဴ” ဗမၞးတံဂး။ (ဇ—၂၈၁။ အစွောံ။) =“မြတ်သောမင်းကြီး၊ နတ်တို့၏အသုံးအဆောင်ဖြစ်သော အဗ္ဘန္တရမည်သောသရက်သည် ဟိမဝန္တာဝယ် ရွှေဂူ၏အတွင်း­ရှိ၏ဟု အဆင့်ဆင့်အားဖြင့် အကျွန်ုပ်တို့သည် ကြားဘူး၏။” (ညောင်ကန်)')
,(16027,3,5,'အဆက်ဆက်။ အစဉ်အဆက်အားဖြင့်။','“တၞောဝ်ဒတောဝ်မပိုဲလဇုပိုဲ မဒ္ဂေတ်ကၠုၚ်အဆက်အဆက်တေံဂှ် မရှာတ်ဗှ်ဗၞုဟ်တုဲ—။” (ဇ—၁၆၃။ အစွောံ။) = “အကျွန်ုပ်တို့၏အဘအဘိုးတို့ အစဉ်အဆက်ကျင့်သုံးလာခဲ့သာ အနွယ်အစဉ်အလာကို အရှင်မင်းမြတ် အောက်မေ့တော်မူ၍—။”')
,(16028,3,1,'အစဉ်အဆက်။',NULL)
,(16029,3,1,'အဆက်အသွယ်။','“ပ္ဍဲကွာန်ဂှ် မိတ်သဟာဲအဲ အဆက်အၜက်အဲ နွံဂၠိုၚ်သန်ရ။” = “ထိုရွာတွင် ကျွန်တော်၏မိတ်ဆွေ ကျွန်တော်၏အဆက်အသွယ် များစွာရှိသည်။”')
,(16030,3,1,'၁။ (လှေကား) အဆင့်။ အထပ်။','အဆင်တၞိန် = လှေကားအဆင့်။ || အဆင်တိ =မြေညီထပ်။ || အဆင်လတူ = အပေါ်ထပ်။ အပေါ်အဆင့်။ || အဆင်အသၟဝ် = အောက်ထပ်။အောက်အဆင့်။')
,(16030,3,1,'၂။ အမျိုးအစား။ အမျိုးအမည်။','“ခရာလဒု၊ သြေဲကၞုသၚ်။ သြဳသြဳဂြိၚ်ဂြိၚ်၊ဒဗိုန်ပိၚ်မၚ်။ လလောၚ်ကမြဴ၊ အသံဂၞဴဂၚ်။ ဂၠိုၚ်ကဵုအဆင်၊ အခြၚ်နာနာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) (အဆင် = အခြၚ်) = “ခရာ၊ ငြင်း၊ ခရုသင်း၊ ဗုံကြီးဗုံသေးသံတို့သည် သာယာစွာ မြည်ဟည်းနေသည်မှာ ပင်လယ်အဝှမ်းသံသဖွယ်တည်း။ တူရိယာအမျိုးအမည် များလှစွာ၏။')
,(16030,3,1,'၃။ လှိုင်းတံပိုး။ (?)','“ညံၚ်ဇွိုန်အဆင်၊ ဇမောဝ်ဂၚ်ဂါ။” (လိက်ပဒုမဝတဳ) = “ပင်လယ်ရေအယဉ်ရှိ လှိုင်းတံပိုးကဲ့သို့။” || “ဇၞောဝ်အဆင်၊ ပ္ဍဲဂၞဴဂၚ်ဂါ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။)')
,(16031,3,1,'အဆင့်။ အဆင့်အတန်း။ ရာထူးအဆင့်။','“မူအဆံၚ်ကၠေဝ်မက်ညးရော။” = “သူ့ရာထူးအဆင့်ကဘာလဲ။” || “ညးဝွံ နူကဵုအဆံၚ်အ္စာဘာဓမ္မတာမွဲဂှ် အဆံၚ်တိုန်တုဲ ဒှ်ကၠုၚ်အ္စာဘာဇၞော်ရ။” = “သူသည် သာမန်ကျောင်းဆရာတစ်ဦးအဖြစ်မှ ရာထူးအဆင့်တက်ပြီး ကျောင်းအုပ်ဆရာကြီးဖြစ်လာသည်။”')
,(16032,3,1,'အဆောင်အယောင်။ ဘွဲ့ထူးဂုဏ်ထူး။ ရာထူးဋ္ဌာနန္တရ။','“သၟိၚ်ဗြာဇ္ဇ (တၠညး) ခုတ်ယၟုကော်တဴရ။ အဆံၚ်အလံၚ်ကဵုလာဘ် တောတိုန်ပၠန်။” (အကြီုရာဇာဓိရာဇ်) = “အမတ်မင်းဗြာဇ္ဇဟု ဘုရင်သည် အမည်ပေး၍ခေါ်၏။ ရာထူးဂုဏ်ထူးဆုလာဘ်လည်း တိုးပြန်၏။” || “(တၠညး) ကဵုလာဘ်ပဿကာ ပ္တိုန်ကဵုစလးစရာဲ သီုအဆံၚ်အလံၚ်အဝဵုအသဳ (ကုလ္ဂန်အိန်) ။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်ရာဇာဓိရာဇ်သည် လဂွန်းအိန်အား ဆုလာဘ်များနှင့်တကွ ဘွဲ့ထူးဂုဏ်ထူး အခွင့်အာဏာများပါပေး၍ ဂုဏ်ပြု၏။”')
,(16033,3,1,'အမှန်။ အဟုတ်အမှန်။ အမှန်အကန်။','“ဂုန်ကီု ဒုဟ်ကီု ဂွံတီအဆတ် ဂွံမိၚ်အဆတ် ဂွံညာတ်အဆတ်တုဲ—။” (ဇ—၅၂ဝ။ အစွောံ။) = “အကျိုးကို၄င်း အပြစ်ကို၄င်း အဟုတ်အမှန်ကိုသိ အဟုတ်အမှန်ကိုကြား အဟုတ်အမှန်ကိုမြင်ပြီးလျှင်—။”')
,(16034,3,5,'ဟုတ်မှန်စွာ။ မှန်ကန်စွာ။ တပ်အပ်သေချာစွာ။','“ယွံဝိသာခါ၊ ခမဳဗြဴသၟတ်ဝွံဂှ်မူဂိတုမူတ္ၚဲ မဒုၚ်ပယၚ်ရော။ စဳစတ်တီတုဲ ဍေံမတန်ဂၠံဂဝ်ဂှ် နူမဒှ်ခရှ်ဟာ၊ ပ္ဍဲကာလမဒှ်ပယၚ်တုဲ မတန်ဂၠံဂဝ်ဟာ၊ ကဵုဂွံတီဗွဲအဆတ်ညိ” ထေရ်ဂး။ (ဇ—၁၂။ အစွောံ။) = “ဒကာမဝိသာခါ၊ ဤရဟန်းမငယ်သည် ပဋိသန္ဓေတည်သည်မှာ လူဖြစ်စဉ်တုန်းကလား၊ ရဟန်းဖြစ်ပြီးမှ ပဋိသန္ဓေတည်သလား၊ သုတ်သင်စိစစ်၍ အဟုတ်အမှန်အားဖြင့် သိပါရစေ။” || “သကိုပ်က္ၜၚ်ဂှ် ဗစာရဏာပိုၚ် ခြာစံၜတ်ရံၚ်တုဲ ဒဒှ်ကလော်ဗြဴဂှ် တီကေတ်ဗွဲအဆတ်ရ။” (ဇ—၁၉၆။ အစွောံ။) = “သင်္ဘောသူကြီးသည် ဆင်ခြင်ပိုင်းခြားစစ်ဆေး၍ ဘီလူးမ၊ဖြစ်ကြောင်းကို တပ်အပ်သေချာစွာသိ၏။” || အဆောတ် (န) ‘အဆတ်’ ရှု။')
,(16035,3,1,'အရေး။ အကြောင်း။ အမှု။ ကိစ္စ။','“တုဲကျာ်သၟာန်ကၠာ၊ မွဲဝါပၠန်ရ။ မူဆေၚ်ရာနွံ၊အဆောံကိစ္စ။ ဂမဳပ္တီပၠန်၊ တဲပ္ဍုန်သိသ။ အဲဍိက်ရံၚ်လွဳ၊ ပ္ကီုလွဳရိယျ။ မိမၜါတၠ၊ ဒှ်တဴရအဴ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “နောက်ထပ်တစ်ဖန် မြတ်စွာဘုရားမေးတော်မူပြန်၏၊ ဘာတော်စပ်ခြင်းရှိ၍ အဘယ်အရေးကိစ္စရှိပါသနည်း။ ထိုရဟန်းသည် ဦးထိပ်လက်တင်လျက်ဆို၏၊ တပည့်တော်လုံ့လပြု၍ ကြည့်ရှုစောင့်ရှောက်သည်မှာကား မိဘနှစ်ပါးဖြစ်ပါသည်ဘုရား။”')
,(16036,3,1,'‘အသောံအယာ’ ရှု။',NULL)
,(16037,3,1,'အခြံအရံနတ်သမီး။','“သီုကဵုအဆေဝ်ဗလှ် မတ္ၜန်တ္ၜောဲတဴကေုာံသၟတ်ဝုတ်ဂမၠိုၚ်ဂှ်မူပြာသာတ်ပြာသာတ်ဂှ်ရောကောန်။” (သၠပတ်သုရသာ) = “ကညာပျိုများနှင့်ပြည့်နှက်နေသောအခြံအရံနတ်သမီးများရှိသော ထိုပြာသာဒ်သည် အဘယ်ပြာသာဒ်ပါနည်းချစ်သား။”')
,(16038,3,1,'မင်းနောက်လိုက်အမှုထမ်း။','“ဣသိစဏာဲဂမၠိုၚ်ဂှ် ပြာံကၠေံတုဲ ဒဒှ်အဆေဝ်ဗွက်သၟိၚ်ဂှ် ပရအဴ” ပြောဟိတ်ဂးကဵုသၟိၚ်။ (ဇ—၄၈၇။ အစွောံ။) = “ရသေ့စဉ်းလဲအပေါင်းတို့ကိုလူထွက်စေပြီးလျှင် မင်းနောက်လိုက်အမှုထမ်းပြုကုန်လော့။”')
,(16039,3,1,'နတ်သမီး။','“ပ္ဍဲဒေါဝ်အဆေဝ်သွဝ်တာဝတိၚ်တေံဂှ် ဂၞကျာ်လုပ်လၟိဟ်ဗြဴအဆေဝ်သွဝ်မွဲကီု။” (ဇ—၄၁၅။ အစွောံ။) = “တာဝင်္တံသာနတ်ပြည်ရှိ နတ်သမီးတို့၏အလယ်­ မိဖုရားသည် နတ်သမီးတစ်ယောက်အဖြစ် စာရင်းဝင်၏။” || “ကောန်ဗြဴဝုတ်ဂှ် ဍေံပကၚ်ရၚ်ရုပ်မတုပ်တဴ ညံၚ်ကောန်ဒေဝတဴဗြဴအဆေဝ်သွဝ်ကီု။” (ဇ—၃၈၇။ အစွောံ။) = “ထိုသမီးပျိုသည်နတ်သမီးတမျှသော ရုပ်အဆင်းကိုဆောင်၏။”')
,(16040,3,10,'(န) အသွင်သဏ္ဍာန်။ အမူအရာ။ ပုံဟန်။','“ယွံကောန်အံက်မ၊ အဇထဝ်သောန်။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “သွန်းလောင်းထားသော ရွှေစင်ရုပ်ထုပုံဟန်ရှိသော အိုချစ်သား။” || “သၟတ်ဗြဴဂှ် ဂၞိၚ်သဏာၚ်တုဲ ဇၚာၚ်ၜတ်တကတ် — က္ၜံၚ်တံၚ်ယျ အဇကောန်ဒေဝတဴဗြဴအဆေဝ်သွဝ်ကီု။” (ဇ—၅၂၃။ အစွောံ။) = “ထိုမိန်းမငယ်သည် သေးသွယ်သောခါး နူးညံ့သောတင်ပါးရှိ၏။ ဒူးခြေသလုံးတို့ကား နတ်သမီး၏ပုံအသွင်ကဲ့သို့ရှိ၏။” || “တုဲတွာ်အာရ၊ အဇညးဇၞော်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “လူကြီးဟန်အမူအရာဖြင့် လျှောက်သွား၏။”')
,(16041,3,4,'ဟန်ဆောင်သည်။ အမူအရာကိုတုပသည်။','“တၠညးရာဇာဓိရာဇ် ပအဇဟွံတီဟွံညာတ်—။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်ရာဇာဓိရာဇ်သည် မသိမမြင်ဟန်ဆောင်တော်မူ၏။” || “မန်တံပအဇညံၚ်မကျ။” (အကြီုရာဇာဓိရာဇ်) = “မွန်တို့သည် ရှုံးသကဲ့သို့ဟန်ဆောင်၏။” || “ပအဇကၠုၚ်နူဗဂေါ။” (အကြီုရာဇာဓိရာဇ်) = “ဗဂိုးမှလာဟန်ပြု၏။” || ‘ပအလိုက်အဇ’ (ကြိ) လည်းရှု။')
,(16042,3,1,'၁။ အစား။ ကိုယ်စား။','“အဲအာဟွံသလး ဗှ်ေအာကဵုအဇာအဲဂွံဟာ။” = “ငါမသွားအားပါ၊ ငါ့ကိုယ်စား နင်သွားပေးလို့ရမလား။”')
,(16042,3,1,'၂။ အမျိုးအစား။ အတန်းစား။','“ၜိုတ်မၞိဟ်အဇာဗှ်ေ အဲသ္ဇက်ဒးပဂရုနွံဟာ။” = “နင့်လိုအတန်းစားလူလောက်ကို ငါဂရုစိုက်နေစရာ လိုသလား။” || “အပေါတ်ဂှ် အဇာခိုဟ်ကဵုအဇာဓမ္မတာ နွံၜါအဇာရ။” = “အဲဒီပစ္စည်းဟာ အကောင်းစားနှင့်သာမန်အစားဆိုပြီး နှစ်မျိုးနှစ်စားရှိတယ်။”')
,(16043,3,10,'(န) ‘အာဇာနေယျ’ ရှု။',NULL)
,(16044,3,1,'ဘိုးလေး။ (အဘိုးထက်ငယ်သောသူ)',NULL)
,(16993,3,1,'ဂရိလူမျိုးတို့ရိုးရာနတ်။',NULL)
,(16045,3,1,'ရှက်ဖွယ်ဇာတိသရုပ်အမှန်။','‘အဇေဟ်အမေဟ်’ နှင့်အတူတူ။ || “လၟေၚ်အဇှ်ေ ညးသ္တီစုတ်တုဲ။” (သၠပတ်ရာဇာသာန်) = “မိမိ၏ရှက်ဖွယ်ဇာတိဂှ် သူတစ်ပါးတို့ သိရှိသွားပြီး—။” || “ဟာဲစိုတ်အဇှ်ေ၊ ဂုန်ဗှ်ေလောဘ။ ဗှ်ေဒးပယျဲ၊ ဘဲကိလေသ။” (လိက်လက္ခဏပိ) =“ဟယ်—ရှက်ဖွယ်ဇာတိသရုပ်အမှန်ရှိသောစိတ်၊ နင်လောဘကြီးခြင်းကြောင့် ကိလေသာဘေး၏နှိပ်စက်ခြင်းကို နင်ခံရ၏။” || “ဟာဲမတ်အဇှ်ေ၊ ဗှ်ေရောၚ်ညာတ်ကၠာ။” (လိက်ကောန်သၟိၚ်ပိ။မာံခစုန်အံက်။) = “ရှက်ဖွယ်ဇာတိ ဟယ်—မျက်စိ၊ နင်သည်သာ ဦးစွာမြင်၏။” || “ဟာဲဇိုၚ်အဇှ်ေ၊ ဗှ်ေတအ်သ္ပအ်သာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ရှက်ဖွယ်ဇာတိရှိသောဟယ်ခြေထောက်၊ နင်တို့သည် သိမ်ဖျင်းပေါ့ဆဘိ၏။”')
,(16046,3,1,'သံသရာ­အဖန်တလဲလဲကျင်လည်နေရခြင်း။','“ပိုဲသတ္တံသမ္တီဂး ညံၚ်ရဴဟွံဒးချိုတ်မွဲလှ်ေ ဝိုတ်ထောံအဇှ်ေသံသာ လဟိၚ်ဗက်အာကာမဒုစရိုတ်။” (သြဝါဒဒဳပနဳ)')
,(16047,3,1,'(ဖောက်ပြန်သော) ဇာတိသရုပ်အမှန်။','“ဂွံညာတ်အဇှ်ေအလၚ်၊ စၚ်ခြၚ်ပ္ဍဲကဵုစိတ္တ။ စဴဒှ်အသုဘဍာံရ၊ ကာယျဇၟာပ်ညးအဲ။” (လိက်ပရေၚ်ခန္ဓ) = “လူတိုင်း၏ကိုယ်ကာယခန္ဓာသည် အသုဘအလောင်းကောင်မျှသာဖြစ်ကြောင်း စိတ်တွင်ဆင်ခြင်လတ်သော်၄င်း၏ဖောက်ပြန်သောဇာတိသရုပ်အမှန်ကို မြင်ရပေမည်။”')
,(16048,3,1,'(မကောင်းသော) အကျင့်စရိုက်။ ရှက်ဖွယ်ဖြစ်သော ဇာတိသရုပ်အမှန်။','“လ္ပကဵုညးတီအာ အဇိဟ်အမိဟ်ဇကုညိ။” = “မိမိ၏ရှက်ဖွယ်ဇာတိသရုပ်အမှန်ကို သူတစ်ပါးတို့မသိပါစေနှင့်။”')
,(16049,3,1,'ဇယ်။ (တောက်ကစားသောဇယ်)',NULL)
,(16050,3,10,'(န) အမျိုးအမည်မထင်ရှားသူ။ ဂုဏ်သိန်သေးနုပ်ညံ့ဖျင်းသူ။ သာမညလူ။',NULL)
,(16051,3,10,'(ကြိဝိ) တစ်ခုနှင့်တစ်ခု၊ တစ်ဦးနှင့်တစ်ဦး အချင်းချင်း။ အပြန်အလှန်။',NULL)
,(16052,3,10,'(န) သိခြင်း။',NULL)
,(16053,3,1,'အညှော်နံ့။','ဒးအညှဝ် = အညှော်မိသည်။ အညှော်နံ့ကိုရှူမိ၍ ရောဂါရသည်။ (အနာကို ပြင်ပမှရောဂါပိုးဝင်၍ အနာယဉ်းလာသည်။')
,(17112,3,1,'မီးဖွားပြီးစ သွားလာမိ၍ မိန်းမကိုယ်­ ဖြစ်ပေါ်လာသောရောဂါ။',NULL)
,(16054,3,1,'ဦးစီး။ ထိပ်သီး။ ဒိုး။',NULL)
,(16055,3,1,'ငပြောက်ကျား။ (နွား၊ ခွေးစသည်၏ အရောင်အဆင်း)',NULL)
,(16056,3,1,'ငကွက်ကျား။ (နွား၊ ခွေးစသည်၏ အရောင်အဆင်း)',NULL)
,(16057,3,1,'တောကြက်။','“သဘဴအဍေဝ်၊ ဂတေဝ်သဒ္ဒံါ။” (လိက်ပဒုမဝတဳ) = “တောကြက်တို့သဘာဝ အသံပြုတွန်မြည်၏။” || “ဇရေၚ်ဇိုၚ်လှာ၊ စာၚ်ဍာ်ဗြုကွက်။ အဍေဝ်ဂြဴကီု၊ သီုစက္ကဝက်။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ရေအိုင်အနီး­ ရေကြက်တွန်မြည်၏၊ တောကြက်နှင့်စက္ကဝက်လည်းတွန်ကျူး၏။”')
,(16058,3,1,'လူလည်။ လူပေါ်လူဇော်။','“ဟာဲအဍိုဟ်ဍိုပ်၊ မူဆေၚ်က္ဍိုပ်မ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ဟယ်လူလည်၊ နင့်သောက်လုပ်ဘာရှိသလဲ။”')
,(16059,3,10,'(နဝိ) သေးငယ်သော။ သိမ်မွေ့သော။',NULL)
,(16059,3,10,'(န) မြူ။ အဏုမြူ။',NULL)
,(16060,3,1,'အလွန့်အလွန် သေးငယ်သောမြူမှုန်။ အဏုမြူ။','လွဟ်အဏုလက်ကၠိုက်= အဏုမြူလက်နက်။')
,(16061,3,1,'နာနတ်သီး။','“ရာန်ဏာအဏှာတ်၊ သီုဗြာတ်သီုတ္ၜဴ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။)')
,(16062,3,5,'ဤမှာ။ သည်မှာ။',NULL)
,(16063,3,1,'၁။ တာဝန်။ တာဝန်ခွဲဝေ၍ ကျရောက်သောတာဝန်။','“အာစိုပ်ဒြာဲထဝ်၊ သၟိၚ်ဓဝ်စၚ်ခြၚ်။ ပရအ်အတာ၊ ခါဂှ်ကဵုမၚ်။” (လိက်မေဃကောန်ဒြာဲ) = “ရွှေသမင်ရှိရာရောက်လတ်သော်ဘုရင်သည်တိုင်ပင်၍ တာဝန်ခွဲဝေကာ သမင်ကိုစောင့်စေ၏။” || “သရာဲသ္ဇၚ်ကွေံ၊ သရာဲချေံမာ။ဗိုလ်ညးညးပြေၚ်၊ လမေၚ်အတာ။” (လိက်ဇိဝှစက္က) = “လှံကိုင်သူရဲတို့သည်၄င်း မြင်းစီးသူရဲတို့သည်၄င်း သူ့စစ်သည်များနှင့်သူ တာဝန်စဉ်အတိုင်း စီတန်းထား၏။” || “ယွံကောန်ဂၠုသ္ဍိုက်၊တြုံသိုက္ခမာ။ — နာဲဒုၚ်အတာ၊ အရာအံက်မ။” (လိက်ဝိဓူရ) = “နူးညံ့သောယောကျာ်းဖြစ်သော အိုချစ်သားကြီး၊ ဖခင်၏အရာကို သင်တာဝန်ခံပါလော့။” || “ဇန်ဂမၠိုၚ်ရော၊ ဟောဒြာညဳသာ။ ဗဝ်သဗာန်ပၠန်၊ ဖန်လဝ်အတာ။” (လိက်တလိၚ်ပန်) = “လူတို့သည် ညီညွတ်ကုန်၍လမ်းပြင်မြေဖို့ရန်အတွက် တာဝန်ခွဲဝေထားကြကုန်၏။”')
,(16063,3,1,'၂။ တာ။ (၇) တောင်ရှိသော အတိုင်းအတာ။','“ဗွိုက်ဍုၚ်တုန် (၅၈ဝ) အတာသဒှ်။” (ရာဇာထ္ၜုတ်) = “မြို့ပတ်လည်လုံးပတ်သည် (၅၈ဝ) တာရှိလိမ့်မည်။” || ‘မၚ်လံၚ်’ နှင့်အတူတူ။')
,(16063,3,1,'၃။ ထန်းသီးရောင်အမွေးရှိသောနွား။','“အဗုအာမ္ဂး အတာလိုက်။” = “ငဖြူ (နွား) သွားလျှင် ငနီ (နွား) ရောက်လာမည်။”')
,(16063,3,1,'၄။ အရံအတား။ တံတိုင်း။ (အဗအရရိရေ)','“ဇၞော်ဍုၚ်ဂှ် ထပှ်ယောဇနာ ကဵုလဗိုန်လဝ်ဇၟာပ်ဇၟာပ်အတာ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မြို့၏အကျယ်အဝန်းမှာ ခုနစ်ယူဇနာရှိ၍ အရံအတားနေရာတိုင်းကို အခိုင်အခံ့ပြုထားစေ၏။” || “ဗိုန်က္ညန်ယဲသ၊ မြုပြအတာ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “တံတိုင်း၊ မျှော်စင်၊ အရံအတားတို့သည် အလွန်တရာခိုင်ခံ့ကုန်၏။”')
,(16064,3,10,'(န) အတိတ်ကာလ။',NULL)
,(16065,3,10,'(နဝိ) (ဉာဏ်ပညာ၊ အကျင့်သီလ စသည်တွင်) မိဘထက်မြတ်သော (သားသမီး) ။ မိဘထက် အရည်အချင်းသာလွန်သော (သား) ။ အတိဇာတ (သား) ။','‘အနုဇာတ’၊ ‘အဝဇာတ’ တို့ကိုလည်းရှု။')
,(16066,3,10,'(န) (စာပေ) လွန်လွန်ကြူးကြူး ဖွဲ့ဆိုရေးသားသောကြောင့် သင့်သောဒေါသ။ အတိဝုတ္တဒေါသ။',NULL)
,(16067,3,10,'(န) (စာပေ) အတိသယဝုတ္တိအလင်္ကာ။ လွန်ကဲစွာဖွဲ့ဆိုရေးသားသောအလင်္ကာ။',NULL)
,(16068,3,10,'(နဝိ) အတုလ။ တူသူမရှိသော။ အတုမရှိသော။ မနှိုင်းယှဉ်နိုင်သော။','“လတူကွိုတ်ဇၟူ၊ တြုံအတူလ။ ညံၚ်ဗီုစရာဲ၊ အိန်နာဲဒေဝ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ဆင်ပြောင်၏ကျောက်ကုန်းထက်­ အတုမရှိသောယောကျာ်းသည် သိကြားနတ်မင်း၏ ဂုဏ်သရေကဲ့သို့ပင်တည်း။”')
,(16069,3,6,'‘လတူ’ ရှု။',NULL)
,(16070,3,1,'သင်္ကြန်။','သ္ဘၚ်အတး = သင်္ကြန်နှစ်သစ်ကူးပွဲတော်။ || အတးစှ်ေ = သင်္ကြန်ကျသည်။ || အတးတိုန် = သင်္ကြန်တက်သည်။')
,(16071,3,11,'(န) အတိတ်။ အတိတ်ကာလ။','အတိက်တေံ = လွန်လေပြီးသောကာလ။')
,(16072,3,1,'အထက်ဆင့်။ အပေါ်အကွပ်။','အတၚ်ဂၞိန် = ထမီအထက်ဆင့်။ || အတၚ်န= တောင်းအကွပ်။ တောင်းအနားသပ်ကွင်း။')
,(16073,3,5,'အတင်း။ အဓမ္မ။ တဇွတ်ထိုး။',NULL)
,(16074,3,6,'အတိုင်း။','“ညံၚ်အတိုၚ်ပၟိက်စိုတ်ကောန်ဗြဴနာဲပိုဲတံ သၟိက်ဂွံပ္တုဲကုသဵုဂှ် ပိုဲကဵုအခေါၚ်ဖအိုတ်ရ။” (ဇ—၃၅၉။ အစွောံ။) = “ကုသိုလ်ကောင်းမှုပြုလိုသော သင်တို့၏သမီးဆန္ဒအတိုင်းအားလုံးငါတို့အခွင့်ပေးပါမည်။” || “အတိုၚ်ညးဗ္ကန်လဝ် ပိုဲအာဆဵုညးရ။” = “သူမှာထားသည့်အတိုင်း ကျွန်တော်တို့ သူနှင့်သွားတွေ့သည်။” || ‘တိုၚ်—၃’ (ဝိ) လည်းရှု။')
,(16075,3,5,'ထိုအတိုင်း။ အရှိအတိုင်း။','“ပုၚ်ဍုန်လဝ်မွဲထၟာဲဂှ် ညးမွဲလေဝ်ဟွံဒှ်စ သှ်ေဒၟံၚ်အတိုၚ်ဂှ်ရ။” = “ချက်ထားသော ထမင်းတစ်အိုးသည် တစ်ယောက်မျှမစားဖြစ်ဘဲ ထိုအတိုင်းကျန်နေသည်။”')
,(16076,3,1,'အတိုင်ပင်။','‘တိုၚ်ဗၚ်’ (ကြိ) ၊ ‘ဒုၚ်အတိုၚ်အဗၚ်’ (ကြိ) တွင်ရှု။')
,(16077,3,1,'အတုံ့အလှည့်ကျေးဇူးပြုခြင်း။ အပြန်အလှန်ကြင်နာခြင်း။ အပြန်အလှန်လက်ဆောင်ပေးခြင်း။','“ဨကရာဇ်ကဵုဨကရာဇ်သၟဟ် အတုန်အခၠေဝ်နွံရၚ်သ္ကံ။” (အကြီုရာဇာဓိရာဇ်) = “မင်းဧကရာဇ်နှင့်မင်းဧကရာဇ် အချင်းချင်းညီညွတ်၍ အပေးအယူ အတုံ့အလှည့်ကျေးဇူးပြု ခြင်းရှိသည်။”')
,(16078,3,1,'နှင်း။ ဆီးနှင်း။','‘လတိုပ်’ နှင့်အတူတူ။ || “ညံၚ်အတိုပ်ရော၊ ဃောဟေမန္တာ။ ဂၠုကြိုပ်မံၚ်ပၠန်၊ မွဲတန်သေၚ်ဟာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ဆောင်းဟေမန္တအတွင်း ဆီးနှင်းကဲ့သို့ မှောင်ရီအုံ့ဆိုင်းနေ၏။”')
,(16079,3,1,'၁။ တံခါးမင်းတုပ်။',NULL)
,(16079,3,1,'၂။ တိုင်။ ကျောက်တိုင်။','ဒယိုင်အတှ် = ကြငှန်းတိုင်။ || အတှ်ဆုဣန္တက္ခဳ = နန်းတော်မုခ်ဦးတိုင်ကြီး။ || “ပ္ဍဲအဒေါဝ်အတှ်ပန်ဂှ် ညးပ္ဍုန်ဓုပ်ပြကာရကျာ်။” (သၠပတ်အဓါန်မသုန်။ အစွောံ။) = “ကြငှန်းတိုင်လေးခုအလယ်­ ထုပိကာကို တင်ကုန်၏။”')
,(16080,3,1,'ကျောက်တိုင်ကြီး။','“ညံၚ်ဗီုအတှ်တၟံမဗိုန် မသက္ကုကသဳဂှ်—။” (ဇ—ဝိဓုရ။ အစွောံ။) = “မယိုင်မလဲခိုင်မြဲသော ကျောက်တိုင်ကြီးကဲ့သို့။”')
,(16081,3,5,'ဟိုမှာ။ ဟိုနေရာမှာ။',NULL)
,(16082,3,1,'တိုက်တွန်းခြင်း။ လှုံ့ဆော်ခြင်း။ အားပေးအားမြှောက်ပြုခြင်း။',NULL)
,(16083,3,1,'ကိုလူအို၊ ယောကျာ်းအို။',NULL)
,(16084,3,1,'သက်တူရွယ်တူအစား။','အထက်ပိုဲ = တို့အရွယ်။ တို့အစား။')
,(16085,3,1,'အထောက်အကူ။ ထောက်ကူပေးခြင်း။',NULL)
,(16086,3,1,'ကူဖော်လောင်ဖက်။',NULL)
,(16087,3,1,'အထောက်အပံ့။ ထောက်ပံ့ခြင်း။ အထောက်အကူ။',NULL)
,(16088,3,1,'ပန်းပွင့်ချပ်။','‘ထိုက်’ ဟူ၍လည်းရေးသည်။')
,(16089,3,1,'အခိုက်အတန့်။ တစ်ခဏ။ နှစ်ခုစပ်ကြားကာလ။ တစ်သက်လျာ။ (ပါဠိ—တာဝကာလိက)','“ဓရ်အနတ္တမ္ဂးဂှ် သဘဴဓရ်မဒှ်လီုဒၟံၚ် အထိုက်အတန်ဍေံကဵုဍေံသၟးရ။ = “အနတ္တတရားဟူသည် သူ့အခိုက်အတန့်နှင့်သူ ဖြစ်ပျက်နေသော တရားသဘောသာဖြစ်သည်။” || “တသ္မိံအန္တရေ။ ပ္ဍဲအကြာဂှ်။ ဝါ။ ပ္ဍဲအထိုက်အတန်ဂှ်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) =“ထိုကာလစပ်ကြား­။ ဝါ။ ထိုအခိုက်အတန့်­။”')
,(16090,3,5,'ထိုက်သင့်သည့်အားလျော်စွာ။ ထိုက်တန်စွာ။',NULL)
,(16091,3,1,'ထင်မြင်ချက်။ မှန်းဆချက်။','“ဓဝ်ကျာ်တြဲကၞာတ်၊ မွဲဟွံညာတ်ကီု။ အထေၚ်ညးလ္အိတ်၊ ညးမတိတ်ဟီု။” (လိက်ဝိဓူရ) = “မြတ်စွာဘုရား၏တရားတော်ကို တစ်စုံတစ်ယောက်မျှမမြင်ဘဲ မိမိတို့၏ထင်မြင်ချက်ကိုသာ ပြောဆိုနေကြကုန်၏။”')
,(16092,3,1,'စိတ်အထင်။ စိတ်ထင်မြင်ချက်။','“အထေၚ်စိုတ်ဗှ်ေ၊ ဗှ်ေဟီုကဵုအဲ။” (လိက် ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “နင့်စိတ်ထင်မြင်ချက်ကို နင်ငါ့ကိုပြော၏။” || “အထေၚ်စိုတ်ဍိက်၊ ဟွံကၞိက်ဗဒန်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ကျွန်တော်မျိုး၏စိတ်ထင်မြင်ချက်ကို မဖုံးကွယ်မထိမ်ချန်ပါ။”')
,(16093,3,4,'အထင်ကြီးသည်။',NULL)
,(16094,3,4,'အထင်သေးသည်။','“ယွံမရာတ်၊ ကောန်ဂဟပတိဝွံ ဍေံအထေၚ်ဍောတ်ကဵုပိုဲလောန်အာ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ထိုသူကြွယ်သားသည်အကျွန်ုပ်တို့ကို အထင်သေးလွန်းသည်။”')
,(16095,3,4,'အထင်လွဲသည်။ အထင်အမြင်လွဲမှားသည်။',NULL)
,(16096,3,1,'မြစ်ကွေ့။ ပင်လယ်ကွေ့။ လေးကိုင်းသဏူဌာန် ပင်လယ်ကမ်းရိုးတန်း။','“တမြးဗတဳအထံၚ်ၜဳဇၞော်။” (ရာဇာထ္ၜုတ်) = “ပင်လယ်ကွေ့ရှိသဲသောင်မြေ။” || “ဒေါဝ်ဖၞုၚ်အထံၚ်၊ ဟဳမံၚ်ရရော။” (လိက်ရတနပဇ္ဇောတ) = “ပင်လယ်ရေၚန်အလယ်­ မျောနေရသကဲ့သို့။”')
,(16097,3,1,'ချီးမွမ်းခြင်း။ ချီးကျူးခြင်း။ အချီးအမွမ်း။','“ယာတ်ပ္ဍဲသုသာန်ဂှ် မဂပ်ဂဝ်ကဵုပိုဲခမဳရောၚ်။ ဒှ်အထိုင်အသးကျာ်အရှန် ပစ္စေဂဗုတ်တံရောၚ်။” (ဇ—၈၇။ အစွောံ။) =“သုသာန်­စွန့်ထားသော အဝတ်ပုဆိုးသည် ရဟန်းတို့အား အပ်စပ်၏။ ဘုရားရဟန္တာ ပစ္စေကဗုဒ္ဓာတို့၏ ချီးမွမ်းရာဖြစ်၏။”')
,(16098,3,1,'၁။ အထွတ်။ အခေါင်အဖျား။ အထွတ်အထိပ်။ အထွတ်အမြတ်။','“ဗြဴတၠသစ္စသာ်ဂှ် ဒှ်အထောတ်ဗြဴဂမၠိုၚ်ရအဴ။” (ဇ—၃၂ဝ။ အစွောံ။) = “ထိုကဲ့သို့သောသစ္စာရှင်မိန်းမသည်ကားမိန်းမတကာတို့၏ အထွတ်အခေါင်မိန်းမမည်၏။” || “(ကၠဵုဂြိုပ်ဂှ်) ပ္ဍဲအထောတ်တၟံမသၠုၚ်ဂှ် တိုန်ဒၟံၚ်တုဲ—။” (ဇ—၃၃၅။ အစွောံ။) = “မြေခွေးသည် မြင့်သောတောင်အထွတ်သို့ တက်နေ၍—။” || “ခါဗောဓိသတ်၊ အထောတ်လိုက်ဗာ။” (လိက်ဇိဝှစက္က) = “လောက၏အထွတ်အခေါင်ဖြစ်သောဘုရားလောင်း။”')
,(16098,3,1,'၂။ အထွတ်ပြာသာဒ်။ ဦးကင်း။',NULL)
,(16099,3,1,'အထွတ်အထိပ်။','“တဳလမၞုံကုပိုန် မစိုန်ဒှ်တဴအထောတ်ကၞောတ်သာကျဝၚ်တံညးဂမၠိုၚ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “သာကီဝင်မင်းအပေါင်းတို့၏ အထွတ်အထိပ်ဖြစ်တော်မူထသော မြတ်စွာဘုရား။”')
,(16100,3,1,'အထွတ်အထိပ်ယောကျာ်း။ ယောကျာ်းကောင်းယောကျာ်းမြတ်။','“မဟောဟ်သဓဝွံ — ဒှ်အထောတ်တြုံမပြဲရောၚ်သွံ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မဟောသဓသည်ကား အထွတ်အထိပ်ယောကျာ်းမြတ်ပေတည်း။”')
,(16101,3,1,'စုလစ်မွန်းချွန်။','“ပ္ဍဲဇြပ်မၞုံကဵုအထောတ်ဒြၚ်ဂှ် ကျာ်တြဲပဒတဴတုဲ—။” (ဇ—၁၄၉။ ဇ—၁၅၂။ ဇ—၂၈၁။ အစွောံ။) = “စုလစ်မွန်းချွန်တပ်သောကျောင်း­ (မြတ်စွာဘုရား) နေတော်မူစဉ်—။” (ညောင်ကန်)')
,(16102,3,1,'အထွတ်အထိပ်မိန်းမ။ မိန်းမကောင်း။','“ယဝ်ရဍေံကလေၚ်စဴမ္ဂး ဒှ်ဗြဴမၞုံကဵုသစ္စဝါဒဳရ။ ဒှ်ဗြဴမဗိုန်ကဵုတၠသ္ၚိရ။ ဒှ်အထောတ်ဗြဴမပြဲရ။” (ဇ—၄ဝ၁။ အစွောံ။) = “အကယ်၍သူပြန်လာပါက သူသည် သစ္စာရှိသောမိန်းမပေတည်း။ လင်ယောကျ်ား­ မြဲသောမိန်းမပေတည်း။ အထွတ်အမြတ်မိန်းမပေတည်း။”')
,(16103,3,1,'တော်လေးဝ။ (အမရာဒေဝီ၊ စန္ဒကိနနရီ၊ မဒ္ဒီဒေဝီ၊ သမ္ဘူလမိဖုရားတည်းဟူသော မိန်းမမြတ်လေးပါး။)','‘တၟပ်ဗြဴပန်’ နှင့်အတူတူ။')
,(16104,3,1,'အိမ်ဦးကင်း။',NULL)
,(16105,3,1,'အထွတ်အထိပ်။ အထွတ်အခေါင်။ အဆုံးစွန်။ အခေါင်အဖျား။ (climax)','“နအထောတ်အဖျာဓမ္မဒေသနာမြဴဝွံဂှ် ကျာ်တြဲတွံကဵုတုဲ ကျာ်ဗစိုပ်ကဵုသစ္စပန်တုဲ ကျာ်တြဲသၟဟ်ကၠေံဇာတ်ရ။” (ဇ—၁၅၆။ အစွောံ။) = “ဤသို့သဗ္ဗညုမြတ်စွာဘုရားသည် — ဓမ္မဒေသနာ၏အထွတ်ကို ယူတော်မူ၍ အလွန်လည်းသစ္စာတို့ကို ပြတော်မူ၍ ဇာတ်ကိုပေါင်းတော်မူ၏။” (ညောင်ကန်) || “ကျာ်တြဲမစိုန်ဒှ်တဴကၞောတ်ဂဥုပ်ဓုပ်ပြကာ အထောတ်အဖျာလိုက်ပိဂှ်ကီု။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “လောကသုံးပါး၏အကြီးအမှူး အထွတ်အဖျားဖြစ်တော်မူသော မြတ်စွာဘုရား။” || “ဂွံအာစိုပ်ကၞတ်အထောတ်အဖျာဝိပဿနာညာန်တုဲ။” (ပြကိုဟ်နရသာသန။ သဳလဝန္တ။) = “ဝိပဿနာဉာဏ်၏ အထွတ်အဖျားသို့ရောက်၍။”')
,(16106,3,1,'၁။ ဦးထုပ်။ ဦးရစ်။ ဦးပေါင်းထုပ်။ ခေါင်းပေါင်း။','“ယွံအစာ၊ ၜးထဍံၚ် ဂိုၚ်အထုပ်လၟုဟ်ဝွံဂှ် မူဒၞာဲမသ္အာဂှ်ရော။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ဆရာ၊ နံငယ်ပိုင်းကိုလဲ၍ဦးရစ်ကိုချ၍ ယခုအဘယ်ကိုသွားအံ့နည်း။” || “(လၟဂှ် တၞဟ်နဂစိုတ်စိၚ်) ဍေံဂလုက်လဝ်ဗၞောဟ်ဍေံသၠောံသ္ၚာ ဍေံစုတ်အထုပ်တုဲ ဍေံဂ္ဇအ်သ္ၚဳဒၟံၚ်ရ။” (ဇ—၂၂၁။ အစွောံ။) = “ထိုမုဆိုးသည်ဆင်တို့ကိုသတ်ရန် လှံကိုကွယ်ဝှက်ထားပြီးလျှင် သင်္ကန်းကိုခြုံ၍ ဦးရစ်ကိုစွပ်၍ ငြိမ်သက်စွာထိုင်နေ၏။')
,(16106,3,1,'၂။ ပန်းပွင့်ဖတ်။',NULL)
,(16106,3,1,'၃။ အဖုံး။ အကာအကွယ်။ အမှေး။','အထုပ်သရ = အနာအမှေး။ || အထုပ်သြိုဟ် = ဇာဘော်ဒီ။ ချွေးခံ။')
,(16107,3,1,'သင်းကျစ်။ နဖူးတွင်ဆင်ရသော မင်းမြှောက်တန်ဆာ။','“(ဗောဓိသတ်) သၠိုက်စုတ်အထုပ်ၝောံကိုတ် အပ္ဍဲက္ဍိုပ်တုဲ—။” (ဇ—၁၈၁။ အစွောံ။) = “(ဘုရားလောင်းသည်) သင်းကျစ်ကို ဦးခေါင်း­စွပ်၍—။” (ညောင်ကန်)')
,(16108,3,1,'အစိတ်အခြမ်း။','ပညောန်မွဲအထေဝ် = ဖရဲသီးတစ်စိတ်။')
,(16109,3,1,'ဝမ်းဘဲ။','အဒါၜဳ = စစ်စလဳ။ ရေဝမ်းဘဲ။ || အဒါက္ၜၚ် = မန္ဒာလီဝမ်းဘဲ။ || အဒါဓါတ်= ဓါတ်ဖြင့်ဖောက်သောဝမ်းဘဲ။')
,(16110,3,11,'(န) ‘အာဒိ’ ရှု။',NULL)
,(16111,3,1,'သားကောင်ရှာငှက်။',NULL)
,(16112,3,1,'ဦးချိုကားသောနွား။ ငချိုကား။',NULL)
,(16113,3,1,'ဆင်းရဲမွဲတေသူ။ ငမွဲ။',NULL)
,(16114,3,12,'(န) တနင်္ဂနွေ။','တ္ၚဲအဒိုတ် = တနင်္ဂနွေနေ့။ || ဂြိုဟ်အဒိုတ် = တနင်္ဂနွေဂြိုဟ်။')
,(16115,3,11,'(န) သူတစ်ပါး၏ဥစ္စာကိုခိုးခြင်း။ အဒိနနာဒါန။',NULL)
,(16116,3,1,'၁။ အကြောင်းတရား။ ဖြစ်မြဲတရား။ (?)','“သံၚ်သာမတွံဂးခြိုၚ်ဂှ် သတ္တံဂမၠိုၚ်ဒဴကၠေံဟွံဒှ်ရောၚ် ကျာ်မတွံ။ ယြဴတၠပညာပူဂဵုမွဲ ဗစာရဏာအဒိန်အဒါန် တီသာ်ဝွံတုဲ ပတိပတ်မွဲမသ္ဂောံဗၠးနူသံၚ်သာဂှ် ဂပ်ဂဝ်သ္ပဗက်ဟေၚ်။” (သၠပတ်သတိပထာန်) = “သံသရာတည်းဟူသောလှောင်ချိုင့်မှ သတ္တဝါအပေါင်းတို့သည် လွတ်အောင်မရှောင်နိုင်ကုန်ဟု ဘုရားဟောတော်မူ၏။ပညာရှိပုဂ္ဂိုလ်သည် ဖြစ်မြဲတရားကိုဆင်ခြင်လျက် ထိုသို့သိနားလည်ပြီးနောက် သံသရာမှလွတ်မြောက်ကြောင်းဖြစ်သောကျင့်စဉ်ကို လိုက်နာကျင့်သုံးအပ်၏။”')
,(16116,3,1,'၂။ စည်းစိမ်ဥစ္စာ။ (?)','“အဒိန်အဒါန်၊ ပိုန်ဟာန်ဒြပ်ညး။ ဆဇြေဟ်ကမတ်၊ ဗၞတ်ညိကီုသ္ဂး။ ယောၚ်စိုတ်တုဲသၟတ်၊ ကၠတ်ကေတ်ဒြပ်ညး။” (လိက်ပယးအနိစ္စ) = “သူတစ်ပါး၏စည်းစိမ်ဥစ္စာကို မြက်တစ်မျှင်ပမာဏ အနည်းငယ်မျှဟုဆိုကာ သိလျက်နှင့်ယောင်၍ ခိုးယူ၏။”')
,(16117,3,11,'(န) စိတ်ဆင်းရဲခြင်း။ ကံမကောင်းအကြောင်းမလှဖြစ်ခြင်း။ ဆိုးကျိုးသက်ရောက်ခြင်း။',NULL)
,(16118,3,1,'နှာမောင်း။','အဒံါစိၚ် = ဆင်နှာမောင်း။')
,(16119,3,1,'၁။ ခါးစည်းပတ်အိတ်ရှည်။','‘ဒဲါ’ ဟုလည်းရေးသည်။')
,(16119,3,1,'၂။ လိပ်ပြာ။ (?)','“ပ္ကဴကြက်စၠန် — ပကၚ်ရၚ်လဝ်မြမောဝ် မဗ္ၜူကဵုစိုတ်ထိုၚ်သာဲအဒဲါ—။” (ဇ—ဝိဓုရ။ အစွောံ။) = “စန္ဒကူးနံ့သာပန်းသည် အမွှေးရနံ့ကိုဆောင်လျက် ပိတုန်း၊ ပျား၊ လိပ်ပြာတို့၏စိတ်ကို ဆွဲဆောင်ယစ်မူးစေ၏။”')
,(16120,3,1,'အလယ်။ ဗဟိုချက်။','အဒေါဝ်ကသီု = မိုးလယ်ခေါင်။ || အဒေါဝ်ၜဳ = ပင်လယ်အတွင်း။ || အဒေါဝ်ဍုၚ် = မြို့လယ်။ || အဒေါဝ်ပေဲါ = ပွဲအလယ်။ || အဒေါဝ်တရဴ = လမ်းခုလပ်။ || “—၊ ကၠဵုဂွံဏာဖျုန်အဒေါဝ်ဂှ်တုဲ ပိုဲညးၜါဟုံထောံသၟးရ” ဖေအ်ၜါဂး။ (ဇ—၄ဝဝ။ အစွောံ။) =“မြေခွေးက ငါးအလယ်သားကို ရယူသွားသဖြင့် ငါတို့နှစ်ဦးသည် သက်သက်ဆုံးရှုံးရ၏” ဟုနှစ်ခုသောဖျံတို့ဆို၏။ || “ဇမၞော်ဂြိုပ်ဂှ်၊ စှ်ယောဇနာ။ ဇၞတ်ကြၚ်အာသွံ၊ ဂွံအဒေါဝ်ကၠာ။” = “ထိုတော၏အရွယ်ပမာဏကား ဆယ်ယူဇနာရှိ၏၊ ခြေဦးတည့်ရာသွားရင်း တောအလယ်သို့ရောက်၏။”')
,(16121,3,1,'အခြေအနေ။ အသွင်သဏ္ဍာန်။ အသွင်အပြင်။',NULL)
,(16122,3,1,'မိုက်မဲတွေဝေသောသူ။ ငမိုက်တုံး။ ငမိုက်ခဲ။ ငမိုက်သား။ (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။စန္ဒိမာ။)','‘ဒိုဟ်ဂွိုၚ်’ (နဝိ) လည်းရှု။')
,(16123,3,1,'ညီမောင်။ ညီလေး။ (ချစ်စနိုးခေါ်ဝေါ်သည်)',NULL)
,(16124,3,10,'(န) အရေးကြီးသော အရေးပါသော လိုရင်းဖြစ်သောအရာ။ အဓိက။ ပဓါန။',NULL)
,(16125,3,11,'(န) ၁။ အဓိကရုဏ်း။ ရုန်းရင်းဆန်ခတ်ဖြစ်ခြင်း။ ငြင်းခုံခိုက်ရန်ဖြစ်ခြင်း။ (ပါဠိ—အဓိကရဏ)','အဓိကဵုဂလာကဵုဗၟာ = ကုလားဗမာအဓိကရုဏ်း။')
,(16125,3,11,'(န) ၂။ ဘေးဒုက္ခ။ဘေးအန္တရာယ်။ အခက်အခဲ။ ပြဿနာ။','“ပရိုက်ဘဲကလောအဲဂမၠိုၚ်ဂှ် ဝေၚ်အာနူအဲမွဲတုဲ မူရဴညးမွဲ မသ္ဂောံလလံကၠေံပရိုက်ဘဲဂှ် ဟွံမွဲရ။ အဲလလံကၠေံအဓိကဵုကလောအဲဂမၠိုၚ်ညိ’ ဗောဓိသတ်သၟိၚ်ခဍာ်ချပ်။” (ဇ—၁၄ဝ။ အစွောံ။) (အဓိကဵု = ပရိုက်ဘဲ) = ‘ငါ့ကိုထား၍ ငါမှတစ်ပါးသောငါ့အဆွေအမျိုးတို့၏ဘေးဒုက္ခကို ငြိမ်းစေခြင်းငှာ စွမ်းနိုင်သောသူမည်သည်မရှိ။ ငါသည် ထိုဘေးဒုက္ခကို ငြိမ်းစေအံ့’ ဟု ဘုရားလောင်းကျီးမင်းကြံ၏။” || “ယွံမဟာရာဇ၊ ဒဒိုက်ပိုဲသတ်ဂမၠိုၚ် မက္တဵုဒှ်အဓိကဵု သ္ကာတ်မြဟ်လောန်က္ဍၚ်သန်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “မြတ်သောမင်းကြီး၊အကျွန်ုပ်တို့သတ္တဝါအပေါင်းအား အလွန်ပြင်းထန်သော ဘေးဒုက္ခဖြစ်ပေါ်လျက်ရှိ၏။” || “ဗမၞးဍုၚ်ကလိၚ်ကရး အာတ်ဏာစိၚ်ရတ်ပစ္စယနာဂဵုဂှ် ပဗဓါန်သၟိက်ကဵုဗြဲဂူ တၞဟ်နလလံကၠေံအဓိကဵုကၞောဝ်ဗယဵုရောၚ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ကာလိင်္ဂရာဇ်တိုင်းမှပုဏ္ဏားတို့ ပစ္စယဆင်ဖြူတော်ကို တောင်းခံခဲ့ခြင်းသည် ငတ်မွတ်ခြင်းဘေးဒုက္ခကို ငြိမ်းစိမ့်သောငှာ မိုးရွာစေလို၍သာဖြစ်၏။”')
,(16125,3,11,'(န) ၃။ ကောလာဟလ။ အုတ်အုတ်ကျက်ကျက်ကြွေးကြော်ခြင်း။ (uproar)','“ဆဂှ်ဟွံသေၚ်ပၠန်တုန် ဒဵုကဵုစိုပ်ဘုံဗြီုအကနိဋ္ဌာတေံ ကၞုက်ကၞာဲအဓိကဵုဒှ်တိုန်အာရ။” (ဇ—၄၂၈။ အစွောံ။) (ကၞုက်ကၞာဲ = အဓိကဵု) = “(ထိုမျှမက) အကနိဋ္ဌဗြဟ္မာ့ပြည်တိုင်အောင် ဤကောလာဟလသည်လည်း ရောက်၏။” (ညောင်ကန်)')
,(16126,3,10,'(န) အကြီးအကဲ။ ဥသျှောင်။ အဓိပတိ။','အဓိပတိကၟိန်ဍုၚ် = နိုင်ငံတော်၏ဥသျှောင်။ (Head of State) || အဓိပတိဂကောံအလဵုအသဳ = အစိုးရအဖွဲ့၏ဥသျှောင်။ (Head of Goverment)')
,(16127,3,1,'အဓိပတိတရားလေးပါး။','“စိုတ်ဇၞော်၊ ပညာဇၞော်၊ သဒ္ဓါဇၞော်၊ လွဳဇၞော် ဍိုက်ပေၚ်တဴကဵုအဓိပတိပန်သာ်။” (ဇ—၃၄ဝ။ အစွောံ။) = “စိတ်ဆန္ဒကြီးခြင်း၊ ပညာကြီးခြင်း၊ သဒ္ဓါတရားကြီးခြင်း၊ ဝဳရိယကြီးခြင်းဟူသော အဓိပတိတရားလေးပါးနှင့် ပြည့်စုံ၏။”')
,(16128,3,11,'(န) အဓိဋ္ဌာန်။','သ္ပအဓိထာန် = အဓိဋ္ဌာန်ပြုသည်။')
,(16128,3,11,'(ကြိ) အဓိဋ္ဌာန်သည်။ အဓိဋ္ဌာန်ပြုသည်။','“မၞိဟ်တံဂှ် ညးအဓိဋ္ဌာန်ကေတ်တုဲ ညးဒဂိုန်သဳဥပုဟ်ရောၚ်။” (ဇ—၃ဝဝ။ အစွောံ။) = “လူတို့သည် အဓိဋ္ဌာန်၍ ဥပုသ်သီလဆောက်တည်ကုန်၏။”')
,(16129,3,10,'(န) ဆိုလိုရင်းအနက်။ အဓိပ္ပါယတ္ထ။',NULL)
,(16130,3,11,'(န) အဓိပ္ပါယ်။ အနက်။',NULL)
,(16131,3,11,'(န) ရှည်သောခရီး။ ရှည်သောကာလ။ အဓွန့်။ (ပါဠိ—အဒ္ဓါန)','“လုကဴအဓါန်မသုန်စှ်ောသၞာံ မလအ်အာတုဲ—။” (ဇ—၅၃ဝ။ အစွောံ။) = “အနှစ်ငါးဆယ်သောကာလကြာမြင့်လတ်သော်—။” || “ယွံခမဳတံ၊ ပ္ဍဲသာသနာဝွံ သောတာပတ္တိမဂ် — ဖျေံကၠေံလွဳ ဟွံကလိဂွံတုဲဂှ် လုကဴအဓါန်မဂၠိၚ်သ္ၚောဲဟေၚ် မဒးစံၚ်တူဒၟံၚ်ရ။” (ဇ—၃။ အစွောံ။) = “ရဟန်းတို့၊ ဤသာသနာတော်­ သောတာပတ္တိမဂ်ကို ဝီရိယလျှော့ခြင်းကြောင့် မရသည်ဖြစ်၍ အခါလေးမြင့် စိုးရိမ်နေရလတ္တံ့။” || “မိတ်မဆာန်နူအဓါန်မလအ်—။” (ဇ—၃၄၉။ အစွောံ။) = “ရှည်ကြာသောကာလမှ ချစ်ခင်လာခဲ့သောအဆွေခင်ပွန်း။” || “သ္ကဵုဂွံပ္တုဲဒါန်၊ အဓါန်ဗွဲကြဴ။” (လိက်တရဳသံသာ) =“နောက်ကာလတွင် အလှူဒါနပြုရပါစေသား။” || “ပ္ဍဲဂြိုပ်ဝွံရ၊ ပလဝ်သုသာန်။ တန်တဴအဓါန်၊ထာန်ဝွံရအဴ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ဤတော­သာ သုသာန်ပြုထားပြီး ဤအရပ်­သာ အတည်တကျ အရှည်သဖြင့်နေထိုင်ပါ၏။”')
,(16132,3,4,'ခရီးရှည်ထွက်သည်။','“(ဗောဓိသတ်) ဂိုၚ်ကေတ်တံသ္ၚု သီုပုၚ်ဂွဳတုဲ ကွာ်တြဴအဓါန်ရ။” (ဇ—၁၇၉။ အစွောံ။) = “ဘုရားလောင်းသည် ရိက္ခာဆန်ရင်းကို၄င်း ထမင်းထုပ်ကို၄င်း ယူ၍ခရီးရှည်သွား၏။” || “ညးဇၞးပိုတ်မွဲ ဍေံကွာ်တြဴအဓါန်—။” (ဇ—၇၈။ အစွောံ။) =“တစ်ယောက်သောဇနပုဒ်သားသည် ခရီးရှည်သွား၏။”')
,(16133,3,1,'ရှေ့လာမည့်အချိန်ကာလ။',NULL)
,(16134,3,1,'ကမ္ဘာတည်သ၍ ကာလအပိုင်းအခြား။',NULL)
,(16135,3,10,'(န) မသူတော်တရား။ မတရားသောအမှု။ အဓမ္မ။',NULL)
,(16135,3,10,'(ကြိဝိ) နိုင်ထက်စီးနင်း။ အဓမ္မ။အတင်းအကျပ်။','“သၟိၚ်တုန်လေဝ် ဒ္ဂေတ်ဗက်အဂတိပန်တုဲ ဒှ်အဓမ္မရောၚ်။” (ဇ—၃၉၆။ အစွောံ။) = “မင်းသည်လည်း အဂတိလေးပါးသို့လိုက်၍ အဓမ္မမင်းပြု၏။”')
,(16136,3,5,'မတရားသဖြင့်။ နိုင်ထက်ကလူ။','“(သၟိၚ်ဂှ်) ပ္ဍဲအဂတိဂမနပန်ဂှ်တန်ဒၟံၚ်တုဲ ပကၚ်ရၚ်မၚ်မွဲကၟိန်ဍုၚ် ဗွဲအဓမ္မဂှ်ရ။” (ဇ—၅၂ဝ။ အစွောံ။) = “ထိုမင်းသည် အဂတိတရားလေးပါး­တည်နေ၍ မတရားသဖြင့် တိုင်းပြည်ကိုအုပ်ချုပ်၏။”')
,(16137,3,1,'မတရားမှု။ အနိုင်အထက်ပြုခြင်း။','“အမာတ်ဒကိုပ်ပၞာန်သၟိၚ်ပဥ္စာလဂှ် ပွအဓမ္မဂှ်ပတုဲ—။” (ဇ—၅၂ဝ။ အစွောံ။) = “ပဥ္စာလမင်း၏အမတ်သေနာပတိတို့သည် အနိုင်အထက်ပြုကုန်၍—။”')
,(16138,3,10,'(န) တရားမစောင့်သောမင်း။','“သၟိၚ်အဓမ္မရာဇာဂှ် ချိုတ်အာတုဲရ။” (ဇ—၁၉၄။ အစွောံ။) = “တရားမစောင့်သောမင်းသည် သေသွားလေပြီ။”')
,(16139,3,12,'(န) ဘုရားတရားမကြည်ညိုသောသူ။ တရားမစောင့်သောသူ။','“ပြောဟိတ်လေဝ် လောဘထနေန်စိုတ်ပ္ဍဲဒြပ်ဂှ် ဒှ်အဓမ္မိကရ။” (ဇ—၃ဝ၉။ အစွောံ။) = “ပုရောဟိတ်သည်လည်း ဥစ္စာ­တပ်စွန်း၍ အလိုရမ္မက်ကြီးသဖြင့် တရား­မတည်သောသူတည်း။”')
,(16140,3,11,'(န) ဖြစ်လတ္တံ့သော ရောက်လတ္တံ့သောကာလ။ အနာဂတ်။',NULL)
,(16141,3,11,'(န) အရိယာလေးဆင့်တွင် တတိယအဆင့်­ တည်သောပုဂ္ဂိုလ်။ ကာမဘုံသို့ပြန်မလာသူ။ အနာဂါမ်။',NULL)
,(16142,3,10,'(န) ယုတ်မာသောအကျင့်။ မကျင့်အပ်သောအကျင့်။ ဖောက်ပြန်သောအကျင့်။လွန်ကျူးသောအကျင့်။','“သမ္ဘာဗောဓိသတ်ဂှ် ဍေံဒ္ဂေတ်တဴပွအနာစာရ ကေုာံတလခွါရ။” =“ဘုရားလောင်း၏မယားသည် ရွာစားနှင့်တကွ ဖောက်ပြန်သောအကျင့်ကိုကျင့်၏။” || “မူရဴခမဳမွဲမပအာတဴအနာစာရရော။” (ဇ—၃၄၄။ အစွောံ။) = “အဘယ်ရဟန်းတို့သည်ကား မကျင့်အပ်သောအကျင့်ကို ကျင့်ကုန်သနည်း။” (ညောင်ကန် || ‘အစာရ၊ အာစာရ’ (န) လည်းရှု။')
,(16143,3,11,'(န) ‘အာဏာစက်’ ရှု။',NULL)
,(16144,3,10,'(နဝိ) ကိုးကွယ်ရာမရှိသော။ အားကိုးရာမရှိသော။ အကူအညီမဲ့သော။ ဆင်းရဲမွဲတေသော။','“ယွံတၠညး၊ တၠညးပကၠေံဂမှဳမ္ဂးဂှ် ပိုဲဍိက်ညးဂမၠိုၚ်ဂှ် ဒှ်ဒဒိုက်ကၠၚ်ကၠောန်အနာထရအဴ” ဂၞကျာ်ဂမၠိုၚ်ဂး။ (ဇ—၅၂၅။ အစွောံ။) = “အရှင်မင်းကြီး၊ အရှင်မင်းကြီးရဟန်းပြုပါကကျွန်တော်မအပေါင်းတို့သည် အထီးကျန်ကုန်လျက် ကိုးကွယ်ရာမရှိတော့ပြီတကား။” || “ယွံကောန်အဲသုတသောမသ္ဍိုက်ယာဲဟိုဲ၊ နာဲထောံကၠေံယာဲတုဲ ဒဒိုက်ယာဲအနာထရသွံကောန်။” (ဇ—၅၂၅။ အစွောံ။) = “သားတော်သုတသောမ၊ သင်ချစ်သားသည် မယ်တော်အား ပစ်ခွါသွားပါကမယ်တော့်မှာ အားကိုးရာမရှိပြီတကား။” || “တြုံကဵုဗြဴဂှ် ဒိုက်လောန်အနာထရ။ ပုၚ်ဟွံဖဲဂၞဴမွဲလှ်ေရ။” (ဇ—၄၁။ အစွောံ။) = “ထိုလင်မယားတို့သည် အလွန်အမင်းဆင်းရဲ၍ ကူညီမည့်သူမဲ့၏။ထမင်းဝမ်းဝအောင် မစားရစဖူး။” || ‘ညးမွဲဇကုမွဲအနာထ—။’ (ဇ—၇၈။ အစွောံ။) = ‘တစ်ကိုယ်တည်း အားကိုးရာမဲ့သည်။’')
,(16145,3,11,'(န) အာပတ်မဟုတ်ခြင်း။ အာပတ်မသင့်ခြင်း။ (ပါဠိ—အနာပတ္တိ)',NULL)
,(16146,3,5,'အမှန်စင်စစ်။ အမှန်တကယ်။','“သၟိက်ဒှ်ရာဲသဳ၊ အနဳကာလ။ ဇၟာပ်ကောန်ဂကူ၊ လ္ဂူကဵုမိမ။ မိမသ္ဍိုက်လောန်၊ ကောန်ဂှ်မူလ။ သာ်ဝွံအနဳ၊ ဒှ်ရာဲသဳရ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “လူချစ်သောပီယဆေးကို အမှန်လိုချင်ပါက အမျိုးကောင်းသားတိုင်းသည် မိဘအပေါ် ရိုးသားသစ္စာရှိပါ။ မိဘချစ်သောသားသမီးသည်ကား ပီယဆေးအမှန်ပင်ဖြစ်တော့သည်။” || “ဝဳပက်ဂှ်ပ္ညုၚ်၊ ဗက်ကၠုၚ်အနဳ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “ထိုဝိပက်သည် အမှန်တကယ်လိုက်လာ၏။”')
,(16147,3,9,'ကဲ့သို့။ သဖွယ်။','“မုက်ညံၚ်ဂိတု၊ အနုထာၚ်သွာ။ အိက်ရုဲစောန်ကၠိ၊ ဟွံဂွံမြိပါ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “လဝန်းကဲ့သို့သောမျက်နှာ ကြာလက်ကဲ့သို့ မစွန်းထင်း မှဲ့မည်းမစွဲ ပကတိဖြူစင်၏။” || “သလးကောန်ဂၠု၊ အနုထာၚ်သွာ။” (လိက်ပဒုမဝတဳ) = “ကြာလက်ကဲ့သို့ဖြူသော သားဦးကိုမွေးဖွား၏။”')
,(16148,3,10,'(နဝိ','န) ‘အဏု’ နှင့်အတူတူ။')
,(16149,3,10,'(နဝိ) (ဉာဏ်ပညာ၊ အကျင့်သီလ စသည်တွင်) မိဘတို့နှင့်တန်းတူရှိသော (သားသမီး)။ မိဘနှင့် အရည်အချင်းတူသော (သား)။ အနုဇာတ (သား) ။','‘အဝဇာတ’၊ ‘အတိဇာတ’တို့ကိုလည်းရှု။')
,(16150,3,11,'(ကြိ) ခွင့်ပြုသည်။ ခွင့်ပေးသည်။','“အဲတိတ်ပခမဳရ။ မရာတ်အနုညာတ်ကဵုအဲညိရ” ပြောဟိတ်ဂး။ (ဇ—၂၉ဝ။ အစွောံ။) = “(မြတ်သောမင်းကြီး) ၊ အကျွန်ုပ်သည် ရဟန်းပြုအံ့။ အကျွန်ုပ်အား ရဟန်းအဖြစ်ကို ခွင့်ပြုလော့” ဟုပုရောဟိတ်ဆို၏။ (ညောင်ကန်) || “ဂဥုဲမသုန်မတ်ဂှ် ကုခမဳမယဲဂှ် ကျာ်အနုညာတ်ရ။” (ဇ—၄ဝ၆။ အစွောံ။) = “ငါးပါးသောဆေးတို့ကို ဖျားနာသောရဟန်းတို့အား မြတ်စွာဘုရား ခွင့်ပြုတော်မူသည်။” || “ကလောပိုဲဂမၠိုၚ်ယဝ်ရအနုညာတ်ကဵုအဲဟီုဂှ် အဲသၟိက်ဂွံဟီုမွဲပါၚ်ညိ” ခဍာ်ဂး။ (ဇ—၂၇ဝ။ အစွောံ။) = “ငါတို့ဆွေမျိုးအပေါင်းတို့က ငါ့ကိုပြောခွင့်ပြုပါလျှင် စကားတစ်ခွန်းပြောလိုပါ၏။”')
,(16150,3,11,'(န) သဘောတူခြင်း။ ခွင့်ပြုခြင်း။ အခွင့်ပေးခြင်း။','အနုညာတ်ကျာ်တြဲ = မြတ်စွာဘုရား၏ အခွင့်ပြုတော်မူခြင်း။ || အနုညာတ်သၟိၚ် = မင်း၏အခွင့်ပေးခြင်း။ (ပါဠိ—အနုညာတ)')
,(16151,3,10,'(န) မူလဋဳကာတွင် မထင်ရှားမပေါ်လွင်သေးသော အဓိပ္ပါယ်များကို နောက်ထပ်ဖွင့်ဆိုသောဋဳကာ။ အနုဋဳကာ။',NULL)
,(16152,3,1,'ဟိမဝန္တာရှိ အိုင်ကြီးခုနစ်အိုင်တွင် အပါအဝင်ဖြစ်သော နေရောင်မထိုးသဖြင့် အလွန်အေးမြသည့်ရေအိုင်ကြီး။','လ္စအနုတတ် = အနောတတ်အိုင်။')
,(16153,3,11,'(န) ပဥ္စင်းခံသည်မှစ၍ (၁ဝ) ဝါအထိဖြစ်သောထေရ်ငယ်။ အနုထေရ်။',NULL)
,(16154,3,11,'(န) ၁။ အထောင့်အရပ်။ (အရှေ့တောင်၊ အရှေ့မြောက်၊ အနောက်တောင်၊အနောက်မြောက် စသည့်အရပ်များ။)',NULL)
,(16154,3,11,'(န) ၂။ အရပ်မျက်နှာအားလုံး။ ထက်ဝန်းကျင်။','“(ညးဗၞိက်မသုန်ကၠံကွဳ ကလော်စကၠေံအိုတ်သ္အးရ။) ဇုတ်မၞိဟ်ဇုတ်ဂၠဴ ပေၚ်ဗြော်ဒၟံၚ် အနုဒိုဟ်ဟေၚ်။” (ဇ—၁။ အစွောံ။) = “ငါးရာကုန်သော လှည်းကုန်သည်တို့အားလုံးကို ဘီလူးတို့စားကုန်၏။လူရိုးတို့သည်၄င်း နွားရိုးတို့သည်၄င်း ထက်ဝန်းကျင်သောအရပ်တို့­ ဖရိုဖရဲပြန့်ကြဲလျက်ရှိ၏။” || “ယွံရသိ၊ ကၠိက်တံဝွံဂှ် ပ္ဍဲကၠာတေံဍေံညာတ်အဲတုဲ ဍေံဖေက်တဴအဲရောၚ်။ — အဲၚဳရံၚ်တုဲ ဗွဲအနုဒိုဟ် ဍေံဒြေပ်ဒဴအာကၠေံရောၚ်” ကၠဂး။ (ဇ—၂၈၃။ အစွောံ။) = “အိုရသေ့၊ ဤဝက်တို့သည်ရှေး­ငါ့ကိုမြင်သော် ကြောက်ကုန်၏။ ငါကြည့်လိုက်လျှင် အရပ်မျက်နှာအသီးသီးသို့ ထွက်ပြေးကြကုန်၏” ဟုကျားဆို၏။ || “မၞိဟ်ဂမၠိုၚ်ဂှ် ဍေံညာတ်သၟိၚ်ဇာဒိသိုၚ်ဂှ် မသြဲကၠုၚ်ဗက် ဍေံဖေက်လကိုတ်စိုတ်တုဲ ဗွဲဒိုဟ်အနုဒိုဟ်ဂှ် ဍေံဒြေပ်ဒဴအာပြးအိုတ်ရ။” (ဇ—၄၈၆။ အစွောံ။) = “လူတို့သည် ခြင်္သေ့မင်းလာသည်ကို မြင်သည်ရှိသော် ကြောက်လန့်၍ ထက်ဝန်းကျင်သို့ ထွက်ပြေးကုန်၍ လူစုကွဲသွားကြကုန်၏။” (ပါဠိ—အနုဒိသာ)')
,(16155,3,11,'(န) အာနုဘော်။ တန်ခိုး။ စွမ်းအား။ (ပါဠိ—အာနုဘာဝ)','“သြကျာ်တြဲ မဇၞော်ကဵုအနုဘဴကွေံရောၚ်သွံ။” (ဇ—၃၅။ အစွောံ။) = “သြော်မြတ်စွာဘုရားသည် အာနုဘော်ကြီးစွတကား။” || “နအနုဘဴသဳလဗောဓိသတ်ဂှ် သၞာသၟိၚ်ဣန်ချဳတၟိုဟ်တိုန်ရ။” = “ဘုရားလောင်း၏သီလအာနုဘော်ကြောင့် သိကြားမင်း၏ မြကျောက်ဖြာသည် တုန်လှုပ်သွားသည်။” || “နအနုဘဴမဂွံဗှ်သၞာကျာ်တြဲဂှ်ရ ကောန်တြုံဥတ္တရသေဋ္ဌဳဂှ် ဂွံဗၠးအာနူဘဲဂစိုတ်ရ။” = “ဥတ္တရသူဋ္ဌေးသားသည် မြတ်စွာဘုရားအား အောက်မေ့သည်၏ အစွမ်းအာနုဘော်ကြောင့် သေဘေးမှလွတ်မြောက်သွား၏။” || “နအနုဘဴပညာကွတ်အဲဂှ် အဲသ္ဍးကၠေံအန္တရာဲဍေံညိ။” (ဇ—၃၃၈။ အစွောံ။) = “ငါ၏ပညာအစွမ်းဖြင့် ငါသည် သူ့တွင်ကျရောက်မည့်အန္တရာယ်ကို ပယ်ဖျောက်အံ့။”')
,(16156,3,10,'(န) ထောက်ဆခြင်း။ ရမ်းဆခြင်း။ ဆ၍သိခြင်း။ နှိုင်းယှဉ်ခြင်း။',NULL)
,(16157,3,10,'(န) သာဓုခေါ်ခြင်း။ အနုမောဒနာ။',NULL)
,(16157,3,10,'(ကြိ) အနုမောဒနာပြုသည်။ သာဓုခေါ်သည်။','“(ဣသိ) ကဵုပိုန်ပိဏ္ဍပါတ်တုဲ နအနုမောဒနာတၞဟ်ဟ်တၟေၚ်သာ်ဂှ် အနုမောဒနာကဵုသၟိၚ်ရ။” (ဇ—၃၃၆။ အစွောဴ။) = “ရသေ့သည် ဆွမ်းဘုဉ်းပေးပြီးနောက် အထူးထူးသောအနုမောဒနာဖြင့် အနုမောဒနာပြု၏။” || “ပ္ဍဲလအိတ်မကဵုပိုန်တုဲဂှ် ကျာ်တြဲအနုမောဒနာဒါန်ရ။” (ဇ—၄ဝ၉။အစွောံ။) = “မြတ်စွာဘုရားသည် ဆွမ်းဘုဉ်းပြီးသည်၏အဆုံး­ ဒါနကို အနုမောဒနာပြုတော်မူ၏။”')
,(16158,3,1,'‘အဏုလက်ကၠိုက်’ ရှု။',NULL)
,(16159,3,11,'(န) အစမှအဆုံးသို့ အစဉ်အတိုင်းဖြစ်ခြင်း။ အနုလုံ။ (ပါဠိ—အနုလောမ)','‘ပဋိလုံ’ လည်းရှု။')
,(16160,3,11,'(ကြိဝိ) အစမှအဆုံး၊ အဆုံးမှအစ အပြန်ပြန်အလှန်လှန်။ အနုလုံပဋိလုံ။','“မၞိဟ်ကဵုသွဝ် သွဝ်ကဵုမၞိဟ် စသိုၚ်တိုန်စှ်ေ အနုလုံပဋိလုံ ဗွဲမဂၠိုၚ်ကဵုဘဝတုဲ—။” (ဇ—ဝေသန္တဝ်။အစွောံ။) = “လူ့ပြည်မှနတ်ပြည် နတ်ပြည်မှလူ့ပြည် အနုလုံပဋိလုံ ဘဝပေါင်းများစွာ စံစားပြီးနောက်—။”')
,(16161,3,10,'(နဝိ) များပြားသော။ အမျိုးမျိုးသော။',NULL)
,(16162,3,11,'(နဝိ) အနေကန်။ မတိကျမသေချာသော။ တိုင်းတာနိုင်ဖွယ်မဟုတ်သော။',NULL)
,(16163,3,10,'(န) အသက်မွေးဖို့ရန် မရှာမှီးအပ် မပြုလုပ်အပ်သောအမှု။ နှစ်ဆဲ့တစ်ပါးအပြားရှိသော အနေသနအမှု။',NULL)
,(16164,3,1,'၁။ ကြိတ်နှုန်း။ ပျမ်းမျှခြင်း။ (စုစုပေါင်းပြီး အချိုးကျတွက်၍ ရသောနှုန်း။)',NULL)
,(16164,3,1,'၂။အားလုံး။ အလုံးစုံ။ အရေအတွက်မတူသည်တို့ကို အားလုံးပေါင်း၍ ရသောရလဒ်။',NULL)
,(16164,3,1,'၃။ အပိုင်းအခြား။ တာကာလ။','“အနက်မွဲတ္ၚဲ။” (လိက်မိဍောၚ်ကှ်ေထဝ်။) = “တစ်နေ့တာ။”')
,(16165,3,6,'(နှစ်ခုသို့မဟုတ် နှစ်ခုထက်ပိုသော အရေအတွက်) အနက်မှ။','“မတ္တမ၊ ဖာသီ၊လ္ဂုၚ် အနက်ဋ္ဌာန်ပိစွံဝွံ ရာဋ္ဌာန်မွဲအဲဍိက်အာမံၚ်တုဲ သ္ဂောံဒှ်ဨကရာဇ် သ္ဂောံဗဂဵုသာသနာတဳလမၞုံကုပိုန်ညိရော” ဗညာနဲချပ်။ (အကြီုရာဇာဓိရာဇ်) = “မုတ္တမ၊ ပုသိမ်၊ ဒဂုံ ဤသုံးရပ်ဋ္ဌာနအနက်အဘယ်အရပ်သို့ ကျွန်ုပ်သွားနေပါလျှင် ဘုရင်ဖြစ်ရ၍ မြတ်စွာဘုရားသာသနာတော်ကို ထွန်းပအောင် ဆောင်ရွက်ရပါမည်နည်း။” || “အနက်သဳမသုန်ဝွံ ညးဂှ်ဇၞော်ကဵုဒြဟတ်ရော။ သူရာမွဲ မဇၞော်ကုဒြဟတ်ရ။” (သၠပတ်သတိပထာန်) = “သီလငါးပါးအနက် အဘယ်က အားကြီးပါသနည်း။ သုရာသည် အင်အားကြီး၏။”')
,(16166,3,5,'တစ်ပြိုင်နက်တည်း။','“အမာတ်ပြောဟိတ်ဂမၠိုၚ် ကဵုတိၚ်တိုက်တဴ နကဵုကွိၚ်ကွိုက်မၞုံပက္ကရတၞဟ်ဟ်ဂမၠိုၚ် အနက်မွဲဒမြိပ်ရ။” (သၚ်္ခါရဘေဒနဳ။ ဝိန္ဒသာရ။) = “အမတ်ပုရောဟိတ်များသည် အထူးထူးအပြားပြားသော တူရိယာများကို တစ်ပြိုင်နက်တည်း တီးမှုတ်စေ၏။”')
,(16167,3,10,'(န) အဖိုးမဖြတ်နိုင်အောင် တန်ဖိုးရှိခြင်း။ အနဂ္ဃ။',NULL)
,(16168,3,3,'အဖိုးအနဂ္ဃထိုက်သော။ အဖိုးမဖြတ်နိုင်သော။ အဖိုးအတိုင်းမသိထိုက်သော။','မၞိက်အနဂ္ဃၚုဟ် = အဖိုးအနဂ္ဃထိုက်သောပတ္တမြား။ ပြည်တန်ပတ္တမြား။ || “ကောန်ချေံဝွံဂှ် အနဂ္ဃၚုဟ်ရောၚ်သွံ။” (ဇ—၂၅၄။ အစွောံ။) = “သိန္ဓောမြင်းငယ်သည် အဘိုးမပြတ်နိုင်အောင် ထိုက်သောမြင်းတည်း။” (ညောင်ကန်) || “ဂကူသၟိၚ်မ္ဂးဂှ် မူစိၚုဟ်တန်ရော” ကျာ်တြဲသၟာန်။ “ယွံတဳလမၞုံပိုန်၊ ဂကူသၟိၚ်မ္ဂးဂှ် အနဂ္ဃၚုဟ်ရအဴ” သၟိၚ်ဂမၠိုၚ်ဂး (ဇ—၅၃၆။ အစွောံ။) = “မြတ်သောမင်းမျိုးတို့၊ မင်းတို့သည် အဖိုးအဘယ်မျှ ထိုက်ကုန်သနည်း” ဟုမေးတော်မူ၏။ “အရှင်ဘုရား၊မင်းတို့မည်သည်ကား အဖိုးအတိုင်းမသိထိုက်ကုန်၏” ဟုလျှောက်ကုန်၏။ (ညောင်ကန်) || “ဓဝ်အဲကျာ်အနဂ္ဃၚုဟ်မပြဲလောန်ဂှ်—။” (ဇ—၇၇။ အစွောံ။) = “အလွန်မြတ်သော အဖိုးအနဂ္ဃဖြစ်သော ငါဘုရား၏တရားတော်—။” || “နထးထဝ်အနဂ္ဃၚုဟ်ဂှ် ကဵုစုတ်လဝ်ပုၚ် ညံၚ်ခၟောမ်မၠဵုတုဲ—။” (ဇ—၂၆ဝ။ အစွောံ။) = “အဘိုးအနဂ္ဃထိုက်သောရွှေခွက်­ စံပယ်ၚုံနှင့်တူသောထမင်းကိုထည့်ထားစေ၍—။”')
,(16169,3,1,'အဖိုးမဖြတ်နိုင်သောယောကျာ်း။ ယောကျာ်းကောင်း။','“တြုံဂှ် အနဂ္ဃတြုံမပြဲရောၚ်သွံ။” (ဇ—၃၇၄။ အစွောံ။) = “ဤယောကျာ်းကား အနဂ္ဃယောကျာ်းမြတ်ပေတည်း။” || “တြုံအနဂ္ဃသာ်ဝွံ သ္ဇက်ကဵုဒှ်ဒြပ်ညးနွံဟာ” သေဋ္ဌဳချပ်တုဲ ကောန်ဗြဴမွဲ ထပ်တဲစရိုဟ်ဍာ် ဇိုန်ကဵု (မၚ်ဗၠာဲရ။) (ဇ—၄။ အစွောံ။) = “ဤကဲ့သို့သောယောကျာ်းကောင်းကို သူတစ်ပါးပိုၚ်ဥစ္စာ အဘယ်အဖြစ်ခံနိုင်အံ့နည်း” ဟုသူဋ္ဌေးကြံ၍ ထိုလုလင်အား မိမိသမီးနှင့် လက်ထပ်ထိမ်းမြားပေး၏။')
,(16170,3,1,'အဖိုးမဖြတ်နိုင်သောမိန်းမ။ မိန်းမကောင်း။ တော်ဝင်အမျိုးသမီး။','“တလဂြိုပ်ပ္ကဴ၊ ဗြဴအနဂ္ဃ။” (လိက်မေဃကောန်ဒြာဲ) = “ပန်းတောပိုင်ရှင် အနဂ္ဃမိန်းမ။”')
,(16171,3,1,'အဖိုးအနဂ္ဃထိုက်သောမန္တန်။',NULL)
,(16172,3,1,'အဖိုးအနဂ္ဃထိုက်သောရတနာ။','‘ထဝ်သြန်မတ်အနဂ္ဃရတ်။’ (ဇ—၄၉၃။ အစွောံ။) = ‘ရွှေငွေကျောက်တံစသည့် အဖိုးအနဂ္ဃထိုက်သောရတနာ။’')
,(16173,3,1,'အဘိုး။ ဘိုးဘိုး။',NULL)
,(16174,3,1,'အနန်းပင်။','ပ္ကဴအနာၚ် = အနန်းပန်း။')
,(16175,3,5,'အတင်း။ အတင်းအကျပ်။ အနိုင်အထက်။','“ဍုတ်သၞေၚ်တံဝွံ ဟိုတ်ဂၞပ်ဗောဓိသတ် (သၟိၚ်ၜိုပ်ထဝ်) ဟွံသေၚ် မပိုက်ကေတ်အနိၚ်ရောၚ်။ ညံၚ်ဍုတ်သၞေၚ်ပံက်ဝွံ ဗုအာအိုတ်ရ။” (ဇ—၁၃၆။ အစွောံ။) = “ဘုရားလောင်းရွှေဟင်္သာမင်း၏ စိတ်ဆန္ဒအရမဟုတ် အတင်းနုတ်ယူခြင်းကြောင့် ထိုနုတ်ယူသောအတောင်တို့သည် ဗျိုင်းအတောင်ကဲ့သို့ အားလုံးဖြူကုန်၏။” || “(သမ္ဘာညးဒိုက်ဂတ်ဂှ် ၜိုန်တြုံတၠသ္ၚိဇကု ဟွံမိက်အာကီုလေဝ်) အနိၚ်ဖအောဝ်ဏာတၠသ္ၚိ (ကဵုအာကၠတ် ဒြပ်သၟိၚ်ရ။)” (ဇ—၁၄၇။ အစွောံ။) = “သူဆင်းရဲ၏မယားသည် မိမိ၏လင်မသွားချင်ပါဘဲလျက်မင်း၏ဥစ္စာကို သွားရောက်ခိုးယူရန် လင်အား အတင်းအကျပ်တိုက်တွန်း၍ သွားခိုးစေ၏။” || “(ကၠဵုဂြိုပ်ဂှ် လုပ်စတဴပ္ဍဲဗုၚ်ဂၞဴဇွစိၚ်ဂှ် ဇွစိၚ်ဂှ်သကှ်အာ ဂၠံၚ်တိတ်ကၠက်အာရ။) ဗြဲဂူတုဲ တရၚ်သ္ၚိဍာ် (ဇွစိၚ်) ဂှ် ထောၚ်အာညိတုဲ ဂၠုက်တိတ်အနိၚ်။” (ဇ—၄၉ဝ။ အစွောံ။) = “ထိုမြေခွေးသည် ဆင်သေကောင်၏ ဝမ်းတွင်း­ဝင်၍စား၏။ ဆင်သေကောင်ခြောက်သွားရာ ထွက်ပေါက်ပိတ်သွား၏။မိုးရွာ၍ ဆင်စအိုပေါက် အနည်းငယ်ပွင့်သွားသောအခါမှ အတင်းတိုးထွက်ရ၏။” || “ကဵုအာအနိၚ်၊ အသံသၟိၚ်မ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “အတင်းအကျပ်သွားစေ၏၊ ဖခည်းတော်မင်း၏အမိန့်တည်း။”')
,(16176,3,5,'‘အနိၚ်’ နှင့်အတူတူ။','“ဗွဲအနိၚ်ဂှ် အဲရာန်သကိုတ်စဏာဂှ်တုဲ—။” (ဇ—၁၇၉။အစွောံ။) = “အနိုင်အထက်အားဖြင့် ငါသည် ထိုဒွန်းစဏ္ဍားကို ရိုက်ပုတ်နှိပ်စက်၍—။”')
,(16177,3,5,'အနိုင်အထက်။ နိုင်ထက်စီးနင်း။ အတင်းအဓမ္မ။','“သၟတ်ၜါဝွံ နကဵုအနိၚ်အခိုၚ်စိုတ်အဲဍိက် အဲဍိက်လှေံလှန်ရပ်စပ်နၚ်မ္ဂးဂှ် မရာတ်လ္ပသၚ်ကာရအဴ” ဗမၞးဂး။ (ဇ—ဝေသန္တဝ်။အစွောံ။) = “ဤသူငယ်နှစ်ယောက်အား အကျွန်ုပ်သဘောအရ အနိုင်အထက်အားဖြင့် ဖြားယောင်းဖမ်းဆီးလာသည်ဟု သင်မင်းကြီးမယုံမှားတော်မူပါလေနှင့်။” || “ယြဴညးမွဲ သ္ပအနိၚ်အခိုၚ်ကဵုညးကီု ကၠတ်စဒမၠစ မၞိဟ်ကဵုဒှ် တိရစ္ဆာန်ကဵုဒှ် ကဵုသ္ဇၚ်အဲဝွံ သ္ကုတ်ကၠေံရ။” (သၠပတ်ဝၚ်ဓါတ်သော်လ္ဂုၚ်) = “အကြင်သူသည် သူတစ်ပါးကို နိုင်ထက်စီးနင်းပြု ခိုးစားတိုက်စားပါက လူဖြစ်စေ တိရစ္ဆာန်ဖြစ်စေ ဤငါ့ဓါးရှည်ဖြင့် ခုတ်ဖြတ်ပစ်အံ့။”')
,(16178,3,1,'အနိုင်အထက်ပြုကျင့်မှု။','“သၠာ်စှ်ဒကေဝ်ကီု ကမၠေၚ်ဆိုက်ဘာ်နအိုတ်အာ ဒှ်ပွအနိၚ်အခိုၚ်ရဂးတုဲ—။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “ကြေးဝါကျပ်တစ်ဆယ်မျှဖြင့် ကောက်ညှင်းတင်းဝက်နီးပါးကုန်အောင် ယူစားလိုက်သည်မှာ အနိုင်အထက်ပြုကျင့်မှုမြောက်၏ဟုဆို၍—။”')
,(16179,3,4,'အနိုင်အထက်ပြုကျင့်သည်။ အနိုင်ကျင့်သည်။','“ယြဴညးမွဲ သ္ပအနိၚ်အခိုၚ်ကဵုညးကီု၊ ကၠတ်စ၊ ဒမၠစ၊ ပၠံၚ်ၜးစ ပအနိၚ်အခိုၚ်ကီု၊ မၞိဟ်ကဵုဒှ် တိရစ္ဆာန်ကဵုဒှ်ကီုရ၊ နသၞာ်အဲဝွံအဲသကဵုဗာ်ဂစိုတ်ကၠေံရ” သၟိၚ်ဂး။ (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “မည်သူမဆို ခိုးခြင်း၊ ဓါးပြတိုက်ခြင်း၊ လုယက်ခြင်း စသောအနိုင်အထက်ပြုသူတို့ကို လူသော်လည်းကောင်း တိရစ္ဆာန်သော်လည်းကောင်း ဤငါ့သန်လျက်ဖြင့် ခုတ်သတ်ပစ်စေမည်။” || “တၠညးဟွံမွဲတုဲ ပြောဟိတ်ပအနိၚ်အခိုၚ်ကဵုအဲ” ဂၞကျာ်ဟီုဗျဵုသၟိၚ်။ (ဇ—၂၂ဝ။ အစွောံ။) = “အရှင်မင်းကြီးမရှိစဉ် ပုရောဟိတ်သည် အကျွန်ုပ်အား အနိုင်အထက်ပြုကျင့်၏” ဟုမိဖုယားကုန်းချော၏။')
,(16180,3,5,'အနိုင်အထက်။ နိုင်ထက်စီးနင်း။ အတင်းအကျပ်။','“ဗှ်ေကေတ်ဏာအဲ အနိၚ်အထက်ရောၚ်ဟာ။ အဲအာဟွံဒှ်ရ။” (ဇ—၃၁၂။ အစွောံ။) = “သင်သည် ငါ့ကို နိုင်ထက်မူ၍ခေါ်ဆောင်သလော။ ငါမသွားနိုင်တော့။” || “သၟိၚ်စက္ကဝဝ်ဏာစိၚ်ဂှ် အနိၚ်အထက် စိၚ်ဂှ်အာဟွံမာန်—။” (ဇ—၄၇၉။ အစွောံ။) = “စကြဝတေးမင်းသည် ဆင်တော်ကို အတင်းအကျပ်သွားစေ၏၊ ဆင်တော်သည် မသွားနိုင်။”')
,(16181,3,1,'အနိုင်အထက်ပြုခြင်း။ အတင်းအကျပ်ပြုခြင်း။ နိုင်ထက်မူခြင်း။',NULL)
,(16182,3,5,'‘အနိၚ်အထက်’ နှင့်အတူတူ။','“ၜိုန်တြုံမိမမဇိုန်ကဵု ဗွဲအနိၚ်အထက်ကီုလေဝ် မဒးဗက်ဗွဲဗလောဲစိုတ်တြုံဂှ်ရောၚ်။” (ဇ—၅၃၁။ အစွောံ။) = “မိဘက အတင်းအကျပ်ပေးစားသော ယောကျာ်းပင်ဖြစ်စေကာမူ ထိုယောကျာ်းအလိုသို့ လိုက်ရပါမည်။” || ‘(ဒြပ်) မကလိဂွံဗွဲအနိၚ်အထက်။’ (ဇ—၄၅ဝ။ အစွောံ။) = ‘မတရားသဖြင့် နိုင်ထက်မူ၍ရရှိသောဥစ္စာ။’')
,(16183,3,5,'အနိုင်အထက်။ နိုင်ထက်စီးနင်း။ အတင်းအကြပ်။',NULL)
,(16184,3,10,'(န) အစိုးမရခြင်း။ အနတ္တ။',NULL)
,(16185,3,10,'(န) မတည်မြဲခြင်း။ အနိစ္စ။',NULL)
,(16186,3,11,'(န) နှစ်သက်လိုလားဖွယ်မရှိသောအာရုံ။ အနိဋ္ဌာရုံ။ (ပါဠိ—အနိဋ္ဌာရမ္မဏ)',NULL)
,(16187,3,10,'(န) အကျိုး။ အာနိသင်။','“ဂွံဒဂိုန်သဳဥပုဟ်မ္ဂးဝွံဂှ် အနိဿံသဖဵုဂၠိုၚ်လောန်သန်။” (ဇ—၅၁၁။ အစွောံ။) = “ဥပုသ်သီလဆောက်တည်ခြင်းမည်သည် အလွန်အကျိုးများ၏။” || “သုၚ်လဝ်ဂဥုဲဂှ်တုဲ သုၚ်စုတ်အရက်သုရာမ္ဂး အာနိဿံသဂဥုဲဂှ် လီုအာမာန်ရောၚ်။” = “ထိုဆေးကိုသောက်ထားပြီး သေရည်အရက်သောက်သုံးလျှင် ဆေး၏အစွမ်းအာနိသင် ပျက်ပြယ်သွားနိုင်သည်။” || “အာနိဿံသဖဵုဂုန် ဒဒှ်ခမဳဂှ် (ပစ္စေဂဗုတ်) တွံကဵုပၠန်ရ။” (ဇ—၃၇၈။ အစွောံ။) = “ရဟန်းဖြစ်ခြင်း၏အကျိုးကျေးဇူးကို အရှင်ပစ္စေကဗုဒ္ဓာ ဟောကြားပြန်၏။”')
,(16188,3,10,'(န) အဆုံးမရှိခြင်း။ အတိုင်းမသိခြင်း။ အနန္တ။',NULL)
,(16189,3,11,'(န) အတိုင်းမသိ ကျေးဇူးရှိသော ဘုရား၊ တရား၊ သံဃာ၊ မိဘ၊ ဆရာတည်းဟူသော အနန္တောအနန္တငါးပါး။',NULL)
,(16190,3,11,'(န) ရေတွက်ခြင်းငှာ မတတ်နိုင်အောင် အလွန်အမင်းများပြားခြင်း။ အဆုံးမရှိခြင်း။',NULL)
,(16191,3,1,'အနံ။ ဗျက်။','“ပြာသာဒ်ဂှ် အနာံဍေံဂှ် ဒစာံယောဇနာ—။” (ဇ—၂၆၄။ အစွောံ။) =“ထိုပြာသာဒ်သည် အနံအားဖြင့် ရှစ်ယူဇနာရှိ၏။” || “ယာတ်မွဲ အနာံပိဟတ် ဇမၠိၚ်ပန်စှ်ောဟတ်။” (ဇ—၂၉၁။ အစွောံ။) = “အနံသုံးတောင် အလျားအတောင်လေးဆယ်ရှိသော ပုဆိုးတစ်ထည်။”')
,(16192,3,1,'မိခင်၏အစ်ကို သို့မဟုတ် ဖခင်၏အစ်ကို။ ဘကြီး။',NULL)
,(16193,3,1,'ကံ့ကော်ပန်း။','‘အဂၞု’ ရှု။')
,(16194,3,1,'နာနတ်သီး။','‘အဏာတ်’ ရှု။')
,(16195,3,7,'စဉ်။ ရင်း။','“အနှိန်အာဝါ အဲရပ်နၚ်ကရ။” = “လယ်တောသွားရင်း ကျွန်တော်ငါးဖမ်းလာသည်။” || “အနှိန်ညးအာဍုၚ် ညးရာန်နၚ်ကွာၚ်ရ။” = “သူမြို့သွားစဉ် မုန့်ဝယ်လာသည်။”')
,(16195,3,9,'အကြောင်းပြသည့်အနက်ဖြင့် ဆက်စပ်ပေးသောစကားလုံး။ သဖြင့်။ သောကြောင့်။','“ယွံကောန်ဇၞော်တံ၊ အနှိန်အဲသ္ဍိုက်ဂၞကျာ် ကောန်သၟတ်ဂှ် အဲဒးကဵုဥပ္ပရာဇာတုဲရ။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “သားတော်ကြီးတို့၊ မိဖုယားကို ငါချစ်သဖြင့် သားတော်ငယ်အား ဥပရာဇာအဖြစ်ကို ပေးအပ်မိပြီ” ဟုမင်းဆို၏။ || “(ကၠဵုဂြိုပ်ဂှ်) အနှိန်ဗၟံက်သမ္ၚာတ်စိုတ်ဂှ်ဒြေပ်အာမွဲချိုန်တုဲ ကလေၚ်ပၠန်ဂ္ဇအ်ဒၟံၚ်။” (ဇ—၁၄၈။ အစွောံ။) = “ထိုမြေခွေးသည် ထိတ်လန့်သဖြင့် တစ်ခဏမျှပြေးသွားပြီးလျှင် ပြန်လာ၍ထိုင်နေ၏။”')
,(16196,3,1,'ဈေးနှုန်း။','အနှေန်ဗၞိက် = ကုန်ဈေးနှုန်း။ || “အဲရဂွံအာကၠာမ္ဂး — အနှေန်ဗၞိက်လေဝ် သ္ဂုတ်သွာတ်ပ္တိုန်ဖျေံ ညံၚ်စိုတ်ပိုဲဂှ် ဂွံသွံစရ” ညးဗၞိက်သမၠီုဂှ်ချပ်။ (ဇ—၁။ အစွောံ။) =“ငါသည် ရှေ့မှသွားသည်ရှိသော် ကုန်ဈေးနှုန်းလည်း အလိုရှိတိုင်း အဘိုးသတ်မှတ်၍ ရောင်းရလတ္တံ့” ဟုလှည်းကုန်သည်မိုက်ကြံ၏။')
,(16197,3,11,'(= တ္ကအ်ပလိုတ်) အနောက်ကျွန်း။ (ပါဠိ—အပရဂေါယာန)',NULL)
,(16198,3,10,'(န) လှူပြီးနောက်ပိုင်း­ ဖြစ်သောစေတနာ။ အပရစေတနာ။',NULL)
,(16199,3,1,'အဖေ။ ဖခင်။ အဘ။',NULL)
,(16200,3,1,'အဘိုး။',NULL)
,(16201,3,1,'ပထွေး။',NULL)
,(16202,3,1,'စည်းကမ်းမဲ့သူ။ အသုံးအဖြုန်းကြမ်းသူ။',NULL)
,(16203,3,1,'ပိဿာဝက်။ ငါးဆယ်ကျပ်သား။','“အစိတ်အပါ်၊ သၞီသၠာ်ကဵုဒး။” (လိက်ပယးအနိစ္စ)')
,(16204,3,1,'ဖြစ်ပျက်ပုံ။ အဖြစ်အပျက်။ (?)',NULL)
,(16205,3,1,'ပယောဂအတတ်ဖြင့် လူ၏ခန္ဓာကိုယ်တွင်းသို့ သွတ်သွင်းသောအစာ။ အပင်း။','စုတ်အပၚ် = အပင်းထည့်သည်။ || ဒးအပၚ် = အပင်းထည့်ပြုစားခြင်းခံရသည်။ || “ယြဴပူဂဵုမွဲစဇဗၠု ဟွံဍေက်တၞုၚ်တဝ်မ္ဂး ဒးအပၚ်သရၚ် ညးမ္ဂး။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ကွမ်းရွက်ရိုးကို မဆိတ်ဖြတ်ပစ်ဘဲ ကွမ်းစားသောသူအား အပင်းသွင်းခံရတတ်သည်ဟု ရှေးလူတို့ဆိုကုန်၏။”')
,(16206,3,1,'မြေဘုတ်ဘီလူး။','“မၞုံရုပ်ဂရှ်ဂပှ် မတုပ်တဴညံၚ်ရဴကလော်အပိၚ်သာတ်—။” (ဇ—၄၉၇။ အစွောံ။) = “မြေဘုတ်ဘီးလူးကဲ့သို့ အကျည်းတန်သောရုပ်ရှိ၏။” || “ကလော်အပိၚ်သာတ် အကြာဟန်ဗန်တံဂှ်ကီု၊ ဘုတ်ပြိုတ်တံဂှ်ကီု။” (ဇ—၅၁ဝ။ အစွောံ။) = “အမှိုက်ပုံကြားမှ မြေဘုတ်ဘီလူးတို့သည်၄င်း၊ ဖုတ်ပြိတ္တာတို့သည်၄င်း။” || ‘ပိၚ်သာတ်’ နှင့်အတူတူ။')
,(16207,3,1,'၁။ အပေါင်း။ စုစုပေါင်း။ အပေါင်းအစု။','“သာ်ဝွံမွဲဂၠံၚ်၊ အပံၚ်ဂါထာ။ ရထဍေံဂှ်၊ ပိုဲဟီုတွံကၠာ။ စိုတ်ပယောၚ်ယာ၊ ပၚ်မိၚ်ကၠာရ။” (လိက်လၞုဟ်ပန်) = “ဤသည်ကားတစ်နည်း ဂါထာအပေါင်းအစုတည်း။ ယင်း၏နိဿယကို တို့ဟောကြားပေအံ့၊ စိတ်ယောၚ်မှားခြင်းမရှိဘဲ နာကြားပါဦးလော့။” || “ပန်စှ်ောထပှ်၊ တိတ်ဒှ်အပံၚ်။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။) = “စုစုပေါင်းလေးဆယ့်ခုနစ်ဖြစ်၏။”')
,(16207,3,1,'၂။ အကြော်။ ငပေါင်းကြော်။','အပံၚ်လဵု = ဗူးသီးကြော်။')
,(16208,3,1,'ငပေါင်းထုပ်။',NULL)
,(16209,3,5,'အပြီးအပိုင်။ အပိုင်။','“အပေါတ်ဏအ် ကဵုအဲအပိုၚ်ဟာ။” = “ဒီပစ္စည်း ငါ့ကို အပိုင်ပေးမလား။”')
,(16209,3,1,'ပိုင်ဆိုင်ခြင်း။ ပိုင်စိုးခြင်း။ အပိုင်။','“ယွံသၟိၚ်မပြဲ၊ သၟိၚ်ထပှ်က္ဍိုၚ်ဗ္တာၚ်ဂှ်မရှာဇ်ဂွံဇၞးတုဲ မရှာဇ်ဂွံရောၚ်။ ဟိုတ်ဂှ်ရ ဒှ်အပိုၚ်မရှာဇ်ရ။ — ဂမ္စိုတ်ဂှ်လေဝ် မရှာဇ်ပိုၚ်ရ၊ ဗလးဂှ်လေဝ် မရှာဇ်ပိုၚ်ရ။” (ဇ—၅၃၁။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ဤခုနစ်ပြည်ထောင်မင်းတို့ကို သင်မင်းကြီးတိုက်နိုင်၍ ရခဲ့ခြင်းဖြစ်၏။ ထို့ကြောင့် သင်မင်းကြီး၏အပိုင်ဖြစ်၏။ သတ်လိုလည်း သင်မင်းကြီးသတ်ပိုင်၏၊ လွှတ်လိုလည်း သင်မင်းကြီးလွှတ်ပိုင်၏။” || “ဒတန်ဂှ်လေဝ် အပိုၚ်ညးဟွံမွဲဏီ။” (ရာဇာထ္ၜုတ်) = “ဤတည်နေရာ (ဒေသ) သည်လည်း သူတစ်ပါးပိုင်ဆိုင်ခြင်းမရှိသေး။” || “ကုညးမပ္တံကဵုကျာ် မဗၠးနူအပိုၚ်တဏှာဂှ် နမလ္ၚောဝ်ဂကောံဒွါပိ ပိုဲမဒးပရောၚ်။” (ဇ—၂၄၄။ အစွောံ။) = “တဏှာ၏ပိုင်စိုးခြင်းမှ လွတ်မြောက်တော်မူပြီးကုန်သော ဘုရားအစရှိသောသူမြတ်တို့အား ငါတို့သည် ရှိခိုးခြင်းကို ပြုပါကုန်၏။” || “ထာန်ဝွံ ကဵုဒှ်ထာန်ပိုဲအပိုၚ်ရ။” (ပြကိုဟ်ဂဝမ္ပတိ) = “ဤအရပ်ကို ငါတို့ပိုင်ဆိုင်သောအရပ်ဖြစ်ပါစေ။”')
,(16210,3,1,'အပိုင်းအခြား။ အကန့်အသတ်။ သတ်မှတ်ခွဲခြားခြင်း။','“မူစိဗၞတ်အပိုၚ်အခြာကာလမွဲ ရနုက်ဗပေၚ်ပါရမဳသ္ဂောံကြံၚ်ဍုဟ် သ္ဂောံအာစိုပ်ဒဒှ်ကျာ်ရော။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “အဘယ်မျှသော ကာလအပိုင်းအခြားတစ်ခုကို ပါရမီဖြည့်ပြီးနောက် ပါရမီရင့်မာ၍ ဘုရားအဖြစ်သို့ရောက်ပါသနည်း။” || “ရန်ကဵုဒါန်ဓမ္မ၊ ဗုဒ္ဓတွံလဝ်ကၠာ။ ဇၞးဒါန်ဂမၠိုၚ်၊ ဟွံမွဲကဵုအပိုၚ်အခြာ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ဓမ္မဒါနကိုရည်၍ ဗုဒ္ဓဘုရားဟောထားတော်မူသည်မှာအပိုင်းအခြားမရှိ ဒါနအားလုံးကို အောင်နိုင်၏။”')
,(16211,3,5,'အပြီးအပိုင်။ အပိုင်စား။ အပြည့်အဝ။','“ရဴဝွံသၟိၚ်ဇၞော်ကဵုလဝ်အခေါၚ် အပိုၚ်အပြာပ်ရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ဤကဲ့သို့မင်းကြီးသည် အပြီးအပိုင် အပြည့်အဝအခွင့်ပေးထား၏။” || “ကွာန်သိဝဂှ်လေဝ် သၟိၚ်ဇိုန်ကဵုမိဍောၚ်ဓဝ် ကဵုစအာအပိုၚ်အပြာပ်ရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “သိဝရွာကိုလည်း မိဍောင်းထော်အား အပိုင်စားပေး၍ စားစေ၏။”')
,(16212,3,1,'အလွန်စေးနှဲသူ။',NULL)
,(16213,3,1,'အရာဝတ္ထု။ ပစ္စည်း။ တန်ဆာန်ပလာ။ ဘဏ္ဍာ။','“ဇုတ်ဒဳပြဘာတ်ဂှ် ကဝ်အာတုဲ ဒလေၚ်ဗဗေၚ်တံဂှ်လေဝ် လောတ်လောပြးဇးအာရ။ အပေါတ်ပြဘာတ်ဂှ်လေဝ် ပြောပ်ပါ်အာအိုတ်ရ။” (ဇ—၃၂၄။ အစွောံ။) = “ပရိဗိုဇ်၏ပေါင်ရိုးသည် ကျိုး၏။ ပရိက္ခရာဖြင့်ပြည့်သော ဝန်ထုပ်သည် လိမ့်၏။ အလုံးစုံလည်းဖြစ်သော (ပရိဗိုဇ်၏) ဘဏ္ဍာသည် ကွဲ၏။” (ညောင်ကန်) || “တဲလ္ၚုဂှ် အဲဟွံအာရ။ အပေါတ်ကယိုင်ဍေံဂှ် ယိုက်ကေတ်တုဲ အဲမဂပ်ဂဝ်သ္အာရောၚ်” တြုံကမၠတ်ဂှ်ချပ်။ (ဇ—၃၁၈။ အစွောံ။) = “လက်ချည်းသက်သက်ဖြင့် ငါမသွား။ သူ့လှဝတ်တန်ဆာပစ္စည်းကို ယူဆောင်၍သွားအံ့” ဟုခိုးသူယောကျာ်းကြံ၏။ || “ကဵုယိုက်ကေတ်အပေါတ်ဗၞိက်တုဲညးၜါမကဵုကောန် အာသွံရာန်စရ။” (ဇ—၁၅၅။ အစွောံ။) = “ကုန်ပစ္စည်းတို့ကို သယ်ဆောင်စေ၍ သားအဖနှစ်ဦးတို့ ကုန်အရောင်းအဝယ်သွားကြ၏။”')
,(16214,3,1,'ပစ္စည်းပစ္စယ။ တန်ဆာပလာ။ အသုံးအဆောင်ပစ္စည်း။','“ဒြပ်ကြိယာဗာအပေါတ်ကညောတ်တံဂှ်ကီု။” (သြဝါဒဒဳပနဳ) = “အသုံးအဆောင်ကိရိယာ ပစ္စည်းပစ္စယတို့ကို၄င်း။”')
,(16215,3,1,'‘အပေါတ်ကြိယာ’ (န) နှင့်အတူတူ။','“အပေါတ်ကယာဆတ္တာ နာဲတံညးၜါကေတ်ဏာတုဲ အာလိၚ်ရေက်သော်ဇၟာပ်သ္ၚိညိ။” (သၠပတ်ဓမ္မသံဂိတိ) =“ဆတ္တာပစ္စည်းကိရိယာများကို သင်တို့နှစ်ဦးယူဆောင်၍ အိမ်တိုင်းသို့သွားကာ အခစားဆံပင်ညှပ်လော့။”')
,(16216,3,1,'အလှပြင်ပစ္စည်း။ လှဝတ်တန်ဆာ။',NULL)
,(16217,3,1,'ပစ္စည်းကိရိယာ။ တန်ဆာပလာ။',NULL)
,(16218,3,1,'ဝတ်ဆင်စရာပစ္စည်း။ အဆင်တန်ဆာ။','“ယွံတၠသ္ၚိအဲ၊ ဒြပ်အိုဿီုမဒှ်အပေါတ်ဂ္ညိအဲဂှ် တၠအဲယိုက်ဏာတုဲ—။” (ဇ—၃၇၄။ အစွောံ။) = “ချစ်လင်၊ အကျွန်ုပ်၏အဆင်တန်ဆာဖြစ်ကုန်သော အလုံးစုံသောဥစ္စာကို သင်သယ်ဆောင်သွားပြီးလျှင်—။”')
,(16219,3,1,'ကုန်ပစ္စည်း။',NULL)
,(16220,3,1,'တွင်းထွက်သယံဇာတပစ္စည်း။',NULL)
,(16221,3,1,'အိမ်သုံးပစ္စည်း။',NULL)
,(16222,3,11,'(န) ချမ်းသာမရှိ ဒုက္ခအတိဖြစ်သောဘုံ။ အပါယ်။',NULL)
,(16223,3,1,'ငရဲ၊ တိရစ္ဆာန်၊ ပြိတ္တာ၊ အသူရကာယ်ဟူသော အပါယ်လေးဘုံ။',NULL)
,(16224,3,1,'ကျူပင်။','‘သပိုဟ်’ ဟု အများအားဖြင့်တွေ့ရသည်။')
,(16225,3,6,'အထဲမှာ။ အတွင်းမှာ။','ပၞာန်အပ္ဍဲဍုၚ် = ပြည်တွင်းစစ်။ || ‘အပ္ဍဲဍုၚ်ကီု မ္ၚးဍုၚ်ကီု။’ (ဇ—၁၅၁။ အစွောံ။) = ‘မြို့တွင်း­၄င်း မြို့ပြင်­၄င်း။’ || “အပ္ဍဲဂှ် ဗှ်ေဒေပ်လဝ်ဂျိလောဘဒေါသတုဲ မ္ၚးဂှ် ဗှ်ေသ္ၚဳလလံတဴရောၚ်သွံ။” (ဇ—၃၂၅။ အစွောံ) = “သင်သည် အတွင်း­ လောဘဒေါသအဆိပ်ကို သိုဝှက်ထားပြီးလျှင် အပြင်ပန်း­မူကား ငြိမ်သက်တည်ကြည်ဘိသကဲ့သို့နေ၏။”')
,(16226,3,1,'ကုလားယောကျာ်း။',NULL)
,(16227,3,1,'ပြက်ရယ်ပြုခြင်း။ ပြောင်လှောင်ခြင်း။',NULL)
,(16228,3,1,'၁။ ကြွေ။ ကြွေထည်ပစ္စည်း။',NULL)
,(16228,3,1,'၂။ အစက်အပြောက်ပါသောအရာ။ ဖြူနီကြောင်ကျားအရောင်။','“ဖ္ဍာန်ဗကေတ်အိုတ်သီု မဟွံဂွံပြံက်ဂှ်ဟေၚ် မဆဳဒဝ်ရောၚ်။ ဒှ်ရအပြံက်မာ။ ဂပ်ဂဝ်ကီုရ။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “အကာအရံသည် အလုံးစုံနီ၍ အရောင်အပြောက်အကျား မရောနှောလျှင်သာ တားမြစ်၏။ အပြောက်အကျားဖြစ်မူကား သင့်လျော်၏။” || “မဟာပိဋ္ဌိယကောဇဝံ။ ၚ်ကောဇဴမဇၞော်မၞုံအပြံက် မတုပ်တဴရဴစၞိန်ကၠန်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “စပါးကြီးမြွေ၏ကျောကဲ့သို့ အပြောက်အကျားရှိသော ကော်ဇောကြီး။” || “ညံၚ်သာ်အပြံက်၊ လစံက်ဓဝါန်။” (လိက်ပဒုမဝတဳ) = “ဖြူနီကြောင်ကျား မည်းညိုပြောက်ကျားသောအရောင်ကဲ့သို့။” || ‘ပြံက်’ (ကြိ) လည်းရှု။')
,(16229,3,1,'အစက်အပြောက်။ အညိုအမည်းအစက်အပြောက်။ ဖြူနီကြောင်ကျား။',NULL)
,(16230,3,1,'(လက်ဝတ်ရတနာမျိုးစုံ) အရောအနှော။','“လကံက်ဒြၚ်ဗံက်၊ အပြံက်အကာန်။ ဒြပ်ပၠံၚ်ကေတ်အိုတ်၊ ဂစိုတ်သာန်သာန်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “လက်ကောက်အစရှိသော ဥစ္စာအရောအနှောတို့ကို လုယက်ယူပြီးလျှင် ပိုင်ရှင်ကို ရက်စက်စွာသတ်ပစ်၏။”')
,(16231,3,1,'အရောအပြွမ်း။','“ဂၠဴၝောံဂှ်ကီု သီုဂၠဴၝောံအပြံက်အရံက်ကၠံ အာကေတ်နၚ်ညိ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ထိုနွားမကို၄င်း (အခြား) အရောအပြွမ်းဖြစ်သော နွားမတစ်ရာတို့ကို၄င်း သွားယူလာပါ။”')
,(16232,3,1,'တစ်ဆင့်မှာကြားချက်။',NULL)
,(16233,3,1,'ပြိတ္တာကောင်။ ငပြိတ္တာ။ (အဆဲဝေါဟာရ)',NULL)
,(16234,3,3,'သာမန်ဖြစ်သော။ သာမညဖြစ်သော။ အချည်းနှီးဖြစ်သော။ အညံ့စားဖြစ်သော။','မၞိဟ်အပြောံ = (ပညာရှင်မဟုတ်သော၊ လူချမ်းသာမဟုတ်သော၊ ရာထူးရှိသူမဟုတ်သော) သာမန်လူပြိန်း။ || ဆုအပြောံ = သစ်မာမဟုတ်သော အညံ့စားသစ်။ || ကၠဵုအပြောံ =သာမန်ဝဲစားခွေးမျိုး။ || “သၟိၚ်ဇာဒိသိုၚ်တၠဣဓိ မၚ်မွဲလဝ်လစဂှ်လေဝ် တီတဴရ၊ ကၠဵုအပြောံဟွံတီဗၞတ်ဇကုဂှ် စှ်ေအာလစတုဲ ဍေံစှ်ၜေိၚ်ဝေၚ်ဂှ် ဍေံထေက်ကြိုက်ညိဟာ။” (ဇ—၁၉၅။ အစွောံ။) =“တန်ခိုးရှင်ခြင်္သေ့မင်း စောင့်ရှောက်သောရေကန်ဖြစ်ကြောင်းကိုလည်း သိလျက်နှင့် မိမိပမာဏကိုမသိသော သာမန်ဝဲစားခွေးသည် ရေကန်သို့ဆင်း၍ ကူးခပ်ကစားခြင်းသည် သင့်လျော်ပါ၏လော။” || “ယွံခမဳ၊ ၜိုန်တၟအ်သိနနရာတ် ကျာမပိုက်ကသဳမာန်ဏီဂှ် သၠဆုလၟုဟ်အပြောံဂှ် မူဟိုတ်ဍေံဟွံပိုက်ကသဳသၞုံရော။” (ဇ—၄၃၃။ အစွောံ။) = “ရဟန်း၊ မြင်းမိုရ်တောင်ကိုပင်လည်း တိုက်ခတ်လှုပ်ခါစေနိုင်သောလေသည် အချည်းနှီးသော သစ်ရွက်ရော်မျှကို အဘယ်မှာလျှင် မတိုက်ခတ်မလှုပ်ခါစေဘဲ ရှိပါငြားအံ့နည်း။” || ‘ချေံတမၞီအပြောံ။’ (ဇ—၂၃။ အစွောံ။) = ‘သာမန်ဝဲစားမြင်း။’ || “ဂဍာ်အပြောံဂှ် ပ္တောံကဵုၜိုပ်ထဝ် တုပ်ၜိုပ်ထဝ်ဟာ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “သာမန်ကျီးကို ရွှေဟင်္သာနှင့်နှိုင်း၍ ရွှေဟင်္သာနှင့်တူပါမည်လော။” || “ၜိုန်ကျာ်နာဲညး၊ သ္ကန်ဂတးဘဴ။ ပိုဲအပြောံအဴ၊ မူရဴသ္ဇက်ဟီု။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “မြတ်စွာဘုရားရှင်သော်မှ သေလွန်ရသေးလျှင် ငါတို့သာမန်လူပြိန်းကား အဘယ်ဆိုဖွယ်ရာရှိတော့အံ့နည်း။”')
,(16235,3,1,'အပြား။ ပြားသောမျက်နှာပြင်။','ထဝ်အပၠာ = ရွှေပြား။ || အပၠာမြ = ဓါးမအပြား (အပြားလိုက်) ။ || “နကဵုအပၠာသၞာ်ရတ်ဂှ် သၟိၚ်မှာသဳလဝ ဒါတ်မွဲမ္ၚုဟ်သၟိၚ်ဗပုန်ဂှ်ရ။” (ဇ—၅၁။ အစွောံ။) = “မဟာသီလဝမင်းသည် သန်လျက်အပြားဖြင့် ခိုးသူမင်းအား ခတ်၍နှိုး၏။”')
,(16236,3,1,'၁။ ဘုရားသပြေပန်းတင်ရန် အလှအပပြုလုပ်ထားသော ညောင်ရေအိုး။ မြူအိုး။','နုၚ်အပၠူ = ဘုရားညောင်ရေအိုး။ || “(ကောန်ဒေဝတဴဗြဴဂှ်) ေၚက်ညံၚ်ဇၟန်ဗၠဲကီု တမ်ကအ်ညံၚ်အပၠူထဝ်ကီု ကမၠံတှ်ညံၚ်ဒကှ်ထဝ်ကီု—။” (ဇ—၅၂၃။ အစွောံ။) = “ထိုနတ်သမီး၏သွားသည် ပုလဲကုံးကဲ့သို့၄င်း၊ လည်ပင်းသည် ရွှေပန်းအိုးကဲ့သို့၄င်း၊ နို့အုံသည် ရွှေကြာပန်းကဲ့သို့၄င်းဖြစ်၏။”')
,(16236,3,1,'၂။ ခန္ဓာကိုယ်ကြွက်သား။','အပၠူကအ် = လည်ပင်းကြွက်သား။ || အပၠူစး = ကျောပြင်ကြွက်သား။ || အပၠူဒၚ်ပၞး = ပခုံးကြွက်သား။')
,(16237,3,1,'ညီညာသောမျက်နှာပြင်။ ကျယ်ပြန့်သောမျက်နှာပြင်။','“ဟိုတ်မှာဲမံၚ်တဴ၊ ဒေါဝ်အပၠဴဂၚ်။ဗၠိုက်ဍာ်ကောံကီု၊ လေၚ်သီုဂၠုၚ်က္ၜၚ်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “မြစ်ရေပြင်ကျယ်­ မေ့လျော့ပေါ့ဆသဖြင့် အစုလိုက်ရေနစ်၍ လှေသင်္ဘောပါ ပျက်စီးဆုံးရှုံးရ၏။” || “လုပ်ၜှ်ဝေၚ်ပ္ကဴ၊ အပၠဴဟေမ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ကျယ်ပြန့်သောတောသို့ဝင်၍ ပန်းခူးကစား၏။” || “ဒေါဝ်ၜဳအပၠဴ၊ ကောဂၞဴကၠေံအာ။” (လိက်ကောန်သၟိၚ်ဝါရဝေါၚ်သ။ အစွောံ။) = “ပင်လယ်ရေပြင်ကျယ်­ မယ့်မောင်ပျောက်ဆုံးသွားရ၏။”')
,(16238,3,1,'‘အဖၠဴပၞာန်’ ရှု။',NULL)
,(16239,3,1,'အကျင့်ပျက်သူ။ လိမ်ညာဖြီးသန်းပြောတတ်သူ။','“ထာန်ဝွံထာန်ပိုဲ၊ ဟိုဲအပၠၚ်ကျာ။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “ဤအရပ်သည် ငါတို့ပိုင်အရပ်တည်း၊ အို—အကျင့်ပျက်တို့။” || ‘ဣပၠၚ်ကျာ’ (န) လည်းရှု။')
,(16240,3,1,'အသုံးအဖြုန်းကြီးသူ။ ငဖြုန်း။',NULL)
,(16241,3,5,'အမြဲ။ မကြာခဏ။','“ဍေံကၠုၚ်ဝေၚ်ဒၟံၚ်သ္ၚိပိုဲအပၠိတ်ရ။” = “ကျွန်တော်တို့အိမ်သို့ အမြဲတမ်းသူလာလည်သည်။” || “ဇေတဝန်အဴ၊ ဒၟံၚ်တဴအပၠိတ်။ ကိုပ်တေံမွဲဝှ်၊ ကြဴစှ်ဒစိတ်။ၜါစှ်ောလအိတ်၊ ပံၚ်တုဲတိတ်ဒှ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ဇေတဝန်ကျောင်းတော်­အမြဲတမ်းနေတော်မူသည်မှာ အစအဦး­တစ်ဝါ နောက်­တစ်ဆယ့်ကိုးဝါ စုစုပေါင်း (၂ဝ) ဝါဖြစ်၏။”')
,(16242,3,1,'အရောင်အဆင်း။ အရောင်အဝါ။ ထွန်းပခြင်း။','“ပြာသာတ်အပၠိတ်၊ ရတ်ဒစိတ်တန်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ရတနာကိုးပါးဖြင့် အရောင်အဝါထွန်းပနေသောပြာသာဒ်။” || “မုက်ဂၠးဒၚောဝ်၊ လျးထဝ်အပၠိတ်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ရွှေရောၚ်အဆင်းနှင့် ကြေးမုံပြင်ကဲ့သို့သောမျက်နှာ။”')
,(16243,3,1,'အပြစ်ဒဏ်။ လျော်ဒဏ်။ လျော်ကြေး။ (fine, penalty, punishment)',NULL)
,(16246,3,4,'အပြစ်ပေးသည်။ အပြစ်ဒဏ်ခတ်သည်။','“သၟိၚ်စဳစတ်ရံၚ်တုဲ ကဵုအပၠေတ်ရာဇာဒဏ်ရ။” (ဇ—၃၇၆။ အစွောံ။) = “မင်းသည် စစ်ဆေးစိစစ်ပြီးနောက် မင်းပြစ်မင်းဒဏ်ပေး၏။”')
,(16247,3,4,'ပြစ်ဒဏ်ခံရသည်။','“သၟိၚ်မိၚ်ဂလာန်ဗောဓိသတ်တုဲ နဗဗွဲဓဝ်သ္ဂုတ်သွာတ်ကဵုတုဲဗမၞးပြောဟိတ်ဂှ် ဒးဒုၚ်အပၠေတ်ရ။” (ဇ—၃၃၂။ အစွောံ။) = “မင်းသည် ဘုရားလောင်းစကားကိုကြား၍ တရားသဖြင့်ဆုံးဖြတ်ရာ ပုရောဟိတ်ပုဏ္ဏားသည်သာ အပြစ်ဒဏ်ကိုခံရ၏။” || မိက်အပၠေတ် (ကြိ) လျော်ကြေးတောင်းသည်။ || “(ဗြဴတမ္ၚာသမၠီုဂှ် သေက်ဇဵုကဵုညး) ကျဂဗုတ်ညးရပ်ဒက်ပဘဲမိက်အပၠေတ် (တုဲ ဒးလေဲအပၠေတ်ကဵုညးရ။)” (ဇ—၁၃၉။ အစွောံ။) = “မိုက်မဲသောတံငါသည်မသည် သူတစ်ပါးအား ခိုက်ရန်ပြုရာ တရားရှုံး၍ ချုပ်နှောင်ဒဏ်ပေးရိုက်ပုတ်ခြင်းခံရပြီးနောက် တစ်ဖက်သောအမှုသည်က လျော်ကြေးတောင်း၍ လျော်ကြေးပေးလျော်လိုက်ရ၏။”')
,(16248,3,4,'လျော်ကြေးပေးလျော်သည်။','“ဍေံပပွစၞာဲတုဲ သၟိၚ်ဟွံစဳစတ်တုဲ ကဵုညးလေဲအပၠေတ်ကဵုဍေံရ။” (ဇ—၃၃၂။ အစွောံ။) = “သူလိမ်လည်လှည့်စားရာ မင်းသည်မစစ်ဆေးဘဲသူတစ်ဖက်သားအား လျော်ကြေးပေးလျော်စေ၏။”')
,(16249,3,1,'နတ်စိမ်း၏အမည်။','ကလော်အပၠေံ = နတ်စိမ်း။ တစ္ဆေ။')
,(16250,3,1,'သေသောက်ကြူး။ အရက်အိုး။ အရက်ချိုး။ အရက်ကို စွဲစွဲမြဲမြဲ အလွန်အကြူးသောက်သူ။ (ပါဠိ—သောဏ္ဍ)','“သောဏ္ဍဝါ။ ၚ်ညးလဗၚ်ဂမၠိုၚ်ကီု။ ဝါ။ ၚ်ညးအပၠေအ်အရက်ဂမၠိုၚ်ကီု။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)')
,(16251,3,1,'အဖော်။ တွဲဖက်တွဲဖော်။','“ဝုတ်အဖဴနာဲ၊ ဂၠာဲဟီုတသိ။” (လိက်ခၠေဝ်ရော်ဂုန်မိ) =“သင်ချစ်သား၏လက်တွဲဖော်သည် ဆိုညည်းမြည်တမ်း၏။”')
,(16252,3,1,'အသက်တူအရွယ်တူ။ အပေါင်းအဖော်။ တွဲဖော်တွဲဖက်။','“ညးမသၟဟ်မွဲ အဖက်ဇကုမဂွံဒှ်ပြောဟိတ်ဂှ် (သၟိၚ်) မအိုဟ်တၟိုဟ်စိုတ်ရောၚ်။” (ဇ—၄၂၂။ အစွောံ။) = “မင်းသည်ကား မိမိနှင့်အသက်အရွယ်တူသော အဖော်အဖက် ပုရောဟိတ်ဖြစ်သည်ကို ဝမ်းမြောက်လတ္တံ့။” || “နာဲသၟဟ်ကောန်ပၠ၊ ရအဖက်ကောန်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “သင်သည်ကားသားနှင့်တူမျှသော အဖော်အဖက်ပင်တည်း။”')
,(16253,3,1,'လိုက်ဖက်သည်။ လိုက်ဖက်ညီသည်။',NULL)
,(16254,3,1,'၁။ သတ်မှတ်ချိန်းဆိုထားသောအချိန်။ ရက်ချိန်း။','“စိုပ်အဖာတ်ဂိတုတ္ၚဲ သၟောဲလဝ်ဂှ်တုဲ ဨကရာဇ်ၜါက္ဍိုၚ်ဗ္တာၚ် သီုဗိုလ်လဗးဗွဲမဂၠိုၚ် ကၠုၚ်ကောံရၚ်သ္ကံ ပ္ဍဲပယဵုမုဟ်ရး။” (အကြီုရာဇာဓိရာဇ်) = “ချိန်းဆိုထားသော ရက်ချိန်းရောက်သောအခါ မင်းနှစ်ပါးတို့သည် စစ်သည်ဗိုလ်ပါများစွာဖြင့် တိုင်းစွန်နယ်ခြား­ တွေ့ဆုံကြ၏။” || “ထပှ်တ္ၚဲသွံ၊ စွံအဖာတ်ကၠာ။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “ရက်ချိန်းကို ခုနစ်ရက်သာ သတ်မှတ်ထားသည်။” || “စွံအဖာတ်ပြဲ၊ ထပှ်တ္ၚဲသၟဟ်။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။)')
,(16254,3,1,'၂။ အမှေး။ အမှေးခွံ။','အဖာတ်သရ = အနာအမှေးခွံ။')
,(16254,3,1,'၃။ အချိန်။ အခါ။','အဖာတ်နူဂယး = နံနက်ချိန်ခါ။ နံနက်ခင်း။ || အဖာတ်သဝ်တ္ၚဲ =ညနေချိန်ခါ။ ညနေခင်း။ || ‘ဖာတ်’ (ကြိ) လည်းရှု။')
,(16255,3,13,'(န) အဖော်။','“ကမၠက်လေဝ် အဖက်နွံ၊ အကဝ်လေဝ် အဖဝ်နွံ။” = “ၚကန်းမှာလည်း အဖက်ရှိသည်၊ ၚကျိုးမှာလည်း အဖော်ရှိသည်။” || “ဗောဓိသတ်ပိုဲက္တဵုဒှ်ကၞုဲ အဖဝ် (၅ဝဝ) ရ၊ သာ်ဝွံဟီုကဵုအဖဝ်ဂမၠိုၚ်ရ။” (ဇ—တေမဳ။ အစွောံ။) = “ဘုရားလောင်းသည် မျောက်မျိုး­ဖြစ်၍ အဖော် (၅ဝဝ) ရှိ၏။ အဖော်များအား ဤသို့ဆို၏။” || “ကောန်ၚာ်ဆတ္တဝ်၊ မွဲအဖဝ်ကၠာ။” (လိက်ဇိဝှစက္က) || “ဒးနရက်အဵု၊ သက်ကဵုအဖဝ်။” (သၠပတ်ပုံပမာ။ အစွောံ။) = “ငရဲကျ၍ အဖော်မဲ့၏။”')
,(16256,3,1,'(ချီလာသောစစ်တပ်၏) အရှည်အလျား။ စစ်မ။ စစ်ကြောင်း။','“သၟိၚ်လ္ဂန်အိန်အာလၟုဟ်ဂှ် ညာတ်ဆက္ဍိုပ်ပၞာန်ဟာ။ အဖၠဴပၞာန်ညာတ်ကီုဟာ” သၟိၚ်ဗြာဇ္ဇသၟာန်။ (အကြီုရာဇာဓိရာဇ်) = “လဂွန်းအိန်သွားစဉ်က စစ်ဦးစစ်ဖျားသာ မြင်သလား။ စစ်မကိုလည်းမြင်သလား” ဟုသမိန်ဗြာဇ္ဇကမေးလေ၏။ (ရာဇာဓိရာဇ်အရေးတော်ပုံကျမ်း။ နိုင်ပန်းလှ။)')
,(16257,3,11,'(န) ကျောက်သလင်း။ ဖလ်။ ဖန်။ (ပါဠိ—ဖလိက)','ပြာသာဒ်အဖၠိုက် = ဖလ်ပြာသာဒ်။ || “ပ္ဍဲတ္ကအ်ဂှ် ပြိုတ်ဗြဴပန် ဒၟံၚ်လတူပြာသာဒ်အဖၠိုက်ဂှ်။” (ဇ—၄၃၉။ အစွောံ။) =“ထိုကျွန်း­ လေးယောက်သောပြိတ္တာမတို့သည် ဖလ်ပြာသာဒ်ပေါ်­နေ၏။” || “ပ္ဍဲမ္ၚးဋ္ဌာန်ရသိဂှ်သၟိၚ်ဣန်ကတဵုဗဒှ် ပြာသာဒ်အဖၠိုက်မွဲတုဲ—။” (ဇ—၃၈ဝ။ အစွောံ။) = “သိကြားမင်းသည် —ထိုရသေ့၏ကျောင်းအနီး­ ဖန်ပြာသာဒ်ကိုဖန်ဆင်း၍—” (ညောင်ကန်) || ‘သုမ္မထိုက်’ (န) နှင့်အတူတူ။')
,(16258,3,1,'ငမိုက်သား။ လူ့ငနွား။',NULL)
,(16259,3,10,'(န) နာခြင်းမှကင်းဝေးခြင်း။',NULL)
,(16260,3,10,'(နဝိ) မလိမ္မာသော။ ပညာမရှိသော။','“ပူဂဵုမသ္ဒိုဟ်သ္ဒီု မဒှ်အဗျတ္တဂှ်—။” (ဇ—၂ဝ၂။အစွောံ။) = “မိုက်မဲသောပညာမရှိသောသူ။”')
,(16261,3,1,'ဝင်ကစွပ်ကောင်။',NULL)
,(16262,3,10,'(န) ဘေးမရှိခြင်း။ ဘေးမှကင်းဝေးခြင်း။',NULL)
,(16263,3,11,'(န) ဘေးမဲ့အလှူ။ (ပါဠိ—အဘယဒါန)','“ဒြာဲထဝ်ဝွံလေဝ် ဂွံအဘယဒါန်ရောၚ်။ မူဟိုတ်ဂွံကၠုၚ်သ္တိက်ဗ္ၚာဒၟံၚ်လဝ်ကအ် ပ္ဍဲဓနန်ဝွံပၠန်ရော” ဂြောဝ်ဂှ်ချပ်။ (ဇ—၁၂။ အစွောံ။) = စားတော်ချက်သည် ဘုရားလောင်း (သမင်မင်း) ကိုမြင်၍ “ဘေးမဲ့ကိုရပြီးသော သမင်မင်းသည်စဉ်းတီတုံး­အိပ်၏။ အကြောင်းအသို့တုံနည်း။” (ညောင်ကန်) || “ယွံမၞးတံ၊ ဟိုတ်သ္ဍိုက်ဒြာဲထဝ်နိဂြောဓတုဲ အဲကဵုလဝ်အဘယဒါန်တုဲရ” သၟိၚ်ဂး။ (ဇ—၁၂။ အစွောံ။) = “ကြည်ညိုသဖြင့် နိ ဂြောဓသမင်မင်းအား ဘေးမဲ့အဖြစ်ကိုပေးအပ်၏။” (ညောင်ကန်) || “ဗောဓိသတ် (သၟိၚ်ခဍာ်) တုန်— အာတ်အဘယဒါန်ကဵုသၟိၚ်ရ။ သၟိၚ်ကဵုအဘယဒါန်တုဲ ကဵုခဍာ်တံဂှ် ဒါန်လၟိုန်ဟေၚ်သၟိၚ်ကဵုရ။” (ဇ—၁၄ဝ။ အစွောံ။) = “ဘုရားလောင်းကျီးမင်းသည် မင်းအား ဘေးမဲ့အလှူကိုတောင်း၏။ မင်းသည် ကျီးအပေါင်းတို့ကို ဘေးမဲ့ပေး၍ ကျီးတို့အား နေ့စဉ်အစာကိုလှူ၏။”')
,(16264,3,11,'(န) အဘိညာဉ်။ ဈာန်ရပုဂ္ဂိုဟ်တို့၏ တန်ခိုးအမျိုးမျိုးဖန်ဆင်းနိုင်သော အသိဉာဏ်ထူး။',NULL)
,(16265,3,10,'(န) အဘိဓဇမဟာရဋ္ဌဂုရုဘွဲ့။ (အဂ္ဂမဟာပဏ္ဍိတဘွဲ့တံဆိပ် ရရှိပြီးဖြစ် ခြင်း၊ အနည်းဆုံးသိက္ခာတော် (၄ဝ) ရှိခြင်း၊ ဗဟုသုတအကြားအမြင်များခြင်း၊ ကျမ်းဂန်ရေးသားဖူးခြင်း စသည့်ဂုဏ်ထူးနှင့် ပြည့်စုံသောဆရာတော်အား အပ်နှင်းဆက်ကပ်သော ဘွဲ့တံဆိပ်တော်။)',NULL)
,(16266,3,11,'(န) အဘိဓါန်ကျမ်း။ (ပါဠိ—အဘိဓါန)',NULL)
,(16267,3,12,'(န) အဘိဓမ္မာတရား။',NULL)
,(16268,3,12,'(န) မိန့်ခွန်း။',NULL)
